export default [{"id":484,"question":"لو توضأ داخل الحمام هل يُبسمل؟","title":"ما حكم البسملة لمن يتوضأ داخل الحمام؟","answer":"الجواب: يقول: \"بسم الله\" عند بدء الوضوء، تزول الكراهة.\n(دروس شرح بلوغ المرام، كتاب الطهارة)","link":"https://binbaz.org.sa/fatwas/6243/ما-حكم-البسملة-لمن-يتوضا-داخل-الحمام","audio":"undefined","categories":["فروض الوضوء وصفته"]},{"id":842,"question":"التَّسمية عند الوضوء: هل هي مُستحبَّة أو واجبة؟","title":"ما حكم البسملة عند الوضوء؟","answer":"الجواب: الذي عليه جمهورُ أهل العلم أنها سنة مُؤكَّدة، وذهب بعضُ أهل العلم إلى وجوبها مع الذِّكْر، فإن سقطت ناسيًا أو جهلًا فلا بأس.\nومَن قال بوجوبها احتجَّ بما يُروى عنه ﷺ أنه قال: لا وضوءَ لمن لم يذكر اسم الله عليه، وهذا حديثٌ قال أحمد رحمه الله وجماعةٌ: إنه لا يثبت، فلهذا ذهب الجمهورُ إلى أنها سُنة، ومَن قال: إنه يصلح للاحتجاج؛ لكثرة طرقه وتعددها، ومن باب الحسن لغيره، قال بوجوب التَّسمية.\nوفي إمكان الاحتجاج به نظرٌ؛ لضعفه من جميع طرقه، لكن إذا أعاد الوضوء إذا تركها عمدًا ذاكرًا وأعاد الوضوء احتياطًا فحسن، وإلا فقول الجمهور أظهر: أنه لا تجب الإعادة، ويُستحب له التَّسمية، فإن تركها عامدًا مُتساهلًا لم يُعِد، وصحَّ وضوؤه، لكن لا ينبغي له أن يدعها، ينبغي له أن يحتاط، فإن تركها ناسيًا أو جاهلًا فلا شيء عليه.","link":"https://binbaz.org.sa/fatwas/20869/ما-حكم-البسملة-عند-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0664حكم البسملة عند الوضوء ؟ ابن باز فتاوى المحاضرات.mp3","categories":["فروض الوضوء وصفته"]},{"id":1127,"question":"إلى أي مكانٍ تمسح المرأةُ رأسها في الوضوء؟","title":"ما كيفية مسح المرأة رأسها في الوضوء؟","answer":"الجواب:\nالرجل مثل المرأة، هذه قاعدة الرجل والمرأة في الأحكام، سواء، إلا ما خصَّه الدليل، فما جاء في حقِّ الرجال يلزم النساء، وما جاء في حقِّ النساء يلزم الرجال، إلا ما خصَّه الدليل، واستثناه الدليل.\nوالوضوء في حقِّ الرجال والنساء سواء، تغسل وجهها ويديها مع المرفقين، وتمسح رأسها كله، من مُقدَّمه إلى مُؤخَّره، إلى منابت مُؤخَّره، أما أطراف العمائم فما هو بلزوم، فقط إلى المؤخر مثل الرجل، ثم تسمح أذنيها أيضًا، تُدخِل أصبعيها في الصماخين وتمسح بإبهاميها ظاهر الأذنين، وتغسل رجليها مع الكعبين كالرجل سواء.\nوهكذا في الغسل من الجنابة كالرجل، لكنها تختص بالحيض والنفاس، فعليها غسل الحيض والنفاس أيضًا. وتختص بأحكامٍ أخرى كما بيَّنه الله جلَّ وعلا في المواريث: للذكر مثل حظِّ الأُنثيين، وفي الشَّهادة المرأتان بشهادة رجلٍ، هذه أمور مُستثناة، وإلا فالأصل أن المرأة والرجل سواء في الأحكام، ما وجب على هذا وجب على هذا، وما وجب على هذا وجب على هذا، إلا ما خصَّه الدليل.","link":"https://binbaz.org.sa/fatwas/21176/ما-كيفية-مسح-المراة-راسها-في-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0972إلى أي مكان تمسح المرأة رأسها في الوضوء؟.mp3","categories":["فروض الوضوء وصفته"]},{"id":2369,"question":"ورد الوضوء مرة ومرتين وثلاثًا، ما الأفضل؟","title":"ما السُّنة في عدد الوضوء وحكم التنشيف؟","answer":"الجواب:\nالواجب مرة، يسبغ الوضوء على العضو الوجه واليدين، ومسح الرأس مرة مع الأذنين والرجلين مرة، هذا الواجب، أما إذا كان كرر ثنتين فهو أفضل، كرر ثلاث فهو أفضل ما عدا الرأس والأذنين مسحة واحدة، النبي ﷺ توضأ مرة مرة، وتوضأ مرتين مرتين، وتوضأ ثلاثًا ثلاثًا؛ ليبيِّن الجواز ويبيِّن الكمال، مرتين مرتين وسط، ثلاثًا ثلاثًا هو الكمال، مرة مرة هو أقل الواجب.\nوإن غاير بينها كأن غسل بعضها مرة وبعضها مرتين وبعضها ثلاثًا؛ كله لا بأس.\nس: أعضاؤه ينشّفها أو يجعلها بغير تنشيف؟\nالشيخ: الأمر واسع، التنشيف سهل، إن نشف فلا بأس، وإن ترك فلا بأس.\nس: تَرْك الرسول ﷺ للتنشيف ألا يدل على الكراهة؟\nالشيخ: ذاك تركه في الغسل، أما الوضوء ما ثبت فيه شيء، ما نعلم فيه شيئًا، أما الغسل تَرْكُه أفضل، ترك التمسح بمنديل أفضل في الغسل غسل الجنابة.","link":"https://binbaz.org.sa/fatwas/22494/ما-السنة-في-عدد-الوضوء-وحكم-التنشيف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الأفضل في الوضوء، وحكم تنشيف أعضاء الوضوء.mp3","categories":["فروض الوضوء وصفته"]},{"id":2447,"question":"أحد الأخوة مصاب بحساسية في أنفه ويصعب عليه الاستنشاق يقول: فهل لي أن أبل أصابعي بالماء وأدخلها في الأنف يكفي؟","title":"كيف يستنشق المصاب بحساسية في أنفه؟","answer":"الجواب:\nإذا كان يؤلمه يتيمّم ولا يُعرِّضها للماء إذا كان يضره الماء.\nس: بس ممكن يدخل أصابعه؟\nالشيخ: لا، المس ما ينفع، لا بدّ من الاستنشاق بالماء، لكن إذا كان ما يستطيع يتيمم، إذا فرغ من الوضوء يتيمم بالنية عن الأنف إذا كان يَضُرُّه الماء.","link":"https://binbaz.org.sa/fatwas/22576/كيف-يستنشق-المصاب-بحساسية-في-انفه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مصاب بحساسية في أنفه فكيف يستنشق.mp3","categories":["فروض الوضوء وصفته"]},{"id":2476,"question":"المسح على الجبيرة هل يجزئ أم لابد من التيمّم؟","title":"هل يجزئ المسح على الجبيرة دون تيمّم؟","answer":"الجواب:\nالصواب يجزئ المسح، ما حاجة للتيمم، المسح يقوم مقام الغَسْل، إذا كان عليه جبيرة يمسح عليها مثل ما يجوز المسح على الخف.","link":"https://binbaz.org.sa/fatwas/22605/هل-يجزى-المسح-على-الجبيرة-دون-تيمم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجزئ المسح على الجبيرة.mp3","categories":["فروض الوضوء وصفته"]},{"id":3589,"question":"امرأة صلت وقد وضعت على أظفار رجليها مناكير وتوضأت وصلت أسبوعًا كاملًا وهي لم تُزل هذه المناكير وهي ناسية فهل تعيد؟","title":"حكم صلاة مَنْ صلت وعلى أظفارها مناكير؟","answer":"الجواب: نعم، إذا كانت المناكير ساترة تحكها تزيلها وتعيد الوضوء والصلاة؛ لأنها ساترة.\nس: تعيد أسبوعًا كاملًا؟\nالشيخ: نعم.\nس: كيف تعيد فروض الأسبوع؟\nالشيخ: مرتبة كل يوم لحاله.\nس: فرض مع فرض؟\nالشيخ: لا، كل يوم لحاله تسردها ولو في ساعة واحدة أو ليلة واحدة.","link":"https://binbaz.org.sa/fatwas/23771/حكم-صلاة-من-صلت-وعلى-اظفارها-مناكير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من صلت وعلى أظفارها مناكير.mp3","categories":["فروض الوضوء وصفته"]},{"id":3795,"question":"المضمضة سنة؟","title":"هل المضمضة بعد الأكل سُنة؟","answer":"الجواب: أفضل، مستحب، كما فعل النبي ﷺ؛ لأجل تُجلي الأثر الذي في الفم؛ لئلا يؤذي وهو في الصلاة.","link":"https://binbaz.org.sa/fatwas/23994/هل-المضمضة-بعد-الاكل-سنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المضمضة بعد الأكل.mp3","categories":["فروض الوضوء وصفته"]},{"id":3892,"question":"في الوضوء لو قدَّم اليُسرى على اليُمنى؟","title":"حكم تقديم اليُسرى على اليُمنى في الوضوء","answer":"الجواب: الصواب أنه لا يجوز، وفيه خلافٌ مشهور: الأكثر يرون أنه من باب الاستحباب، ولكن مواظبة النبي ﷺ على تقديم اليمين في يديه ورجليه -وهو المفسِّر لما أُجمل في القرآن- يقتضي ترجيح قول مَن قال بوجوب التيامن في هذا، وفي حديث أبي هريرة: إذا لبستُم وتوضَّأتُم فابدؤوا بميامنكم.\nالحاصل أن الرسول ﷺ فسَّر الآية في قوله جلَّ وعلا: يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا قُمْتُمْ إِلَى الصَّلَاةِ فَاغْسِلُوا وُجُوهَكُمْ وَأَيْدِيَكُمْ إِلَى الْمَرَافِقِ وَامْسَحُوا بِرُءُوسِكُمْ وَأَرْجُلَكُمْ إِلَى الْكَعْبَيْنِ [المائدة:6]، فعمله تفسير لهذا عليه الصلاة والسلام، وقد بدأ باليمين في يديه، وبدأ باليمين في رجليه، فالواجب الأخذ بذلك.","link":"https://binbaz.org.sa/fatwas/24108/حكم-تقديم-اليسرى-على-اليمنى-في-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم تقديم اليُسرى على اليُمنى في الوضوء.mp3","categories":["فروض الوضوء وصفته"]},{"id":3906,"question":"فعل أبي هريرة (مبالغته في غسل اليدين) إذا فعله أحدُهم؟","title":"حكم المبالغة في غسل اليدين في الوضوء","answer":"الجواب: الذي يظهر لي أنه بدعة؛ لأن الشيء الذي ما له أصل، كون الصحابي اجتهد..... ما يكون حجة، مثل: فعل ابن عمر في أخذ ما زاد على القبضة من اللحية، وفعل ابن عمر في غسل عينيه، فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ [النساء:59]، هذا عام، إلا ما جاء عن الخلفاء الراشدين فهو من السنة إذا لم يُخالف سنة صحيحة صريحة.","link":"https://binbaz.org.sa/fatwas/24123/حكم-المبالغة-في-غسل-اليدين-في-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مبالغة أبي هريرة في غسل اليدين، ما الحكم إذا فعله أحدُهم.mp3","categories":["فروض الوضوء وصفته"]},{"id":4233,"question":"غسل الأعضاء أكثر من ثلاثة جائز؟","title":"حكم غسل الأعضاء أكثر من ثلاث في الوضوء","answer":"الجواب: لا، ما ينبغي، أقل شيء الكراهة، ثلاثة فقط، السنة ثلاثة فأقل؛ الوجه ثلاث واليدين ثلاث والأرجل كذلك، أما الرأس مسحة واحدة، هذه السنة؛ لا يزيد على ثلاث، في بعض الروايات من زاد فقد أساء وتعدى وظلم فالسنة ثلاث فأقل في الوضوء.","link":"https://binbaz.org.sa/fatwas/24500/حكم-غسل-الاعضاء-اكثر-من-ثلاث-في-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم غسل الأعضاء أكثر من ثلاث.mp3","categories":["فروض الوضوء وصفته"]},{"id":4441,"question":"الاستنشاق مرة واحدة كافٍ؟","title":"هل يصح الاكتفاء بمرة واحدة في الوضوء؟","answer":"الجواب: نعم.\nس: وغسل يده مرةً كافٍ؟\nج: نعم.\nس: ورجله كذلك؟\nج: نعم، والموالاة، الصحيح لا بد من الموالاة والترتيب، يبدأ بالوجه، ثم اليدين، ثم الرأس، ثم الرجلين، ويُوالي بينها، ولهذا أمر مَن تركه معه أن يُعيد الوضوء عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/24719/هل-يصح-الاكتفاء-بمرة-واحدة-في-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألةٌ الاستنشاق وغسل اليد والرجل مرة واحدة في الوضوء.mp3","categories":["فروض الوضوء وصفته"]},{"id":4442,"question":"غسل اليدين قبل الوضوء؟","title":"حكم غسل اليدين قبل الوضوء","answer":"الجواب: السنة ثلاثًا، إلا من النوم، فالظاهر أن السنة الوجوب، إذا قام من نوم الليل وجب أن يغسلها ثلاثًا؛ لأنَّ فيها أوامر ونواهٍ، فالأفضل الأخذ بها، والقول بوجوبها؛ لأنَّ هذا هو الأصل في الأوامر والنواهي –الوجوب- فذهب الجمهورُ إلى أنها سنة كبقية الأوامر في الوضوء، ولكن ما ورد في غسل اليدين عند القيام من النوم فواضح في الوجوب، فينبغي للمؤمن أن يغسلها ثلاثًا قبل أن يُدخلها في الإناء، أما في النهار ونوم النهار فالأمر أوسع.\nوبكل حال إذا قام من النوم حتى في النهار ينبغي أن يغسلها ثلاثًا؛ لأنَّ بعض أهل العلم ألحق نوم النهار بنوم الليل على ظاهر بعض الأحاديث، أما إذا كان على غير النوم فهي سنة، إن شاء ثلاثًا مطلقًا سنة.","link":"https://binbaz.org.sa/fatwas/24720/حكم-غسل-اليدين-قبل-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم غسل اليدين قبل الوضوء.mp3","categories":["فروض الوضوء وصفته"]},{"id":4443,"question":"السنة أن يستنشق باليمين ويستنثر باليُسرى؟","title":"ما السُّنة في صفة الاستنشاق والاستنثار؟","answer":"الجواب: كذلك السنة أن يستنشق باليمين؛ لأن الاستنشاق عبادة مقصودة، والانتثار إزالة للأذى، الاستنشاق باليمين، والاستنثار يكون باليسار، هذا هو الأفضل.","link":"https://binbaz.org.sa/fatwas/24721/ما-السنة-في-صفة-الاستنشاق-والاستنثار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/السنة أن يستنشق باليمنى ويستنثر باليُسرى.mp3","categories":["فروض الوضوء وصفته"]},{"id":4444,"question":"إدخال الأصبع في الفم عند المضمضة؟","title":"حكم إدخال الأصبع في الفم عند المضمضة","answer":"الجواب: لا، ما هو لازم، المضمضة تكفي، إنما الاستنان؛ وهو أن يستن بالسواك، هذا أفضل، أو بإصبعه أفضل، هذا ما هو لازم، فإذا أدخل الماء ثم ألقاه كفى.\nس: يُدخل الأصابع اليُمنى أو اليُسرى في الفم؟\nج: اليُسرى بارك الله فيك؛ لأنَّه من باب جهة الأذى، من باب جهة الوسخ.","link":"https://binbaz.org.sa/fatwas/24722/حكم-ادخال-الاصبع-في-الفم-عند-المضمضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إدخال الأصبع في الفم عند المضمضة.mp3","categories":["فروض الوضوء وصفته"]},{"id":4445,"question":"مسح الأذنين مع الوجه أو بعد الرأس؟","title":"متى يكون مسح الأذنين في الوضوء؟","answer":"الجواب: مع الرأس بارك الله فيك؛ لأنَّ الأذنين من الرأس.","link":"https://binbaz.org.sa/fatwas/24723/متى-يكون-مسح-الاذنين-في-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/متى يكون مسح الأذنين في الوضوء.mp3","categories":["فروض الوضوء وصفته"]},{"id":4446,"question":"مسح القفا يا شيخ؟","title":"حكم مسح القفا والعنق في الوضوء","answer":"الجواب: أما القفا فلا يُشرع، الحديث ضعيف، حديث طلحة بن مصرف هذا حديث ضعيف لا تقوم به الحُجَّة، ولا يمسح العنقَ، إنما المسح في الرأس، وأما طلحة بن مصرف هذا فهو ضعيف.\nس: المسح مرة واحدة؟\nج: مرة واحدة نعم.","link":"https://binbaz.org.sa/fatwas/24724/حكم-مسح-القفا-والعنق-في-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في مسح الرأس ومسح القفا.mp3","categories":["فروض الوضوء وصفته"]},{"id":4447,"question":"ما رُوي عن بعض الصحابة كابن عمر وغيره: عدم المُوالاة بين أعضاء الوضوء؟","title":"هل صح شيء في عدم المُوالاة في الوضوء؟","answer":"الجواب: ما أعرف الصحة، أقول: ما أذكر فيها صحَّة، غير صحيح.  ولو وُجد فهو محجوج بسنة النبي ﷺ، أقول: لو وُجد صحيحًا عن بعض السلف، أو عن بعض السلف، فهو محجوجٌ بفعل النبي ﷺ، فإنه يُفسره القرآن، ويُبيِّنه عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/24725/هل-صح-شيء-في-عدم-الموالاة-في-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل رُوي عن بعض الصحابة عدم المُوالاة بين أعضاء الوضوء.mp3","categories":["فروض الوضوء وصفته"]},{"id":4448,"question":"العمامة مربوطة أو ..؟","title":"حكم وكيفية المسح على العمامة عند الوضوء","answer":"الجواب: هكذا عادتهم ..... يُسوّنها مُحنَّكة، إذا كانت ما هي مُحنَّكة لا يُمسح عليها، إذا كان هذا مجرد عصابة ما تكفي، نعم.\nس: التَّحنيك لا بدّ منه؟\nج: هذا هو الأرجح؛ لأنه هو الذي فيه الصعوبة والمشقة، أما إذا كانت غير محنكة فليس فيه صعوبة في إزالتها ومسح ما تحتها.\nس: يشترط لبسها على طهارة؟\nج: نعم، مثلها مثل الخفّ سواء.\nس: التوقيت كذلك؟\nج: نعم؛ لأنها مثل الخفّ سواء.\nس: بالنسبة للمسح على الرأس: إذا كان الإنسانُ مثلًا لبس العمامة، ولم يبدُ شيئًا من ناصيته، هل يكفي لمجرد المسح؟\nج: يكفي المسح، إذا ستر الرأس كله كفى المسح.\nس: هل يُشترط في المسح على العمامة أن تُغطي الرأسَ كله؟\nج: لا، ما هو بشرط، إذا ما غطت الرأس يمسح ما ظهر.","link":"https://binbaz.org.sa/fatwas/24726/حكم-وكيفية-المسح-على-العمامة-عند-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في المسح على العمامة عند الوضوء.mp3","categories":["فروض الوضوء وصفته"]},{"id":4451,"question":"المُوالاة في الوضوء؟","title":"حكم المُوالاة في الوضوء","answer":"الجواب: وأما الموالاة فقد تقدَّم أنها لا بدّ منها، وأنها فرضٌ من فروض الوضوء، ولهذا جاء في عدة أحاديث أنه ﷺ رأى في قدم بعض الناس لمعة قدر الظفر، وبعضها قدر الدرهم، فأمره أن يُعيد، حديث خالد بن معدان هذا جيد، وهكذا حديث عمر، وهكذا حديث أنس، كلها صحيحة، فهي دالة على وجوب الموالاة، وأنها فرض؛ لأنها لو كانت غير فرضٍ لأمره أن يغسل اللمعة واكتفى، فلما أمره أن يُعيد الصلاة والوضوء دلَّ على أنه لا بدّ من الموالاة في الوضوء. ولأنه ﷺ توضأ مواليًا وقال: هكذا الوضوء، فوجب علينا أن نتوضأ كما توضأ؛ ولأن فعله تفسير لكلام الله، لقوله سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا قُمْتُمْ إِلَى الصَّلَاةِ فَاغْسِلُوا وُجُوهَكُمْ [المائدة:6]، فتفسيره ﷺ يُبين المعنى، ويُوضح الوضوء، فالواجب أن يكون الوضوء مُرتبًا كما رتَّبه الله، وكما رتَّبه النبي ﷺ، والواجب أيضًا أن يكون مُتواليًا، لا يُفرق بينه، بل مُتواليًا التَّوالي المعتاد؛ بحيث يغسل كل العضو قبل أن يجفَّ الذي قبله.","link":"https://binbaz.org.sa/fatwas/24729/حكم-الموالاة-في-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم المُوالاة في الوضوء.mp3","categories":["فروض الوضوء وصفته"]},{"id":4452,"question":"المعونة في الوضوء؟","title":"هل تجوز المعونة في الوضوء؟","answer":"الجواب: وأمر المعونة في الوضوء لا بأس بها، المتوضئ يصبّ عليه بعضُ الناس، كما فعل المغيرةُ وغيره، فهذا لا بأس به، وهذا ثابتٌ عن النبي ﷺ، فإذا صبَّ عليك غيرُك من إناءٍ أو غيره ليُعينك على ما شرع الله من الوضوء فلا بأس بذلك، كما فعله المصطفى عليه الصلاة والسلام في حديث المغيرة، وفي حديث أبي أمامة، وأبي ذر، وغيرهم.\nس: إذا دخل المُعين غسل بعض الأعضاء؟\nج: لا بأس، إذا نوى المعان صار المعينُ كالآلة، لكن الأولى أن المتوضئ يُباشر، كما فعله النبيُّ ﷺ، فالمعان يُباشر، والمعين يصبّ، لكن لو قدّر أنَّ المعان في علّة المريض ونحو ذلك فإنَّ غسل غيره يكفي مع نيته، فإذا غسل غيره وجهه، وغسل يديه، ومسح رأسه، وغسل رجليه، فهذا لا بأس به؛ لأن بعض الناس قد تتعطل يداه، أو ...؛ فلا حرج أن يُعينه أخوه أو زوجته أو نحو ذلك.\nس: مباشرة إعانة غير محتاج؟\nج: تصحّ، النبي ﷺ ما هو محتاج، وأعانه أبو هريرة.\nس: مُباشرة غسل أعضائه؟\nج: القاعدة لا بأس به، لكن كونه يُباشر أفضل.","link":"https://binbaz.org.sa/fatwas/24730/هل-تجوز-المعونة-في-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم المعونة في الوضوء.mp3","categories":["فروض الوضوء وصفته"]},{"id":4453,"question":"حكم الوضوء في الحمام؟","title":"حكم الوضوء في الحمام","answer":"الجواب: لا بأس به إذا دعت الحاجةُ إليه، لا بأس بالوضوء في الحمام، لكن يقول الشهادة إذا خرج، إذا خرج سهل.","link":"https://binbaz.org.sa/fatwas/24731/حكم-الوضوء-في-الحمام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الوضوء في الحمام.mp3","categories":["فروض الوضوء وصفته"]},{"id":4455,"question":"الفصل بين المضمضة والاستنشاق هل ورد فيها شيء؟","title":"هل تُفصل المضمضة عن الاستنشاق بالوضوء؟","answer":"الجواب: عدم الفصل أفضل، كان النبيُّ ﷺ لا يفصل المضمضة والاستنشاق، بغرفةٍ واحدةٍ إذا تيسر أفضل.","link":"https://binbaz.org.sa/fatwas/24733/هل-تفصل-المضمضة-عن-الاستنشاق-بالوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل ثبت شيء في الفصل بين المضمضة والاستنشاق.mp3","categories":["فروض الوضوء وصفته"]},{"id":4788,"question":"حديث البسملة في الوضوء، طرقه ضعيفة كلها؟","title":"ما صحة حديث البسملة في الوضوء؟","answer":"لكن حسّنه بعضهم، أي من باب الحسن لغيره، كابن الصلاح وجماعة، وكابن كثير - رحمه الله - في التفسير قال: من باب الحسن. كما في تفسير سورة المائدة.","link":"https://binbaz.org.sa/fatwas/25156/ما-صحة-حديث-البسملة-في-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على حديث البسملة في الوضوء.mp3","categories":["فروض الوضوء وصفته","الحكم على الأحاديث"]},{"id":4926,"question":"ظاهر الأذنين؟","title":"حكم وكيفية مسح ظاهر الأذنين والصّدغين","answer":"الجواب: السنة ألا يأخذ، السنة أن يكون الأذنان تابعتين للرأس، هذا هو الأفضل، فلا يحتاج إلى ماءٍ جديدٍ، المحفوظ أنه أخذ لرأسه ماءً جديدًا غير فضل يديه، وإن كان ابنُ عمر يأخذ للأذنين ماءً جديدًا، ولكن الأفضل عدم ذلك، إلا إذا يبست يداه، كان الماء قليلًا يبست يداه، يأخذ لأذنيه ماءً جديدًا لا بأس، أما ما زال الماء في يديه والرطوبة موجودة فيمسحهما مع رأسه، هذا هو السنة.\nس: المراد بظاهر الأُذنين الذي يمسح .....؟\nج: الذي فوق...\nس: مما يلي الصّماخ؟\nج: مما يلي الرأس.\nس: والذي يلي الصّماخ؟\nج: ما له تعلق، الممسوح الصّماخين وما فوق... مما يلي الرأس، هذا هو الظاهر، ظاهر الأذنين.\nس: مسح الصّدغين؟\nج: الصّدغين تبع الرأس.","link":"https://binbaz.org.sa/fatwas/25815/حكم-وكيفية-مسح-ظاهر-الاذنين-والصدغين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسح ظاهر الأذنين والصدغين.mp3","categories":["فروض الوضوء وصفته"]},{"id":4994,"question":"إذا احتاج الوضوء إلى أكثر من ثلاث غسلات يعتبر اعتداء؟","title":"حكم الزيادة على ثلاث في الوضوء","answer":"الجواب: هذا إذا كان عليه شيء يزيله ثم يشرع في الوضوء، إن كان عليه طين أو شيء يزيله قبل، يتخلص منه لا بدّ، يزيل الأثر ما هو باعتداء، لا بد يزيله، يكون ثلاثًا لأجل الوضوء، ما هو لأجل إزالة الأذى،..... إما عجين أو قروح تمنع الماء أو..... يزيلها، وإلا شيء طين وإلا شيء آخر؛ لا بدّ يزيله؛ حتى يحصل له فضل الوضوء ثلاثًا، أو الثنتين.","link":"https://binbaz.org.sa/fatwas/28676/حكم-الزيادة-على-ثلاث-في-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الزيادة على ثلاث في الوضوء.mp3","categories":["فروض الوضوء وصفته"]},{"id":5300,"question":"هل الحديث أثناء الوضوء في كلام الدنيا مكروه؟","title":"ما حكم الكلام الدنيوي أثناء الوضوء؟","answer":"الجواب: ما نعلم فيه شيئًا، الكلام في بيع أو شراء ما فيه شيء، يُكره في المساجد، أما كونه يتوضأ ويكلم أحدًا ما نعلم فيه شيئًا إذا كان مباحًا.[1]","link":"https://binbaz.org.sa/fatwas/30950/ما-حكم-الكلام-الدنيوي-اثناء-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 020.mp3","categories":["فروض الوضوء وصفته"]},{"id":5561,"question":"تخليل الأصابع واجب؟","title":"ما حكم تخليل الأصابع في الوضوء؟","answer":"الجواب: نعم. س: ذكر أنه من المُستحبَّات؟ ج: وخلل بين الأصابع أمر من النبي ﷺ، إذا كان يخشى من عدم وصول الماء يُخلل، أما إذا تيقن وصول الماء صار التَّخليل مستحبًّا، خلل بين الأصابع: يعني مُستحبًّا إذا كان الماء يصل، أما لو كان الماءُ لا يصل وجب التَّخليل. س: هنا أطلق؟\nج: هذا غلط، لا بدَّ من التفصيل؛ لأنَّ بعض المرات الأصابع تكون متلاصقةً، يكون بينها أشياء، فلا بدَّ من التخليل، خصوصًا أصابع الرِّجلين، وقد يقع في أصابع اليدين، قد يكون بينها شيء، لكن إذا كانت سليمةً لا بأس، يكون مُستحبًّا.[1]","link":"https://binbaz.org.sa/fatwas/31513/ما-حكم-تخليل-الاصابع-في-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 001.mp3","categories":["فروض الوضوء وصفته"]},{"id":5562,"question":"الدلك في الغسل والوضوء؟","title":"ما حكم الدلك في الغسل والوضوء؟","answer":"الجواب: نعم الدَّلك مستحب، ليس بواجبٍ، جاء في بعض الأحاديث أنَّ النبي كان يدلك ذراعيه ﷺ، فلا بأس إذا دلك من باب الاستحباب، لكن الغالب -غالب فعل النبي ﷺ- ليس فيه دلك، يمر الماء فقط؛ لأنها أرفق بالمسلمين، فمرور الماء يكفي، وإذا دعت الحاجةُ إلى الدلك فلا بأس. س: في الغسل كذلك؟ ج: وفي الغسل كذلك إذا مرَّ الماء كفى على البدن كله، وإن وجد أشياء تحتاج إلى دلكٍ دَلَكَ: كمحلٍّ فيه طين، فيه عجين، فيه أشياء يُزيلها، يدلكها حتى تزول.[1]","link":"https://binbaz.org.sa/fatwas/31514/ما-حكم-الدلك-في-الغسل-والوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 002.mp3","categories":["الغسل","فروض الوضوء وصفته"]},{"id":5566,"question":"إذا غسل يديه ورجليه خرّت خطاياه مع الماء أو مع آخر قطر الماء، يدل على أنَّ الأفضل عدم التنشيف لخرور الخطايا؟","title":"ما حكم التنشيف في الوضوء والغسل؟","answer":"الجواب: خرور الخطايا هذا عند الغسل، وهذا بعد ذلك، عند غسله تخرّ الخطايا مثلما في الحديث، لكن إن تنشف بعد ذلك هذه رطوبة باقية. س: التنشيف ما ثبت إلا في الغسل فقط؟ ج: المعروف في الغسل من حديث ميمونة. س: في الحديث الثاني، هذا يقول: لم يكن النبي ﷺ يعتاد تنشيف أعضائه بعد الوضوء ولا صح عنه في ذلك حديث البتة، بل الذي صح عنه خلافه؟ ج: ما أعلم في هذا شيئًا، لا التنشيف، ولا عدمه، إنما جاء في الغسل: أتته بمنديل فردَّه وجعل ينفض الماء بيديه، وأما في الوضوء ما أحفظ فيه شيئًا، الأمر فيه واسع. س: في الغسل الأفضل عدم التَّنشيف؟ ج: هذا هو، نعم، ينفض الماء بيديه مثلما في حديث ميمونة في الصحيح. س: وجعل ينفض الماء بيديه؟ ج: هذا السنة. س: نفض الماء، ما تخلص منه؟ ج: هذا السنة، نفض الماء بيديه وعدم التَّمسح.[1]","link":"https://binbaz.org.sa/fatwas/31518/ما-حكم-التنشيف-في-الوضوء-والغسل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 006.mp3","categories":["فروض الوضوء وصفته","الغسل"]},{"id":5567,"question":"مسح الرأس مرة بدون إرجاعٍ؟","title":"حكم مسح الرأس في الوضوء بدون إرجاعٍ؟","answer":"الجواب: ليس بلازمٍ، جاءت أنواع في المسح، المهم مسح الرأس ويكفي، سواء ردَّها أو ما ردَّها، أو بدأ بوسط الرأس وذهب به إلى قفاه، ثم إلى مقدمه، الأمر واسع، لكن الأفضل أن يبدأ بالمقدم، ثم يذهب به إلى قفاه، ثم يعود إلى مقدمه، هذا هو الأفضل.[1]","link":"https://binbaz.org.sa/fatwas/31519/حكم-مسح-الراس-في-الوضوء-بدون-ارجاع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 007.mp3","categories":["فروض الوضوء وصفته"]},{"id":5666,"question":"هل يصح أن أغسل بعض الأعضاء ثلاث مرات، وبعضها مرتين؟","title":"ما حكم تفاوت عدد غَسل الأعضاء في الوضوء؟","answer":"الجواب: لا حرج أن يغسل بعض الأعضاء مرتين، وبعضها ثلاثًا، وبعضها مرةً، وبعضها مرتين، النبي توضأ مرةً مرةً، ومرتين مرتين، وثلاثًا ثلاثًا، وغسل بعض الأعضاء مرتين، وبعضها ثلاثًا عليه الصلاة والسلام. فإذا غسل وجهه ثلاثًا، وكل يدٍ مرتين، أو غسل رجليه ثلاثًا أو مرتين؛ لا حرج. لكن الأفضل ثلاثًا ثلاثًا: أن يغسل وجهه ثلاثًا، ويديه ثلاثًا، هذا الأفضل، يمسح رأسه مرةً واحدةً، الرأس مرة واحدة، لا يُكرر المسح.[1]","link":"https://binbaz.org.sa/fatwas/31703/ما-حكم-تفاوت-عدد-غسل-الاعضاء-في-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aldurus almuhima 012.mp3","categories":["فروض الوضوء وصفته"]},{"id":6039,"question":"هل الاسم، والتشهد في الحمام عند الوضوء حرام، أم حلال؟","title":"حكم التلفظ بالتسمية والشهادتين للمتوضئ داخل الحمام","answer":"الجواب: ينبغي له إذا توضأ أن يكون تشهده خارج الحمام أفضل؛ لأن الحمام محل قذر، فكونه يتوضأ، ويخرج، ثم يتشهد، يقول: أشهد أن لا إله إلا الله وحده لا شريك له، وأشهد أن محمدًا عبده ورسوله بعد خروجه من الحمام، هذا الذي ينبغي، يكره في داخل الحمام؛ لأنه لا ضرورة إلى ذلك، بإمكانه أن يصبر حتى يخرج. أما التسمية عند بدء الوضوء؛ إذا كان وضوؤه في الغسالات الداخلية؛ فلا حرج؛ لأن التسمية واجبة عند جمع من أهل العلم، فلا يترك الواجب لأجل الكراهة، الكراهة لا تسقط الواجب.  فإذا كان مغتسله من داخل؛ سمى عند الوضوء، ولا يضر، ولا كراهة في ذلك؛ لأن التسمية واجبة عند جمع من أهل العلم، أما إذا تيسر أن يكون الوضوء خارج الحمام؛ فهذا حسن، حتى يسمي خارج الحمام، ولكن إذا كانت -مثل ما هو معروف الآن- موضع الغسل يكون داخل الحمام؛ فإنه يسمي عند بدء الوضوء، عندما يغسل يديه في الوضوء، ويسمي، ولا حرج في ذلك، ولا كراهة؛ لأن التسمية واجبة عند جمع من أهل العلم.","link":"https://binbaz.org.sa/fatwas/1450/حكم-التلفظ-بالتسمية-والشهادتين-للمتوضى-داخل-الحمام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_378.mp3","categories":["فروض الوضوء وصفته","الأدعية والأذكار"]},{"id":6161,"question":"إذا مات إنسان وهو جنب، هل تجزئه غسلة واحدة، أم غسلتين؟","title":"حكم جمع أكثر من نية في غسل واحد","answer":"الجواب:  بسم الله الرحمن الرحيم ، اللهم صل وسلم على رسول الله، وعلى آله، وأصحابه، ومن اهتدى بهداه، أما بعد: فهذا يسأل عن الميت إذا كان جنبًا، هل يغسل مرتين، أم يكفي غسل واحد؟  والجواب: أنه يكفي غسل واحد ينويه الغاسل عن الجنابة، وعن الموت جميعًا، كما لو حاضت المرأة، وعليها جنابة، ثم اغتسلت بعد الحيض بنية الحيض، والجنابة. فالمقصود: أن هذا يكفي غسل واحد بنية واحدة، الغاسل ينوي هذا وهذا، ينوي الجنابة، وينوي الموت، ويكفي.","link":"https://binbaz.org.sa/fatwas/1608/حكم-جمع-اكثر-من-نية-في-غسل-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_502.mp3","categories":["فروض الوضوء وصفته","الغسل"]},{"id":6483,"question":"يقول أحد العلماء: المسح على الرأس بالماء مرة واحدة، وآخر يقول: ثلاث مرات، فما الصواب؟","title":"الصواب في عدد مسح الرأس أثناء الوضوء","answer":"الجواب: الصواب: مرة واحدة، كان النبي يمسح مسحة واحدة -عليه الصلاة والسلام- يبدأ بمقدم رأسه إلى قفاه، ثم يردهما إلى المكان الذي بدأ منه، هذا السنة، أما ما يروى في بعض الروايات أنه مسح ثلاثًا؛ فهو ضعيف، لا يصح عن النبي ﷺ المحفوظ مسحة واحدة، هكذا جاءت الأحاديث الصحيحة عن رسول الله ﷺ مسح الرأس يمسح واحدة، والأفضل أن يكون يبدأ بمقدم الرأس، ثم يذهب بيديه إلى قفاه، ثم يردهما إلى المكان الذي بدأ منه، وفق الله الجميع.","link":"https://binbaz.org.sa/fatwas/2243/الصواب-في-عدد-مسح-الراس-اثناء-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_864.mp3","categories":["فروض الوضوء وصفته","الأدعية والأذكار"]},{"id":6498,"question":"يقول أحد العلماء: المسح على الرأس بالماء مرة واحدة، وآخر يقول: ثلاث مرات، فما الصواب؟","title":"الصواب في عدد مسح الرأس أثناء الوضوء","answer":"الجواب: الصواب: مرة واحدة، كان النبي يمسح مسحة واحدة -عليه الصلاة والسلام- يبدأ بمقدم رأسه إلى قفاه، ثم يردهما إلى المكان الذي بدأ منه، هذا السنة، أما ما يروى في بعض الروايات أنه مسح ثلاثًا؛ فهو ضعيف، لا يصح عن النبي ﷺ المحفوظ مسحة واحدة، هكذا جاءت الأحاديث الصحيحة عن رسول الله ﷺ مسح الرأس يمسح واحدة، والأفضل أن يكون يبدأ بمقدم الرأس، ثم يذهب بيديه إلى قفاه، ثم يردهما إلى المكان الذي بدأ منه، وفق الله الجميع.","link":"https://binbaz.org.sa/fatwas/2243/الصواب-في-عدد-مسح-الراس-اثناء-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_864.mp3","categories":["فروض الوضوء وصفته","الأدعية والأذكار"]},{"id":6747,"question":"هل يجوز مسح الوضوء، أم تركه أفضل؟ وإذا أقيمت الصلاة والإنسان في نافلة، فماذا يصنع؟","title":"حكم التنشيف بعد الوضوء وبعد الغسل من الجنابة","answer":"الجواب: الأمر واسع، من نشف؛ فلا بأس، ومن ترك؛ فلا بأس، فلم يجيء في هذا شيء صحيح فيما نعلم، لا في التنشيف ولا في كراهة التنشيف، الأمر فيه واسع. أما غسل الجنابة فقد ورد عن النبي ﷺ أنه عرض عليه المنديل؛ فرده، وجعل ينفض الماء بيده، في غسل الجنابة -عليه الصلاة والسلام- هذا أفضل، ينفض الماء بيده، أما الوضوء فلم يثبت فيه شيء فيما نعلم، فمن نشف؛ فلا بأس، ومن ترك؛ فلا بأس، الأمر واسع.","link":"https://binbaz.org.sa/fatwas/2616/حكم-التنشيف-بعد-الوضوء-وبعد-الغسل-من-الجنابة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1112.mp3","categories":["الغسل","فروض الوضوء وصفته"]},{"id":7433,"question":"من نسي أن يسمي قبل الوضوء؟","title":"حكم من نسي التسمية قبل الوضوء","answer":"الجواب:  يسقط عنه التسمية في أول الوضوء، فإذا نسي؛ فلا شيء عليه، وإن ذكر في أثناء الوضوء؛ سمى في أثناء الوضوء، قال: بسم الله، مثل الأكل يسمي عند الأكل، فإذا نسي سمى في أثنائه.  السؤال: ...؟ الجواب: الحديث ضعيف، لكن الواجب أنه إذا ذكر؛ يسمي، هذا هو الذي ينبغي خروجًا من خلاف العلماء، أكثر أهل العلم على أنه سنة؛ لأن الحديث ضعيف، ولكن إذا تركه عمدًا؛ ينبغي أن يعيد الوضوء، أما جاهلًا أو ناسيًا؛ فلا بأس.","link":"https://binbaz.org.sa/fatwas/3521/حكم-من-نسي-التسمية-قبل-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1825.mp3","categories":["فروض الوضوء وصفته","الأدعية والأذكار"]},{"id":7448,"question":"ما حكم اللصفة، هل يمسح عليها عند الغسل من الجنابة؟ وهل يمسح عليها عند الوضوء إذا كانت على أحد أعضاء الوضوء؟","title":"حكم المسح على اللاصقة في الغسل وفي الوضوء","answer":"الجواب: نعم، ويقال لها: الجبيرة، واللزقة، كذلك التي توضع على الظهر، أو على البطن، أو على الجنب، إذا كان عليه غسل جنابة؛ يكفي جريان الماء عليها، إذا أجرى عليها الماء؛ كفى، وإذا كانت في محل الوضوء في القدم؛ كفى المسح عليها، والذراع؛ كفى المسح عليها، يمسح عليها عند غسل الذراع إذا كانت في الذراع، وإذا كانت في الوجه عند غسل الوجه، وإذا كانت في القدم؛ مر عليها الماء ومسحها بالماء عند غسل القدم، ويكفي ذلك ولا يحتاج معها إلى تيمم.","link":"https://binbaz.org.sa/fatwas/3540/حكم-المسح-على-اللاصقة-في-الغسل-وفي-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1845.mp3","categories":["فروض الوضوء وصفته","الغسل"]},{"id":7590,"question":"سؤالها الثاني تقول: عند الوضوء نغسل أعضاء الوضوء ثلاثاً، هل إذا زادت عن ثلاث تنقض الوضوء أم لا؟","title":"حكم الزيادة على ثلاث في غسل الأعضاء عند الوضوء","answer":"الجواب: السنة في الوضوء مرة مرة، ومرتين مرتين، وثلاثاً ثلاثاً، هذا هو الثابت عن رسول الله عليه الصلاة والسلام، توضأ مرة مرة في كل عضو، وتوضأ مرتين مرتين، وتوضأ ثلاثاً ثلاثاً، توضأ في بعض الأعضاء مرتين وبعضها ثلاث، هذا كله لا بأس به، أما الزيادة على الثلاث فلا ينبغي، على ثلاث غسلات يعني، لا ينبغي الزيادة على ثلاث غسلات لا في الوجه ولا في اليدين ولا في الرجلين، أما الرأس فيمسح مسحة واحدة، أما الرأس يمسح ولا يغسل، يمسح مسحة واحدة، يبدأ بمقدمه إلى قفاه ثم يرد اليدين إلى المكان الذي بدأ منه، الرجل والمرأة سواء، هذه السنة لكن المحافظة على الثلاث أفضل، كونه يغسل يديه ثلاثاً ووجهه ثلاثاً ويديه ثلاثاً فهذا هو الكمال، فإن اقتصر على غسلة واحدة أو غسلتين فلا بأس بذلك ولاسيما للتعليم وبيان أن هذا جائز، كل هذا لا بأس به، أو ليعود نفسه الأخذ بالرخصة، كل هذا لا بأس به، أو غسل بعض الأعضاء مرتين وبعضها واحدة، أو بعض الأعضاء مرتين وبعضها ثلاثاً، كل هذا لا حرج فيه والحمد لله، لكن لا تنبغي الزيادة؛ لأنه جاء عن النبي عليه الصلاة والسلام أنه ذكر الوضوء وغسل ثلاثاً ثلاثاً قال: فمن زاد على هذا فقد أساء وتعدى وظلم، فهذا يدل على أنه لا ينبغي أن يزيد على الثلاث أبداً. نعم.","link":"https://binbaz.org.sa/fatwas/4643/حكم-الزيادة-على-ثلاث-في-غسل-الاعضاء-عند-الوضوء ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_019/01908.mp3","categories":["فروض الوضوء وصفته"]},{"id":7636,"question":"هذه الرسالة وردت عن المسح والتيمم في الصلاة، يقول مرسلها وهو لم يذكر اسمه في هذه الرسالة: أصاب أصبع رجلي الإبهام جرح تعفن وأدخلت المستشفى، وأجريت له عملية، وبقي هذا الجرح ستة أشهر لم يبرأ، يغير له الأطباء يوم بعد الآخر ويربطونه بالشاش، وكلما توضأت أمسح على الأصبع، فهل يجزئ هنا المسح عن التيمم؟ مع العلم أن الماء يصل إلى جميع محلات الوضوء ما عدا الأصبع المربوطة، وإذا ربط الشاش فوق الدواء لم يخرج منها شيء، أجيبونا رحمكم الله؟","title":"حكم المسح على الجبيرة عند الوضوء","answer":"الجواب: لا شك أن مسح الجبيرة كافي عن التيمم، فإذا مسح على الجبيرة التي على الجرح عند غسل الرجل التي فيها الجرح كفى ذلك والحمد لله، ولا يحتاج إلى التيمم، وهذا هو الواجب عليه عند وجود الجرح الذي عليه الشاش.. عليه الجبيرة، يمسح على الجبيرة يعمها بالمسح ويكفي عند غسل الرجل والحمد لله. نعم.","link":"https://binbaz.org.sa/fatwas/4690/حكم-المسح-على-الجبيرة-عند-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_026/02603.mp3","categories":["فروض الوضوء وصفته"]},{"id":7716,"question":"أيضاً تقول: إذا كان على جسمي شيء من الدهون، وليس على أعضاء الوضوء، ثم توضأت ونسيت أو تركت إزالته، هل وضوئي صحيح، أم لا؟","title":"الدهن والدسم لا يمنع وصول الماء إلى الجسم","answer":"الجواب: وجود الدسم على أعضاء الوضوء أو على البدن لا يمنع الماء ولا حرج في ذلك، وإذا كان على غير أعضاء الوضوء فليس له تعلق بالوضوء، ولكن في الجنابة لا يضر أيضاً، إذا كان في البدن دسم آثار زيت أو سمن أو شيء شبه ذلك من الدسم هذا لا يمنع وصول الماء إلى البشرة، فلا يضر في ذلك، فإذا توضأت وفي يدها آثار دسم أو في ذراعها أو في قدمها فإنه لا يضر، وهكذا غسل الجنابة وغسل الحيض إذا كان في البدن آثار الدسم لا يمنع الماء، الدسم المعروف الذي ليس له جسم وإنما هي لزوجة في البدن، هذا لا يمنع صحة الغسل ولا صحة الوضوء، والحمد لله.","link":"https://binbaz.org.sa/fatwas/4915/الدهن-والدسم-لا-يمنع-وصول-الماء-الى-الجسم ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_031/03102.mp3","categories":["فروض الوضوء وصفته"]},{"id":7760,"question":"أيضاً يقول: هل يسمح للإنسان الاستنشاق في رمضان؟ وما هي كيفية ذلك الاستنشاق أم الاستنشاق يفطر الصائم؟","title":"حكم المضمضة والاستنشاق أثناء الوضوء للصائم","answer":"الجواب: الاستنشاق والمضمضة في رمضان وفي غير رمضان واجبتان على الصحيح، فالواجب على المسلم أن يتمضمض ويستنشق في رمضان أو في غيره.. في الوضوء وفي الغسل، هذا الواجب في أصح أقوال أهل العلم، ولكنه في رمضان لا يبالغ، يتمضمض مضمضة غير مبالغ فيها لئلا يذهب الماء إلى جوفه، ويستنشق بغير مبالغة كما في الحديث الصحيح: وبالغ في الاستنشاق إلا أن تكون صائماً إذا كان صائم لا يبالغ، يستنشق مرتين أو ثلاثاً، والأفضل ثلاثاً، وهكذا المضمضة، لكن لا يبالغ، لا يشدد في استنشاق الماء لئلا يذهب إلى جوفه. نعم.","link":"https://binbaz.org.sa/fatwas/4956/حكم-المضمضة-والاستنشاق-اثناء-الوضوء-للصاىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_044/04403.mp3","categories":["فروض الوضوء وصفته"]},{"id":7887,"question":"هذه -يا سماحة الشيخ- رسالة وردتنا من المستمع أو الطالبة: (نور الهدى . أ. أ) من السودان، تقول: ما حكم طلاء الأظافر والصلاة فيها؟","title":"حكم طهارة المرأة إذا كان على ظفرها طلاء","answer":"الجواب: إن كان طلاؤها بالحناء أو نحوه مما لا يمنع الماء فلا بأس، أما إذا كان طلاؤها بما يمنع الماء وصوله إلى الظفر فإنه يزال وقت الوضوء، يزال الطلاء ويتوضأ أو تغسل من الجنابة، ثم إذا وضعته بعد ذلك ثم أزالته عند الوضوء لا بأس، أما الطلاء الذي لا يمنع مثل الطلاء بالحناء فهذا لا بأس به ولا حرج فيه مطلقاً. نعم.\nالمقدم: لكن بالنسبة للمرأة التي تطلوا أظافرها بشيء يمنع الوضوء لكنها تغسله عند كل وضوء؟\nالشيخ: إذا غسلته لا بأس، إذا أزالته وقت الوضوء والغسل من الجنابة لا بأس، وغسل الحيض أيضاً. نعم.","link":"https://binbaz.org.sa/fatwas/5358/حكم-طهارة-المراة-اذا-كان-على-ظفرها-طلاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_059/05906.mp3","categories":["فروض الوضوء وصفته"]},{"id":7903,"question":"أيضاً يقول عن وضع المناكير قبل الوضوء: هل تصح الصلاة والوضوء لمن وضعته علماً بأنه يكون طبقة مانعة كما تعلمون، وهل يجوز لمن وضعته دخول المسجد؟","title":"حكم وضع المرأة المناكير قبل الوضوء","answer":"الجواب: الواجب أنها لا تفعله إلا على طهارة، إذا كان ولابد مع أن تركه مطلقاً، هذه المناكير تركها أولى مطلقاً؛ لأنها قد تتساهل فيها، وقد تمنعها من الوضوء، فينبغي تركها بالكلية، لكن إذا كان ولابد وفعلتها على طهارة فإنها إذا انتقضت الطهارة وأرادت الوضوء تزيلها مرة أخرى حتى يبلغ الماء أصل البشرة وأصل الظفر.\nهذا هو الذي ينبغي وهذا هو الواجب عليها فيما نعتقد أنها تزيل هذه المناكير عند إرادة الوضوء، ولا تصلي بها وقد وضعتها على غير طهارة، أما إذا كان وضعتها على طهارة وجاء الوقت وهي على طهارة صلت، لكن لو وضعتها على طهارة ثم انتقضت الطهارة تزيلها ما هي مثل الخفين، الخفين يمسح عليهما، هذه لا، تزيل هذه المناكير حتى تغسل ما تحتها وقت الوضوء. نعم","link":"https://binbaz.org.sa/fatwas/5386/حكم-وضع-المراة-المناكير-قبل-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_061/06105.mp3","categories":["فروض الوضوء وصفته","قضايا المرأة"]},{"id":8127,"question":"يقول في رسالته أيضاً: نحن نجهل ما يجب أن نعرفه، فكيف عملية الاستنجاء وفقكم الله؟ هل الإنسان لازم يغسل ذكره كل مرة أم لا، نريد إحاطتنا وإحاطة المستمعين بذلك، جزاكم الله عنا خير الجزاء؟","title":"حكم الاستنجاء عند كل صلاة","answer":"الجواب: الاستنجاء إنما يجب إذا وجد بول أو غائط، أو جاءت الصلاة فإن المسلم يغسل ذكره إذا بال، إذا بال يغسل ذكره من البول، ويستنجي من الغائط، وهذا يكفيه في أي وقت كان، فإذا جاء وقت الصلاة يتوضأ وضوء الصلاة، يبدأ بالمضمضة والاستنشاق ويكفي، ولا حاجة إلى الاستنجاء، إذا كان قد غسل ذكره من البول، أو غسل دبره من الغائط، أو استجمر بالحجارة أو اللبن ثلاث مرات أو أكثر حتى أنقى المحل كفى، فلا يلزمه أن يعيد ذلك إذا جاء وقت الظهر وهو قد استنجى الضحى بالماء غسل ذكره وغسل دبره أو استجمر بالحجارة الضحى، وأنقى المحل ثلاث مرات فأكثر، لا يعيده الظهر إذا كان ما حصل غائط ولا بول، إلا الأول الذي تطهر منه لا يعيده، بل يتمسح يسميه بعض العامة: التمسح، وهو الوضوء الشرعي، يعني يبدأ بغسل كفيه ثلاثاً، ثم يتمضمض ويستنشق، ويغسل وجهه إلى آخره، ولا يعيد الاستنجاء، ولو أنه ما نوى شيء من هذك الساعة، إذا غسله الضحى مثلاً لا يعيده، هكذا لو أتى الغائط العصر، أو بال وغسل ذكره من البول، واستنجى من الغائط وغسل دبره حتى أنقى المحل، ثم جاء وقت المغرب ولم يأته بول ولا غائط بعد ذلك، فإنه يتوضأ الوضوء الشرعي، يعني يتمسح يبدأ بالمضمضة والاستنشاق، ولا يعيد الاستنجاء، وهكذا لو نام أو خرج منه الريح ريح أو أكل لحم الإبل ما يستنجي، بس يتمسح، يبدأ بالمضمضة والاستنشاق؛ لأن النوم وأكل لحم الإبل ومس الذكر ما فيه استنجاء، الاستنجاء عن البول والغائط خاصة، أما هذه الأشياء التي تنقض الوضوء مثل الريح من الفساء والضراط، مثل مس الفرج، مثل أكل لحم الإبل، هذا لا يوجب الاستنجاء، ولكن يتوضأ توضئوا شرعياً، يبدأ بالمضمضة والاستنشاق، ولا يغسل دبره ولا ذكره، إلا من بول أو غائط. نعم.","link":"https://binbaz.org.sa/fatwas/5924/حكم-الاستنجاء-عند-كل-صلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_087/08710.mp3","categories":["فروض الوضوء وصفته"]},{"id":8322,"question":"الواقع لها سؤال مطول سماحة الشيخ وكله ثناء وتقدير على هذا البرنامج وعلى المشاركين فيه من أصحاب الفضيلة، وتذكر الاستفادة منه في منطقتهم، ثم تسرد سؤالاً مطولاً فتقول: أنا فتاة مسلمة ملتزمة أعمل الخير وأتجنب الشر، إلا أنني لم أقم الصلاة وذلك بسبب الحيرة، حيث في العراق الناس منقسمة إلى قسمين -أي: المسلمين- قسم يدعى: شيعة ، أو القسم الآخر وهو الثاني يدعى: سنة، وصلاة كل منهما تختلف عن الآخر، وكل منهما يدعي أن صلاتهم هي الأصح، وأنا إن صليت القسم الشيعي أو السني فإن الوسوسة لا تفارقني، لهذا كتبت إليكم لعلكم تنقذوني من حيرتي بإخباري الصلاة الصحيحة بدءاً من الوضوء وأنا أعلم أن هذا سيأخذ وقتاً كثيراً من البرنامج، ولكنكم لو تعلمون مدى الفائدة في جوابكم ليس لي فقط وإنما للكثيرات منا، علماً أنني سوف أسجل الجواب على شريط كاست إلى أن أتعلمها وأحفظها، ثم إلى غيري من الفتيات، وهكذا تستمر سماحة الشيخ إلى أن تقول: أرجو أن تفيدوني عن الصلاة بدءاً من الوضوء وحتى التسليم؟","title":"حكم من تقصِّر الصلاة بسبب الحيرة من اختلاف الناس","answer":"الجواب: أسأل الله لك ولجميع أخواتك في الله التوفيق والهداية، وأوصيك أولاً بلزوم ما عليه أهل السنة ، وأن يكون الميزان ما قاله الله ورسوله، الميزان: هو كتاب الله العظيم القرآن، وما صح عن رسول الله عليه الصلاة والسلام في أحاديثه وسيرته عليه الصلاة والسلام، وأهل السنة هم أولى بهذا وهم الموفقون لهذا الأمر، وعند الشيعة أغلاط كثيرة وأخطاء كثيرة، نسأل الله لنا ولهم الهداية حتى يرجعوا إلى الكتاب والسنة، وحتى يدعوا ما عندهم من البدعة.\nفنوصيك بأن تلزمي ما عليه أهل السنة والجماعة ، وأن تستقيمي على ذلك حتى تلقي ربك على طريق السنة والجماعة.\nأما ما يتعلق بالصلاة فالواجب عليك أن تصلي، وليس لك أن تدعيها حيرة، فالصواب ما عليه أهل السنة في ذلك، فعليك أن تصلي كما يصلي أهل السنة ، وعليك أن تحذري التساهل في ذلك، فالصلاة عمود الإسلام وتركها كفر وضلال، فالواجب عليك الحذر من تركها، والواجب عليك وعلى كل مسلم ومسلمة البدار إليها والمحافظة عليها في أوقاتها، كما قال الله : حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاةِ الْوُسْطَى وَقُومُوا لِلَّهِ قَانِتِينَ [البقرة:238] هكذا في سورة البقرة، وقال سبحانه: وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَارْكَعُوا مَعَ الرَّاكِعِينَ [البقرة:43] كذا في سورة البقرة أيضاً، وقال سبحانه: وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَأَطِيعُوا الرَّسُولَ لَعَلَّكُمْ تُرْحَمُونَ [النور:56] في سورة النور، فعليك أن تعتني بالصلاة وأن تجتهدي في المحافظة عليها، وأن تنصحي من لديك في ذلك، والله وعد المحافظين بالجنة والكرامة قال سبحانه: قَدْ أَفْلَحَ الْمُؤْمِنُونَ ۝ الَّذِينَ هُمْ فِي صَلاتِهِمْ خَاشِعُونَ [المؤمنون:1-2] ثم عدد صفات عظيمة لأهل الإيمان ثم ختمها بقوله سبحانه: وَالَّذِينَ هُمْ عَلَى صَلَوَاتِهِمْ يُحَافِظُونَ ۝ أُوْلَئِكَ هُمُ الْوَارِثُونَ ۝ الَّذِينَ يَرِثُونَ الْفِرْدَوْسَ هُمْ فِيهَا خَالِدُونَ [المؤمنون:9-11] هذا وعد عظيم من الله عز وجل لأهل الصلاة وأهل الإيمان، وقال في سورة المعارج: إِنَّ الإِنسَانَ خُلِقَ هَلُوعًا ۝ إِذَاا مَسَّهُ الشَّرُّ جَزُوعًا ۝ وَإِذَا مَسَّهُ الْخَيْرُ مَنُوعًا ۝ إِلَّا الْمُصَلِّينَ ۝ الَّذِينَ هُمْ عَلَى صَلاتِهِمْ دَائِمُونَ [المعارج:19-23] ثم عدد صفاتهم بعد ذلك ثم قال: وَالَّذِينَ هُمْ عَلَى صَلاتِهِمْ يُحَافِظُونَ ۝ أُوْلَئِكَ فِي جَنَّاتٍ مُكْرَمُونَ [المعارج:34-35] فنوصيك بالعناية بالصلاة والمحافظة عليها.\nوأما ما سألت عنه من الوضوء وكيفية الصلاة فهذا جوابه:\nأولاً: الوضوء شرط للصلاة لابد منه، قال الله : يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا قُمْتُمْ إِلَى الصَّلاةِ فَاغْسِلُوا وُجُوهَكُمْ وَأَيْدِيَكُمْ إِلَى الْمَرَافِقِ وَامْسَحُوا بِرُءُوسِكُمْ وَأَرْجُلَكُمْ إِلَى الْكَعْبَيْنِ [المائدة:6] هكذا أمر الله في سورة المائدة، وقال النبي ﷺ: لا تقبل صلاة بغير طهور، وقال عليه الصلاة والسلام: لا تقبل صلاة أحدكم إذا أحدث حتى يتوضأ فلابد من الوضوء، والوضوء أولاً: الاستنجاء، إذا كان الإنسان قد أتى الغائط أو البول يستنجي بالماء من بوله وغائطه، أو يستجمر باللبن أو بالحجارة أو بالمناديل الخشنة الطاهرة عما خرج منه، ثلاث مرات أو أكثر حتى ينقي المحل في الدبر والذكر والقبل حتى ينقي الفرجين من آثار الغائط والبول بالحجر باللبن بمناديل حتى ينقي المحل ثلاث مرات فأكثر والماء أفضل، وإذا جمع بينهما استجمر واستنجى بالماء كان أكمل وأكمل، ثم بعد ذلك يتوضأ الوضوء الشرعي فيغسل كفيه ثلاث مرات هذا هو الأفضل، ثم يتمضمض ويستنشق ثلاث مرات بثلاث غرفات، ثم يغسل وجهه ثلاثاً من منابت الشعر فوق إلى الذقن أسفل، وعرضاً إلى فروع الأذنين هكذا يغسل الوجه، ثم يغسل يديه ذراعيه من أطراف الأصابع إلى المرافق مفصل الذراع من العضد، والمرفق يكون مغسول يغسل اليمنى ثم اليسرى الرجل والمرأة، ثم بعد يمسح الرأس والأذنين الرجل والمرأة، ثم بعد ذلك يغسل رجله اليمنى ثلاثاً مع الكعبين ثم اليسرى ثلاثاً مع الكعبين حتى يشرع في الساق، فالكعبان مغسولان، والسنة ثلاثاً ثلاثاً، في الوجه في المضمضة والاستنشاق والوجه واليدين والرجلين ثلاثاً ثلاثاً، أما الرأس مسحة واحدة مع أذنيه هذه السنة، وإن لم يغسل وجهه إلا مرة عمه بالماء ثم عم يديه بالماء مرة مرة وهكذا الرجلان عمهما بالماء مرة مرة أو مرتين مرتين أجزأ ذلك، ولكن الأفضل ثلاثاً ثلاثاً. وقد ثبت عنه ﷺ أنه توضأ مرة مرة ومرتين مرتين وثلاثاً ثلاثاً وثبت عنه صلى الله عليه وسلم أنه توضأ في بعضها ثلاثاً وبعضها مرتين فالأمر واسع بحمد الله، الواجب مرة يعم كل عضو بالماء، يعم وجهه بالماء مع المضمضة والاستنشاق، ويعم يده اليمنى بالماء حتى يغسل المرفق وهكذا اليسرى يعمها بالماء، وهكذا يمسح رأسه وأذنيه يعم رأسه بالماء ثم الرجلان يغسل اليمنى مرة يعمها بالماء واليسرى كذلك يعمها بالماء مع الكعبين هذا الواجب، وإذا كرر ثنتين كان أفضل، وإذا كرر ثلاث كان أفضل، وبهذا ينتهي الوضوء، ثم يقول: أشهد أن لا إله إلا الله وحده لا شريك له وأشهد أن محمداً عبده ورسوله، اللهم اجعلني من التوابين واجعلني من المتطهرين هكذا قال النبي ﷺ: ما من أحد يتوضأ فيسبغ الوضوء ثم يقول: أشهد أن لا إله إلا الله وحده لا شريك له وأشهد أن محمداً عبده ورسوله إلا فتحت له أبواب الجنة الثمانية يدخل من أيها شاء رواه مسلم في صحيحه، وزاد الترمذي بإسناد حسن بعد ذلك: اللهم اجعلني من التوابين واجعلني من المتطهرين فهذا يقال بعد الوضوء، يقوله الرجل وتقوله المرأة خارج الحمام، ويبدأ الوضوء بالتسمية يقول: باسم الله عند بدء الوضوء، هذا هو المشروع، وأوجبه بعض من أهل العلم أن يقول: باسم الله عند بدء الوضوء، وبهذا عرفنا الوضوء وهو مفتاح الصلاة مفتاحها الطهور.\nثم الصلاة كيفيتها يبدؤها بالتكبير، الظهر والعصر والمغرب والعشاء والفجر يقول: الله أكبر، الرجل والمرأة: الله أكبر، ثم يقول: سبحانك اللهم وبحمدك، وتبارك اسمك، وتعالى جدك، ولا إله غيرك هذا الأفضل، أو يقول: اللهم باعد بيني وبين خطاياي كما باعدت بين المشرق والمغرب، اللهم نقني من خطاياي كما ينقى الثوب الأبيض من الدنس، اللهم اغسلني من خطاياي بالثلج والماء والبرد إن فعل هذا أو هذا كله صحيح، وهناك استفتاحات أخرى ثابتة عن النبي ﷺ إذا أتى بشيء منها صح، ولكن هذان الاستفتاحان من أقصرها فإذا فعلها الرجل أو فعلته المرأة كفى وهو مستحب، هذا الاستفتاح مستحب وليس بواجب، لو شرع في القراءة حالاً بعد التكبير أجزأ، لكن كونه يأتي بهذا الاستفتاح يقول: سبحانك اللهم وبحمدك، وتبارك اسمك، وتعالى جدك، ولا إله غيرك هذا أفضل، أو يأتي بقوله: اللهم باعد بيني وبين خطاياي كما باعدت بين المشرق والمغرب، اللهم نقني من خطاياي كما ينقى الثوب الأبيض من الدنس، اللهم اغسلني من خطاياي بالثلج والماء والبرد وهذا أصح شيء ورد في الاستفتاح.\nثم يقول الرجل أو المرأة: أعوذ بالله من الشيطان الرجيم بسم الله الرحمن الرحيم بعد هذا الاستفتاح يقول: أعوذ بالله من الشيطان الرجيم بسم الله الرحمن الرحيم، ثم يقرأ الفاتحة وهي: الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ۝ الرَّحْمَنِ الرَّحِيمِ ۝ مَالِكِ يَوْمِ الدِّينِ ۝ إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ ۝ اهْدِنَا الصِّرَاطََ الْمُسْتَقِيمَ ۝ صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلا الضَّالِّينَ [الفاتحة:2-7] ثم يقول: آمين، وآمين ما هي من الفاتحة، مستحبة، كان يقولها النبي ﷺ بعد الفاتحة في الجهرية والسرية يقول: آمين، معناها: اللهم استجب.\nثم يقرأ ما تيسر بعد الفاتحة، في الأولى من الظهر والثانية من الظهر، والأولى من العصر والثانية من العصر، والأولى من المغرب والثانية من المغرب، والأولى من العشاء والثانية من العشاء، وفي الثنتين كلتيهما من الفجر، يقرأ مع الفاتحة سورة أو آيات، بعدما يقرأ الفاتحة يقرأ سورة أو آيات، والأفضل في الظهر أن يكون من أوساط المفصل، أن يكون من أوساط المفصل مثل هَلْ أَتَاكَ حَدِيثُ الْغَاشِيَةِ [الغاشية:1] مثل وَاللَّيْلِ إِذَا يَغْشَى [الليل:1] مثل عَبَسَ وَتَوَلَّى [عبس:1]، إِذَا الشَّمْسُ كُوِّرَتْ [التكوير:1]، إِذَا السَّمَاءُ انفَطَرَتْ [الانفطار:1] وما أشبه ذلك وما حول ذلك، وفي العصر مثل ذلك أو أخف منه قليلاً في العصر، وفي المغرب كذلك يقرأ بعد الفاتحة ما تيسر من هذه السور أو أقصر منها، وإن قرأ في بعض الأحيان بأطول في المغرب فهو أفضل؛ لأن الرسول ﷺ قرأ في المغرب بعض الأحيان بالطور، وقرأ فيها في بعض الأحيان بالمرسلات وقرأ فيها في بعض الأحيان بسورة الأعراف قسمها في ركعتين، ولكن في الأغلب يقرأ أقل من ذلك أقصر من ذلك كقراءة هَلْ أَتَاكَ حَدِيثُ الْغَاشِيَةِ [الغاشية:1]، لا أُقْسِمُ بِهَذَا الْبَلَدِ [البلد:1] أو ( إذا زلزلت ) أو ( القارعة ) أو ( العاديات ) لا بأس بهذا، ولكن في بعض الأحيان يقرأ أطول كما تقدم لأن الرسول ﷺ قرأ أطول في المغرب كالطور والمرسلات ونحوهما، وفي العشاء يقرأ مثلما قرأ في الظهر والعصر، يقرأ الفاتحة ويزاد معها، في الأولى مثل ( والسماء ذات البروج ) ( والسماء والطارق ) ( هل أتاك حديث الغاشية ) ( عبس وتولى ) ( إذا الشمس كورت ) وما أشبه ذلك، أو آيات بمقدار ذلك، في الأولى والثانية، وهكذا في الفجر يقرأ بعد الفاتحة زيادة لكن أطول من الماضيات، يكون في الفجر أطول من الظهر والعصر والمغرب والعشاء، يقرأ في الفجر مثل ( ق ) مثل ( اقترتب الساعة ) أو أقل من ذلك مثل ( التغابن ) و ( الصف ) وشبه ذلك مثل ( تبارك الذي بيده الملك ) مثل (قل أوحي...) مثل ( يا أيها المزمل ) وما أشبه ذلك، في الفجر تكون أطول من الظهر والعصر والمغرب والعشاء، اقتداءً بالنبي عليه الصلاة والسلام، ولو قرأ أقل وأقصر لا حرج عليه، فإنه ثبت عنه ﷺ أنه قرأ في بعض الأحيان بأقل من ذلك، لكن كونه في الفجر يقرأ بالطوال في الغالب يكون أفضل تأسياً برسول الله عليه الصلاة والسلام، أما في الثالثة والرابعة من الظهر والعصر والمغرب الثالثة في المغرب والثالثة والرابعة في العشاء يكفي الفاتحة، يقرأ الفاتحة ثم يكبر للركوع، الفاتحة الحمد يعني، يقرؤها ثم يكبر للركوع، لكن ورد في الظهر ما يدل على أنه ﷺ بعض الأحيان قد يقرأ زيادة في الظهر في الثالثة والرابعة، فإذا قرأ بعض الأحيان في الظهر في الثالثة زيادة على الفاتحة وفي الرابعة زيادة على الفاتحة بعض الشيء فهو حسن تأسياً به عليه الصلاة والسلام. هذه صفة القراءة في الصلاة.\nثم يركع ويطمئن في ركوعه، ويجعل يديه على ركبتيه مفرجتي الأصابع، ويسوي رأسه بظهره ويقول: سبحان ربي العظيم، سبحان ربي العظيم، سبحان ربي العظيم، سبحانك اللهم ربنا وبحمدك اللهم اغفر لي، سبحانك اللهم ربنا وبحمدك اللهم اغفر لي، لقول النبي ﷺ: أما الركوع فعظموا فيه الرب، وكان يقول في ركوعه: سبحان ربي العظيم، سبحان ربي العظيم قالت عائشة رضي الله عنها: كان يكثر أن يقول في الركوع والسجود: سبحانك اللهم ربنا وبحمدك اللهم اغفر لي فهذا كله مستحب، والواجب: سبحان ربي العظيم مرة، وإن كررها ثلاثاً كان أفضل أو خمساً، وإذا زاد على ذلك: سبحانك الله ربنا وبحمدك اللهم اغفر لي، سبحان ذي الجبروت والملكوت والكبرياء والعظمة، سبوح قدوس رب الملائكة والروح في بعض الأحيان فحسن، هذا في الركوع.\nوحين يركع يقول: الله أكبر، حين يركع يقول: الله أكبر، ويعتدل في الركوع ويطمئن ولا يعجل، ثم يرفع يقول: سمع الله لمن حمده إن كان إماماً أو منفرداً عند الرفع، يقول: سمع الله لمن حمده، ثم يقول بعد سمع الله لمن حمده: ربنا ولك الحمد، حمداً كثيراً طيباً مباركاً فيه ملء السماوات وملء الأرض وملء ما بينهما وملء ما شئت من شيء بعد  هكذا كان النبي ﷺ وأقر شخصاً سمعه يقول: حمداً كثيراً طيباً مباركاً فيه أقره على ذلك وقال: إنه رأى كذا وكذا من الملائكة كلهم يبادر ليكتبها ليرفعها أو كما قال عليه الصلاة والسلام.\nفالحاصل: أنه إذا رفع من الركوع إذا كان إماماً أو منفرداً يقول: سمع الله لمن حمده ثم يقول وهو منتصب وواقف: ربنا ولك الحمد حمداً كثيراً طيباً مباركاً فيه ملء السماوات وملء الأرض وملء ما بينهما وملء ما شئت من شيء بعد.\nالمقدم: شيخ عبد العزيز انتهى وقت هذه الحلقة، أرجو أن تتفضلوا بتكملة صفة الصلاة الصحيحة في حلقة قادمة إن شاء الله تعالى.","link":"https://binbaz.org.sa/fatwas/6135/حكم-من-تقصر-الصلاة-بسبب-الحيرة-من-اختلاف-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_110/11005.mp3","categories":["فروض الوضوء وصفته"]},{"id":8342,"question":"يقول: كنت ذات يوم ألعب الكرة وقد حدث أن جرحت رجلي جرحاً مؤلماً، ودخل وقت الصلاة فتوضأت الوضوء الكامل غير أني لم أغسل مكان الجرح، فكنت أصلي والدم ينزف مني، ودمت على ذلك خمسة أيام، فهل صلاتي صحيحة مع العذر، أم أنها غير صحيحة، أفيدونا بارك الله فيكم؟","title":"حكم الصلاة مع عدم غسل الجرح ونزول الدم","answer":"الجواب: الواجب في هذا أنك تجعل على الجرح شيئاً يمسك الدم، جبيرة يعني: خرقة تلفه عليه أو ما أشبهها مما يحبس الدم ويوقف الدم حتى تمسح على هذه الجبيرة، فإن لم يتيسر تتيمم عن ذلك، بعد الوضوء تتيمم عن ذلك ويكفي عن محل الجرح، ولكن ربطه بلفافة أو جبيرة ثم تمسح عليها هذا هو الواجب؛ لأنه هو الطريق المتبع، فإذا لم تفعل ذلك فإن قضيت هذه فيكون هو أحوط، إن قضيت الأيام الخمسة التي فعلتها من دون مسح ولا تيمم فهذا هو الأحوط لك؛ لأنك فرطت في هذا الأمر وهو أمر واضح، إما بربط الجرح والمسح عليه وإما بالتيمم بعد ذلك؛ لأنك تستطيع التيمم عن هذا الجرح الذي بقي محله ولم يغسل، والله ولي التوفيق. نعم.","link":"https://binbaz.org.sa/fatwas/6160/حكم-الصلاة-مع-عدم-غسل-الجرح-ونزول-الدم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_112/11206.mp3","categories":["فروض الوضوء وصفته"]},{"id":8459,"question":"هل يشترط الاستنجاء لكل وضوء؟","title":"حكم الاستنجاء لكل وضوء","answer":"الجواب: لا يشترط إنما الاستنجاء لما قد يقع من بول أو غائط.","link":"https://binbaz.org.sa/fatwas/6465/حكم-الاستنجاء-لكل-وضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_123/12306.mp3","categories":["فروض الوضوء وصفته"]},{"id":8707,"question":"أخونا يسأل بالنسبة للمتوضي ذي اللحية الكثيفة هل يفترض أن يصل الماء إلى منابت الشعر؟","title":"جواز الاكتفاء بإجراء الماء على اللحية عند الوضوء","answer":"الجواب: يكفيه أن يمر الماء عليها إذا أمر الماء عليها كفى، فقد جاءت الأحاديث الصحيحة عن رسول الله ﷺ دالة على أن إجراء الماء على اللحية يكفي، وأنه إذا غسل وجهه حتى أجرى الماء على اللحية كفى ذلك، وإن خللها كان أفضل، إذا تيسر تخليلها فهو أفضل، فقد فعل النبي هذا وهذا عليه الصلاة والسلام. نعم.","link":"https://binbaz.org.sa/fatwas/6854/جواز-الاكتفاء-باجراء-الماء-على-اللحية-عند-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_132/13203.mp3","categories":["فروض الوضوء وصفته"]},{"id":8877,"question":"سؤالها الأخير أو ما قبل الأخير: هل مسح الرقبة في الوضوء غير مستحب؛ لأنه تشبه بـاليهود كما سمعت؟","title":"حكم مسح الرقبة في الوضوء","answer":"الجواب: نعم، لا يستحب ولا يشرع، المسح يكون للرأس فقط؛ من منابت الشعر إلى منتهى الشعر تمسح المرأة والرجل، أما الرقبة فليست محلاً للمسح. نعم.","link":"https://binbaz.org.sa/fatwas/7033/حكم-مسح-الرقبة-في-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_139/13903.mp3","categories":["فروض الوضوء وصفته"]},{"id":9186,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات تقول: صفية محمد من لحج في اليمن، أختنا لها مجموعة من الأسئلة من بينها هذا  هل يجوز الاستنشاق والمضمضة في نهار رمضان لمن كان صائماً؟","title":"حكم المضمضة والاستنشاق في نهار رمضان","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه. أما بعد:\nفقد ثبت عن رسول الله عليه الصلاة والسلام أنه قال: وبالغ في الاستنشاق إلا أن تكون صائماً، أمر بإسباغ الوضوء ثم قال: وبالغ في الاستنشاق إلا أن تكون صائماً دل ذلك على أن الصائم يتمضمض ويستنشق لكن لا يبالغ مبالغة يخشى منها نزول الماء إلى جوفه، أما الاستنشاق فلابد منه، وهكذا المضمضة لأنهما فرضان في الوضوء في حق الصائم وغيره. نعم.","link":"https://binbaz.org.sa/fatwas/7346/حكم-المضمضة-والاستنشاق-في-نهار-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_151/15101.mp3","categories":["مفسدات الصيام","فروض الوضوء وصفته"]},{"id":9212,"question":"هل يجوز للمسلم أن يزيد في مرات الاستنشاق عن الثلاث إذا كان مصاباً بالرشح -الزكام- أم يعد هذا مخالفاً للسنة؟","title":"حكم الزيادة في الاستنشاق عن ثلاث","answer":"الجواب: هذا في الحقيقة غير مشروع؛ لأن الرسول ﷺ توضأ ثلاثاً ثلاثاً، تمضمض واستنشق ثلاثاً، غسل وجهه ثلاثاً، غسل يديه ثلاثاً، مسح رأسه مرة وأذنيه مرة واحدة، غسل رجليه ثلاثاً ثلاثاً، هذا هو السنة أن يكتفي بالثلاث، وإن توضأ مرة مرة، أو مرتين مرتين فلا حرج قد فعله النبي ﷺ، أو توضأ مرة في بعض الأعضاء ومرتين في بعض الأعضاء، أو مرتين في بعض الأعضاء وثلاثاً في بعض الأعضاء، كل ذلك لا حرج فيه، أما الزيادة فلا، فقد ثبت عنه ﷺ أنه لما توضأ، لما سأله سائل عن الوضوء علمه إياه ثم قال: فمن زاد فقد أساء وتعدى وظلم خرجه أبو داود والترمذي وغيرهما وإسناده صحيح، وهو يدل على أنه لا تجوز الزيادة، قال: فقد أساء وتعدى وظلم، والإساءة والتعدي والظلم أمر غير جائز.\nفالحاصل أن الحديث المذكور يدل على أنه لا تجوز الزيادة على الكمال الذي فعله النبي ﷺ وهو الثلاث، يعني: إسباغ الوضوء ثلاثاً، ليس المراد الغرفة المراد الغسلة، المراد الغسلة لا الغرفة، فلو أنه غرف مرتين لكل غسلة صارت ست غرفات لا يكون مسيئاً، إنما المسيء الذي قد كمل العضو بالغسل ثم أعاده أكثر من ثلاث، لكن لو غسل رجله مثلاً بغرفة لكن ما كملت الغسلة احتاج إلى غرفة ثانية حتى يكمل رجله ثم غسلها ثانية ثم غسلها ثالثة وزادت الغرفات لا يضر، المهم أن تكون غسلة تامة ثم ثانية ثم ثالثة فلا يزيد على الثلاث، وهكذا في الوجه وهكذا في اليدين، أما الرأس فالسنة أن يكون واحدة فقط هذا المحفوظ في الأحاديث الصحيحة، يمسح مرة واحدة فقط مع الأذنين. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7372/حكم-الزيادة-في-الاستنشاق-عن-ثلاث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_152/15204.mp3","categories":["فروض الوضوء وصفته"]},{"id":9852,"question":"يسأل أيضاً ويقول: هل يصح الوضوء والإنسان متعر تماماً بعد استحمامه في مكان واحد؟","title":"حكم الوضوء والإنسان عريان","answer":"الجواب: لا نعلم حرجاً في ذلك، إذا توضأ وهو عار لا حرج في ذلك، وإن لبس ثم توضأ فهو أحسن وأكمل. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8021/حكم-الوضوء-والانسان-عريان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_262/26210.mp3","categories":["فروض الوضوء وصفته"]},{"id":9896,"question":"شخص يستعمل الماء بكثرة في الوضوء والغسل حيث يغسل الأعضاء أكثر من اللازم، هل يؤثر ذلك على العبادة؟","title":"حكم الإسراف في الماء أثناء الوضوء","answer":"الجواب:\n\nنعم، لا ينبغي، لا ينبغي الإسراف، ذهب بعض أهل العلم إلى تحريم الإسراف في الزيادة عن الثلاث، فينبغي للمؤمن أن يقتصر على ثلاث فأقل، في وضوئه ويحذر من الإسراف في الماء، هذا هو الواجب وهذا هو المشروع للمؤمن أن يقتصد وأن يحذر الإسراف.\n\nبل ورد أنه ﷺ توضأ مرة، مرة، وثنتين ثنتين، وثلاث ثلاث، وفي رواية: فمن زاد فقد أساء وتعدى وظلم.\n\nفالمشروع للمؤمن الاقتصار على المسنون وهو ثلاث فأقل.\n\nالمقدم: جزاكم الله خيرًا","link":"https://binbaz.org.sa/fatwas/8064/حكم-الاسراف-في-الماء-اثناء-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_273/27308.mp3","categories":["فروض الوضوء وصفته"]},{"id":10083,"question":"تسأل عن مسح الأذنين حال الوضوء هل هو سنة؟","title":"حكم مسح الأذنين أثناء الوضوء","answer":"الجواب: لا، لابد منه فرض مع مسح الرأس، ... جزء من مسح الرأس الرسول ﷺ كان يمسح رأسه وأذنيه، فمسحهما مع الرأس أمر مفترض.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8252/حكم-مسح-الاذنين-اثناء-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_276/27611.mp3","categories":["فروض الوضوء وصفته"]},{"id":10132,"question":"تقول: عند القيام بفرض الوضوء، هل واجب على المرأة مسح جميع الرأس أم يكفي الناصية؟","title":"كيفية مسح الرأس عند الوضوء بالنسبة للمرأة","answer":"الجواب: مثل الرجل تمسح جميع الرأس من مقدم الرأس إلى مؤخره، مؤخر الرأس المنبت، أما العمائل الأطراف ما نزل من الضفائر لا يُمسح، ما يجب مسحه، لكن تمسح المرأة كالرجل منبت الشعر من مقدم الرأس إلى آخر الرأس. والرقبة وما بعدها والعمائل ليس لها، الظفائر لا تُمسح، لا يجب مسحها، إنما هو منبت الشعر من مقدم الرأس إلى مؤخر الرأس، تمسح عليه ويمسح الرجل. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8300/كيفية-مسح-الراس-عند-الوضوء-بالنسبة-للمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_305/30506.mp3","categories":["فروض الوضوء وصفته"]},{"id":10173,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الجمهورية العربية السورية وباعثها مستمع من هناك هو (ن. س. س) في أحد أسئلته يقول: أولاً: هل الرقبة من أعضاء الوضوء؟ أرجو إفتائي جزاكم الله خيراً.","title":"الرقبة ليست من أعضاء الوضوء وكيفية مسح الرأس","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فالرقبة ليست من أعضاء الوضوء، وإنما المسح ينتهي بآخر الرأس، يبدأ بمقدمه إلى قفاه آخر منابت الشعر هكذا كان النبي يفعل عليه الصلاة والسلام، كان ﷺ إذا مسح رأسه بدأ بمقدمه إلى قفاه بيديه ثم ردهما إلى المكان الذي بدأ منه، هذا هو أفضل المسح، وكيفما مسح أجزأ لو بدأ بمؤخره أو بوسطه وعمم المسح أجزأه ذلك، لكن كونه يبدأ بمقدم ثم يمر يديه إلى قفاه إلى آخر منابت الشعر ثم يعيدهما إلى المكان الذي بدأ منه هذا هو السنة التي فعلها المصطفى عليه الصلاة والسلام، أما الرقبة فليست محلاً للمسح وليست من أعضاء الوضوء. نعم.\nالمقدم: جزاكم الله خيراً! يسأل -سماحة الشيخ- عن جانبي الرأس هل يشترط لها المسح؟\nالشيخ: نعم، جانبي الرأس يمسحان مع أعلى الرأس ومقدمه يمسح الجميع. نعم.","link":"https://binbaz.org.sa/fatwas/8340/الرقبة-ليست-من-اعضاء-الوضوء-وكيفية-مسح-الراس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_308/30801.mp3","categories":["فروض الوضوء وصفته"]},{"id":10176,"question":"جزاكم الله خيراً، هل تجفيف الماء بعد الوضوء جائز؟","title":"حكم تجفيف الأعضاء بعد الوضوء","answer":"الجواب: لا بأس لا حرج في ذلك، تجفيف الأعضاء لا حرج لا بأس بعد الوضوء. نعم.","link":"https://binbaz.org.sa/fatwas/8341/حكم-تجفيف-الاعضاء-بعد-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_308/30802.mp3","categories":["فروض الوضوء وصفته"]},{"id":10265,"question":"المرسل فهد حمد محمد وافي القحطاني بعث برسالة يقول فيها: إذا بدأت الوضوء ولكنني نسيت التسمية، فما حكم وضوئي ذلك وكيف تنصحون من كان مثلي؟","title":"حكم التسمية عند ابتداء الوضوء","answer":"الجواب: إذا توضأ الإنسان ونسي التسمية أو كان جاهلًا فلا شيء عليه وضوءه صحيح، إنما الخلاف بين العلماء إذا كان تعمد مع العلم، فالجمهور على أن وضوءه صحيح ولو تعمد؛ لأن الأحاديث عندهم ضعيفة في ذلك.\nوذهب بعض أهل العلم: إلى أن وضوءه غير صحيح إذا تعمد مع العلم؛ لأن الأحاديث وإن كان في أسانيدها مقال، لكنها يشد بعضها بعضًا، كما قال الحافظ ابن كثير رحمه الله عند تفسير قوله تعالى: يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا قُمْتُمْ إِلَى الصَّلاةِ [المائدة:6] الآية من سورة المائدة، قال: إن أسانيدها يشد بعضها بعضًا، وهي الحديث المعروف المروي عن رسول الله ﷺ أنه قال: لا وضوء لمن لم يذكر اسم الله عليه جاءت من عدة أحاديث، جاءت عن عدة من الصحابة، عن أبي سعيد وأبي هريرة وآخرين، لكن في أسانيدها مقال، قال الحافظ رحمه الله: يشد بعضها بعضًا وتكون من قبيل الحسن، يكون الحديث من قبيل الحسن لغيره، ولهذا ذهب بعض أهل العلم إلى وجوب هذه التسمية في أول الوضوء مع الذكر، أما مع النسيان أو مع الجهل فلا شيء عليه، ووضوءه صحيح.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8436/حكم-التسمية-عند-ابتداء-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_337/33705.mp3","categories":["فروض الوضوء وصفته"]},{"id":10450,"question":"يقول: أكثر الأحيان أتوضأ في الحمام، وبدون أن أسمي، ولكني أنوي التسمية بقلبي، فهل يصح الوضوء؟","title":"حكم التسمية في الوضوء لمن توضأ في الحمام","answer":"الجواب: الوضوء صحيح على الصحيح، لكن السنة أنك تسمي ولو في الحمام، تقول: (باسم الله) عند بدء الوضوء؛ لأن التسمية يراها واجب جمع من أهل العلم، التسمية تجب عند جمع من أهل العلم فلا تتركها، تسمي في أول الوضوء ولو كنت .... والذي مضى نسأل الله أن يعفو عنا وعنك ولا حرج إن شاء الله. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8629/حكم-التسمية-في-الوضوء-لمن-توضا-في-الحمام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_319/31907.mp3","categories":["فروض الوضوء وصفته"]},{"id":10470,"question":"من المستمع حسن كاظم جاسم من العراق رسالة وضمنها جمعاً من الأسئلة يقول في أحدها: ما هي أحكام الوضوء؟ وهل هناك أدعية واردة عن الرسول ﷺ أثناء الوضوء؟","title":"من أحكام الوضوء","answer":"الجواب: الوضوء له فرائض وله شرائط، ويستحب في أوله التسمية وفي آخره الشهادة، بعدما يفرغ يقول: أشهد أن لا إله إلا الله وحده لا شريك له، وأشهد أن محمداً عبده ورسوله، اللهم اجعلني من التوابين واجعلني من المتطهرين وفي أوله يقول: (باسم الله). عندما يغسل يديه ليتوضأ، يغسل كفيه ثلاثاً، قبل أن يتمضمض يسمي عند ذلك، وله شرائط عشرة: الإسلام، والعقل، والتمييز، ونية رفع الحدث، واستصحاب حكم النية، وانقطاع الموجب الذي يوجب الوضوء من البول ونحوه، والاستنجاء والاستجمار قبله، إما استنجاء بالماء وإلا استجمار بالحجارة ونحوها، كالمناديل واللبن ونحو ذلك، وطهورية الماء، كون الماء طهور .. كونه مباح، وإزالة ما يمنع غسل البشرة، إزالة الشيء الذي يمنع غسل البشرة من عجين أو صمغ أو غير هذا مما يمنع وصول الماء إلى الجلدة، وهناك شرط حادي عشر في حق من حدثه دائم: أن لا يتوضأ إلا بعد دخول الوقت.\nوهذا أمر به النبي ﷺ المستحاضة، وحكم صاحب السلس مثلها، النبي عليه السلام قال للمستحاضة: وتوضئي لوقت كل صلاة، فيلحق بها جميع من حدثه دائم، كصاحب السلس الدائم البول، أو الريح الدائمة، هذا مثل صاحب الدم الدائم المستحاضة، يتوضأ إذا دخل الوقت، وبعض أهل العلم نازع في إباحة الماء، وقال: يجوز التوضؤ وإن كان غير مباح؛ لأن المقصود يحصل به من إزالة آثار النجاسة ومقتضى الحدث، والتحريم ليس خاصاً بالوضوء خاصاً بجنس الماء، لابد يكون مباح لا يجوز له شربه ولا الوضوء به، ولا استعماله إلا إذا كان ملكاً له.\nوالقاعدة: ما كان تحريمه عاماً لا يخص الصلاة فإنه لا يبطل الصلاة، وهكذا الصلاة في الثوب المغصوب والأرض المغصوبة؛ لأن النهي عام ما يخص الصلاة، ليس له أن يستعمل الثوب المغصوب، وليس له أن يجلس في الأرض المغصوبة، ولو كان في غير الصلاة.\nفإذا كان النهي عاماً فإنه لا يضر الصلاة، وإن كان لا يجوز له الفعل، فعلى هذا لو صلى في الأرض المغصوبة أو توضأ بالماء المغصوب أو صلى في الثوب المغصوب، صحت صلاته مع الإثم، يأثم وتصح صلاته، وهذا القول أرجح، أرجح هذا القول. نعم.\nالمقدم: جزاكم الله خيراً..\nالشيخ: وهكذا النجاسة لو أزالها بالماء النجس بماء طهور لكنه مغصوب زالت ولكن يأثم، لو كان في ثوبه نجاسة وغسلها بماء مغصوب ماء طهور لكنه مغصوب زالت النجاسة وطهر الثوب مع كونه آثماً؛ لأن المقصود حصل، المقصود من الماء حصل. نعم.\nالمقدم: جزاكم الله خيراً، يسأل عن الأدعية أثناء الوضوء؟\nالشيخ: ما ورد شيء مثلما تقدم، لا يشرع في الوضوء أدعية ما عدا التسمية في أوله والشهادة في آخره.\nالمقدم: أما أثناء الوضوء؟\nالشيخ: ما ورد شيء لا، .. شيء صحيح.\nالمقدم: لم يرد شيء صحيح.\nالشيخ: نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8638/من-احكام-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_320/32004.mp3","categories":["فروض الوضوء وصفته"]},{"id":10505,"question":"يسأل سماحتكم عن حكم مسح الأذنين حال الوضوء؟","title":"حكم مسح الأذنين في الوضوء","answer":"الجواب: يجب مسح الأذنين؛ لأنها من الرأس، جزء من الرأس، والرأس يجب تعميمه، الرأس كله من أوله إلى آخره مع الأذنين، يدخل أصبعيه في الصماخين ويمسح بإبهاميه ظاهر أذنيه، وهذا هو الواجب عليه في كل وضوء. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8680/حكم-مسح-الاذنين-في-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_282/28213.mp3","categories":["فروض الوضوء وصفته"]},{"id":10552,"question":"يقول: هل يلزم الإنسان أن يستنجي كلما أراد أن يتوضأ؟","title":"حكم الاستنجاء قبل الوضوء","answer":"الجواب: لا لا يلزمه ذلك إنما يتوضأ في الوجه واليدين ومسح الرأس والأذنين وغسل الرجلين، إذا كان لم يخرج منه بول ولا غائط إنما هو الريح مثلاً أو مس الفرج، أو أكل لحم الإبل أو النوم، هذا ما فيه استنجاء إنما يتوضأ يسميه بعض الناس التمسح يعني: يغسل يديه كفيه ثلاث مرات ثم يتمضمض ويستنشق، ثم يغسل وجهه ثلاثاً، ثم يغسل يديه ثلاثاً مع المرفقين، ثم يمسح رأسه مع أذنيه مسحة واحدة ثم يغسل رجليه مع الكعبين ثلاثاً، هذا يقال له: الوضوء الشرعي، وإن غسل أقل من ذلك، غسل وجهه مرة ويديه مرة أو مرتين و غسل رجليه مرة أو مرتين لا بأس لكن السنة ثلاثاً الأفضل ثلاثاً ثلاثاً. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8728/حكم-الاستنجاء-قبل-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_321/32108.mp3","categories":["فروض الوضوء وصفته"]},{"id":10928,"question":"نعود مع مطلع هذه الحلقة إلى رسالة المستمع (ع. ص. أ) هذا المستمع عرضنا بعض أسئلة له في حلقة مضت، وفي هذه الحلقة يسأل ويقول: سمعت حديثًا من برنامجكم وهو: لا وضوء لمن لم يذكر اسم الله عليه، فما الحكم لو أن أحدًا توضأ في دورة المياه، ونحن نعلم أنه لا يجوز ذكر اسم الله فيها؟","title":"حكم التسمية عند بدء الوضوء وفي دورة المياه","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه. نعم، لقد جاء عن النبي ﷺ من عدة طرق عن جماعة من الصحابة  أنه قال: لا وضوء لمن لم يذكر اسم الله عليه، ولكن أسانيدها فيها بعض الضعف، ومجموعها يرتقي إلى درجة الحسن، فينبغي للمؤمن عند الوضوء أن يسمي الله في ابتداء الوضوء فيقول: باسم الله عندما يغسل كفيه لقصد الوضوء، أو عند ابتداء المضمضة والاستنشاق يسمي الله -جل وعلا- عملًا بهذه الأحاديث ولو كان في دورة المياه، فإن تيسر له أن يكون الوضوء خارجها فعل، وإلا فلا مانع أن يقول: باسم الله عند وضوئه وإن كان في الدورة، وذكر الله في الدورة ليس بحرام، إنما يكره كراهة فقط عند بعض أهل العلم، لكن إذا دعت الحاجة إلى ذلك زالت الكراهة كالتسمية عند بدء الوضوء، أما إن نسى ذلك، أو جهل ذلك فلا حرج عليه، وضوؤه صحيح، لكن لا ينبغي له أن يتعمد ذلك، بل ينبغي له أن يسمي الله في أول الوضوء حتى وإن كان في الدورة؛ لأن شدة الحاجة إلى ذلك، وقول بعض أهل العلم بوجوب ذلك يمنع من الكراهة حينئذ، وتزول الكراهة بذلك، ويسمي الله عند بدء وضوئه. أما إذا كان ما هناك حاجة فيكره له ذكر الله في حال وجوده في الدورة التي هي محل قضاء الحاجة؛ تعظيمًا لذكر الله  وتقديسًا له، ولو ترك المتوضئ التسمية عند الوضوء جهلًا منه، أو نسيانًا منه فوضوؤه صحيح.  أما إن تركها عمدًا مع العلم، ومع المعرفة بالحكم الشرعي، فالأحوط له أن يعيد الوضوء؛ لأن بعض أهل العلم ذهب إلى وجوب ذلك، لهذه الأحاديث، وإن كان فيها ضعف لكن يشد بعضها بعضًا، نسأل الله للجميع التوفيق، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9111/حكم-التسمية-عند-بدء-الوضوء-وفي-دورة-المياه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_362/36208.mp3","categories":["فروض الوضوء وصفته"]},{"id":11235,"question":"يقول: ذهبت إلى الجامع للصلاة وعند الانتهاء من الصلاة تذكرت بأن أحد أعضاء الوضوء لم أقم بغسله، فهل تجوز صلاتي؟","title":"حكم من ترك أحد أعضاء الوضوء ولم يذكر إلا بعد الصلاة","answer":"الجواب:  لا. عليك أن تعيد الوضوء وتعيد الصلاة إن كانت فريضة؛ لأنك لم تأت بوضوء صحيح، الوضوء غير صحيح، فأنت صليت بلا وضوء.","link":"https://binbaz.org.sa/fatwas/9406/حكم-من-ترك-احد-اعضاء-الوضوء-ولم-يذكر-الا-بعد-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_291/29116.mp3","categories":["فروض الوضوء وصفته"]},{"id":11248,"question":"هل يجوز الوضوء بماء قد تغيرت أحد أوصافه الثلاثة بطاهر مثلًا: تغير بليمون أو بحليب أو بصابون مثلاً، جزاكم الله خيرًا؟","title":"حكم الوضوء بماء تغيرت أحد أوصافه","answer":"الجواب:  ما دام اسمه باقيًا فلا بأس، ما دام اسمه الماء باقيًا فله أن ينتفع به .. أن ينتفع بالماء. الشيخ: أعد العبارة؟ المقدم: يقول: هل يجوز أن أتوضأ بماء تغيرت أحد أوصافه الثلاثة بطاهر، مثلًا: تغير بليمون أو حليب، أو صابون أو ما شابه ذلك؟ الشيخ: إن كان الشيء يسيرًا ما غير الماء.. تغيير يسلبه اسم الماء، فيه الشيء اليسير من صابون أو من غيره فالماء باقٍ، فلا بأس. أما إذا كان صار حليبًا أو صار صابونًا أو صار نوعًا آخر لا، ما عاد صار ماء صار شيئًا آخر، كالمرق وكالشاهي ما يجوز استعماله، لكن إذا كان شيئًا يسيرًا خالطه شيء يسير لم يسلبه اسمه، بل فيه شيء يسير من صابون أو غيره فلا بأس. أما إذا تغير صار صابونًا أو صار سدرًا، أو صار شاهيًا أو حليبًا أو لبنًا فلا يجوز استعماله ما يحصل به رفع الحدث، ولا إزالة النجاسة، لأن اسم الماء ذهب عنه. نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9445/حكم-الوضوء-بماء-تغيرت-احد-اوصافه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_374/37418.mp3","categories":["المياه","فروض الوضوء وصفته"]},{"id":11260,"question":"هل يجوز الوضوء بماء قد تغيرت أحد أوصافه الثلاثة بطاهر مثلًا: تغير بليمون أو بحليب أو بصابون مثلاً، جزاكم الله خيرًا؟","title":"حكم الوضوء بماء تغيرت أحد أوصافه","answer":"الجواب:  ما دام اسمه باقيًا فلا بأس، ما دام اسمه الماء باقيًا فله أن ينتفع به .. أن ينتفع بالماء. الشيخ: أعد العبارة؟ المقدم: يقول: هل يجوز أن أتوضأ بماء تغيرت أحد أوصافه الثلاثة بطاهر، مثلًا: تغير بليمون أو حليب، أو صابون أو ما شابه ذلك؟ الشيخ: إن كان الشيء يسيرًا ما غير الماء.. تغيير يسلبه اسم الماء، فيه الشيء اليسير من صابون أو من غيره فالماء باقٍ، فلا بأس. أما إذا كان صار حليبًا أو صار صابونًا أو صار نوعًا آخر لا، ما عاد صار ماء صار شيئًا آخر، كالمرق وكالشاهي ما يجوز استعماله، لكن إذا كان شيئًا يسيرًا خالطه شيء يسير لم يسلبه اسمه، بل فيه شيء يسير من صابون أو غيره فلا بأس. أما إذا تغير صار صابونًا أو صار سدرًا، أو صار شاهيًا أو حليبًا أو لبنًا فلا يجوز استعماله ما يحصل به رفع الحدث، ولا إزالة النجاسة، لأن اسم الماء ذهب عنه. نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9445/حكم-الوضوء-بماء-تغيرت-احد-اوصافه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_374/37418.mp3","categories":["المياه","فروض الوضوء وصفته"]},{"id":11268,"question":"يسأل ويقول: ما حكم من نسي شيئًا في الوضوء، سواء كان ذلك الشيء فرضًا أو كان سنة، هل يعيد العضو نفسه أم يعيد الوضوء كله جزاكم الله خيرًا؟","title":"حكم من نسي عضواً من أعضاء الوضوء","answer":"الجواب:  إذا كان المدة قريبة يعيد العضو وما بعده، أما إذا كان طال الفصل يعيد الوضوء كله، فلو نسي مثلًا يده اليسرى عند الوضوء ثم تنبه بعدما مسح رأسه أو عند غسل رجليه يعود يغسل يده اليسرى ثم يمسح رأسه، ثم يغسل رجليه، أما لو طال الفصل فإنه يعيد الوضوء كله، نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9463/حكم-من-نسي-عضوا-من-اعضاء-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_375/37514.mp3","categories":["فروض الوضوء وصفته"]},{"id":11345,"question":"يقول: أصيب شخص بجرح في إصبعه، وقام الطبيب بربط الجزء المصاب حتى لا يصل الماء إلى الجرح، فهل يتوضأ في هذه الحالة؟ أم يتيمم؟ جزاكم الله خيرًا.","title":"كيفية وضوء من به جرح يخشى وصول الماء إليه","answer":"الجواب:  يتوضأ ويمسح على الجبيرة، يتوضأ ويمسح على الجبيرة والحمد لله، وليس له حد محدود، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9542/كيفية-وضوء-من-به-جرح-يخشى-وصول-الماء-اليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_378/37819.mp3","categories":["فروض الوضوء وصفته"]},{"id":11347,"question":"تقول: إحدى الأخوات شعرها طويل، تقوم بلفه حول رأسها بحيث يكون كالطاقية، ثم تثبته بالمشابك الخاصة بالشعر، فهل يصح المسح عليه وهو على هذه الحالة عند الوضوء؟","title":"حكم المسح على الظفائر في الوضوء","answer":"الجواب: عليها أن تنقضه حتى تمسح الرأس الذي هو المنابت من أوله إلى منتهاه، أما أطراف الشعر العمايل فلا يلزمها مسحها، لكن تزيل هذا الذي على القبة حتى تمسح القمة من منابت الشعر، من مقدم الرأس إلى نهاية منابت الشعر مما يلي مؤخر الرأس، أما العمايل التي تنزل عن ذلك فلا يلزمها في الوضوء مسحها، لكن يلزمها إمرار الماء عليها في الغسل غسل الجنابة والحيض، وأما في الوضوء يكفي المسح لمنابت الشعر وإزالة هذه المجموعة على الرأس.","link":"https://binbaz.org.sa/fatwas/9537/حكم-المسح-على-الظفاىر-في-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_378/37814.mp3","categories":["فروض الوضوء وصفته"]},{"id":11409,"question":"بعد هذا رسالة بعث إليها أحد الإخوة المستمعين، بل إحدى الأخوات المستمعات تقول: أختكم أم معاذ من المدينة المنورة تسأل سماحتكم عن الحناء ووضعه على الشعر، وحينئذ تمسح عليه إذا ما أرادت الوضوء، هل يجوز ذلك، أو لا؟ جزاكم الله خيرًا.","title":"حكم مسح المرأة شعرها وعليه حناء حال الوضوء","answer":"الجواب:  لا حرج في ذلك، قد ذكرت عائشة -رضي الله عنها- أنهن كن يمسحن على الضمادات على رؤوسهن في عهد النبي -عليه الصلاة والسلام- فلا حرج في ذلك إذا كانت ماشطة بحناء، أو غيره، ومسحت على ما علا رأسها، لا حرج -إن شاء الله- مع مسح الأذنين، مع مسح الأذنين الصماخين، وظاهر الأذنين، نعم.","link":"https://binbaz.org.sa/fatwas/9588/حكم-مسح-المراة-شعرها-وعليه-حناء-حال-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_380/38008.mp3","categories":["فروض الوضوء وصفته"]},{"id":11489,"question":"تسأل أختنا: هل ينبغي إخراج ما برأسي من دبابيس الشعر عند المسح عليه حال الوضوء؟","title":"حكم مسح المرأة رأسها في الوضوء وفي شعرها دبابيس","answer":"الجواب:  لا حرج أن تمسحي عليه، وفيه الدبابيس، نعم، مثلما يمسح على الملصقات في الرأس من حناء وغيره، فهذه الأمور قد يشق نزعها، وإن نزعتها؛ فلا بأس، لكن قد يشق نزعها، دبابيس أو حناء، أو أشياء من أدوية؛ تمسح عليها، والحمد لله. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9670/حكم-مسح-المراة-راسها-في-الوضوء-وفي-شعرها-دبابيس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_383/38303.mp3","categories":["فروض الوضوء وصفته"]},{"id":11526,"question":"تقول أختنا في قضية أخرى: توضأت، وقدمت عضوًا على عضو، أي: قدمت غسل اليدين، ثم الوجه وذلك دون علم بصحة ذلك، أو عدم صحته، فما حكم وضوئي؟ جزاكم الله خيرًا.","title":"حكم الترتيب في الوضوء","answer":"الجواب:  الوضوء لا يصح إلا بالترتيب، الوجه، ثم اليدين، ثم الرأس، ثم الرجلين هذا الوضوء الشرعي، فالصلاة التي صليتيها بهذا الوضوء المنكس عليك أن تعيديها إذا كنت تعرفينها، وإلا فبالظن والاجتهاد، أعيدي الصلاة التي تظنين أنك صليتيها بهذا، مع التوبة والاستغفار؛ ولأنك لم تسألي، ولم تتعلمي الواجب، عليك التعلم والسؤال، ولو من طريق الهاتف، تسألي أهل العلم من طريق الهاتف، من طريق التلفون، من طريق المكاتبة.. تسألي أهل العلم عندك إن كان عندك من يعرف لا تسكتي، الواجب السؤال، الله يقول سبحانه: فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لا تَعْلَمُونَ [النحل:43] ويروى عنه  أنه قال: ألا سألوا إذ لم يعلموا، إنما شفاء العي السؤال. فالواجب على الرجل والمرأة أن يسأل كل واحد، كل مسلم يسأل عما أشكل عليه، عما يهمه في دينه، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9708/حكم-الترتيب-في-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_385/38504.mp3","categories":["فروض الوضوء وصفته"]},{"id":11615,"question":"هل الاستحمام يجزئ عن الوضوء للصلاة؟","title":"حكم الاكتفاء بالاستحمام عن الوضوء","answer":"الجواب:  إذا كان الاستحمام عن جنابة، وأراد الحدثين الأصغر والأكبر، المغتسل أراد بغسله الوضوء والغسل جميعًا وهو جنب؛ أجزأ، أما الاستحمام عن غير الجنابة لا، لابد من الوضوء قبله، أو بعده، لابد أن يتوضأ. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9802/حكم-الاكتفاء-بالاستحمام-عن-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_388/38813.mp3","categories":["الغسل","فروض الوضوء وصفته"]},{"id":11624,"question":"هل الكحل السائل يمنع من وصول ماء الوضوء؟","title":"حكم الكحل الذي يمنع وصول الماء في الوضوء","answer":"الجواب:  الكحل كحلان: إن كان له جرم يمنع الماء؛ لابد من إزالتة وقت الوضوء، أما إن كان ليس له جرم، بل هو خفيف، ليس له جرم يمنع؛ فإنه لا يمنع الوضوء، تغسل وجهها، ولا حاجة إلى إزالة الكحل إذا كان مجرد سواده، وجود سوادة ليس له جرم يمنع الماء، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9805/حكم-الكحل-الذي-يمنع-وصول-الماء-في-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_388/38816.mp3","categories":["فروض الوضوء وصفته"]},{"id":11629,"question":"هل الاستحمام يجزئ عن الوضوء للصلاة؟","title":"حكم الاكتفاء بالاستحمام عن الوضوء","answer":"الجواب:  إذا كان الاستحمام عن جنابة، وأراد الحدثين الأصغر والأكبر، المغتسل أراد بغسله الوضوء والغسل جميعًا وهو جنب؛ أجزأ، أما الاستحمام عن غير الجنابة لا، لابد من الوضوء قبله، أو بعده، لابد أن يتوضأ. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9802/حكم-الاكتفاء-بالاستحمام-عن-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_388/38813.mp3","categories":["الغسل","فروض الوضوء وصفته"]},{"id":11633,"question":"المستمع محمد السيد عبده من بريدة بعث يسأل ويقول: هل يجوز الوضوء من ماء شربت منه الدابة، مثل الإبل والغنم والبقر؟ وما هي الدواب التي لا يجوز الوضوء من سؤرها؟ جزاكم الله خيرًا.","title":"حكم الوضوء من ماء شربت منه دواب","answer":"الجواب:  لا حرج في الشرب من الماء الذي شربت منه الدواب من الإبل أو البقر أو الغنم؛ لأنها طيبة؛ لأنها مباحة، وهكذا الحمر والبغال على الصحيح، لو شربت؛ فإنها لا تضر الماء.. الماء طهور، ولو شرب منه البغل والحمار، كانت تشرب من المياه عند النبي ﷺ والصحابة، فالصواب أن سؤر البغل والحمار لا حرج فيه يستعمل. أما إذا كانت الدواب غير المعتادة، كالكلب فلا يستعمل سؤره بل يراق، وهكذا الأسود والنمور، وأشباهها من السباع سؤرها يراق، إلا إذا كان ماء كثير مثل ورودها على الحياض، والغدران لا يضر، ولا يلتفت إليها، ولو وردتها؛ لا يضر ذلك، أما إذا شربت في إناء.. إذا شربت في إناء؛ يراق، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9819/حكم-الوضوء-من-ماء-شربت-منه-دواب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_389/38906.mp3","categories":["فروض الوضوء وصفته"]},{"id":11638,"question":"هل يجوز قطع الوضوء لفترة تكون بسيطة، ثم بعد ذلك يعود لإكمال الوضوء؟","title":"حكم اشتراط الموالاة في الوضوء","answer":"الجواب:  إذا كانت يسيرة عرفًا، والأعضاء على حالها لم تيبس، بل قطع ليكلم أحدًا، وإلا كذا؛ فلا يضر، أما إذا طال الفصل؛ لابد من التوالي، ما يصح، لابد من التوالي عرفًا، والأحوط له ألا يتساهل في هذا؛ لأنه قد يعتقد أنها غير طويلة، وهي طويلة.  فالأحوط له أنه يكمل الوضوء، يتابع الوضوء كما كان النبي يفعل -عليه الصلاة والسلام- والصحابة، إذا دخل فيه؛ يتابعه حتى ينهيه. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9820/حكم-اشتراط-الموالاة-في-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_389/38907.mp3","categories":["فروض الوضوء وصفته"]},{"id":11662,"question":"الأخت المستمعة (م. م. م) من جدة خط الجامعة بعثت تسأل وتقول: لدي طقم أسنان هل يجزئ وضوء واحد، أم عند كل وضوء لا بد من خلعها ثم الوضوء؟","title":"حكم إخراج الأسنان الصناعية عند الوضوء","answer":"الجواب:  لا حاجة إلى خلعها، تمضمضت يعني عند الوضوء الأول، وما دامت على الطهارة؛ فلا حاجة، مادامت على الطهارة فإنها تصلي بالطهارة، وإذا أرادت الطهارة الأخرى؛ تمضمضت، والأسنان في فمها، لا حاجة إلى خلعها. نعم.","link":"https://binbaz.org.sa/fatwas/9845/حكم-اخراج-الاسنان-الصناعية-عند-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_298/29814.mp3","categories":["فروض الوضوء وصفته"]},{"id":11685,"question":"هذا المستمع يسأل قضايا أخرى فيقول في هذه القضية: في الشتاء كنت دائمًا أستعمل الماء الساخن في الوضوء، فقال لي صديقي: إن هذا ليس من السنة، فما هو تعليق سماحتكم؟ جزاكم الله خيرًا.","title":"جواز استعمال الماء الساخن للوضوء في الشتاء","answer":"الجواب:  لا حرج في هذا الإنسان يستعمل الماء الدافي حتى يتمكن من الكمال والتمام في وضوئه والإسباغ، وهذا الذي قال لك ليس عنده خبر، ليس عنده بصيرة، أما حديث: ألا أخبركم بما يرفع الله به الدرجات، ويحط به الخطايا إسباغ الوضوء في المكاره فهذا عند الحاجة إليه، عند الحاجة إلى البارد وعدم وجود الدافي لا بأس، الحمد لله، أما إذا تيسر الماء الدافي فهو أولى؛ لأنه أبلغ في الوضوء وأكمل. نعم.","link":"https://binbaz.org.sa/fatwas/9870/جواز-استعمال-الماء-الساخن-للوضوء-في-الشتاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_390/39017.mp3","categories":["فروض الوضوء وصفته"]},{"id":11709,"question":"رسالة بعث بها مستمع رمز إلى اسمه بالحروف (أ. م. س. أ) من أسيوط في جمهورية مصر العربية، يسأل سؤالًا ويقول: تحديد الوجه في الوضوء لمن لا لحية له، ولمن له لحية، وذلك بالتفصيل، وبيان معنى ذلك؟ جزاكم الله خيرًا.","title":"تحديد الوجه في الوضوء","answer":"الجواب:  الوجه هو الذي تحصل به المواجهة، فيغسل ما بين الأذنين، ومن منابت الشعر فوق إلى اللحية أسفل هذا الوجه، يغسل وجهه ومعه اللحية، يجري عليها الماء، والخدين ما أقبل من الأذنين الأذنان من الرأس، ليسا من الوجه، لكن ما بينهما كله من الوجه، ومن منابت الشعر فوق وأسفل، كله من الوجه إلى اللحية واللحية إن خللها بالماء؛ فهو أفضل، وإن أجرى عليها الماء كلها؛ كفى، والحمد لله. نعم. المقدم: الحمد لله، جزاكم الله خيرًا، وإذا لم يكن له لحية؟ الشيخ: كذلك يغسل محل اللحية. المقدم: محل اللحية، بارك الله فيكم، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9899/تحديد-الوجه-في-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_392/39212.mp3","categories":["فروض الوضوء وصفته"]},{"id":11712,"question":"يسأل عن غسل الأذن بالذات والفم والأنف هل هو واجب؟ ولاسيما أن الأذن قد تتضرر بالغسل، جزاكم الله خيرًا.","title":"حكم غسل الأذن في الوضوء","answer":"الجواب:  الأذن لا تغسل، تمسح بالأصبع في الوضوء، لا تغسل لا في الوضوء، ولا في الغسل، إنما يغسل ظاهرها، وأما صماخها بالأصبع يمسحها، ويغسلها، ويكفي، لا يخاطر نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9900/حكم-غسل-الاذن-في-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_392/39213.mp3","categories":["فروض الوضوء وصفته"]},{"id":11882,"question":"هل يجب على المرأة أن تخلل شعرها أثناء الوضوء؟","title":"حكم تخليل شعر المرأة ونقض ضفائرها في الغسل والوضوء","answer":"الجواب:  ليس عليها أن تخلل شعرها، بل تمر الماء على شعرها ويكفي، سألت أم سلمة النبي ﷺ قالت: يا رسول الله! إني امرأة أشد شعر رأسي؛ أفأنقضه لغسل الجنابة والحيض؟ فقال -عليه الصلاة والسلام-: إنما يكفيك أن تحثي على رأسك ثلاث حثيات، ثم تغتسلين، فتطهرين في الجنابة تحثو عليه ثلاث مرات، وفي الوضوء تمر يديها عليه بالمسح يكفي، ولا حاجة إلى النقض لا في الغسل، ولا في الوضوء، لكن في الغسل تحثي عليه ثلاث حثيات، مثلما أمر النبي ﷺ، ويكفي، وفي الوضوء تمسح تمر يديها عليه على ظاهر الرأس، ويكفي، نعم تمسح أذنيها أيضًا، تضع أصبعيها في أذنيها في الصماغين وتمسح بإبهامها على ظاهر الأذنين، ويكفي، والحمد لله. المقدم: جزاكم الله خيرًا، إذا كان على شكل ضفائر، هل يلزمها أن تفك تلك الضفائر؟ الشيخ: لا لا تمسح عليها الماء، ويكفي، إلى حدود ......... أطراف الضفائر، لا نعلم إلا في الغسل، تمر الماء عليها كلها، أما في الوضوء إلى منابت الشعر إلى أسفل الرأس في المنابت، وإذا طال الشعر فوق ذلك ما يضر. المقدم: جزاكم الله خيرًا، لكن في الغسل لا يجب عليها فك الضفائر؟ الجواب: لا تفك، ولكن تعمه بالماء، تعم الماء، تصب الماء عليه كله. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/10066/حكم-تخليل-شعر-المراة-ونقض-ضفاىرها-في-الغسل-والوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_425/42503.mp3","categories":["فروض الوضوء وصفته"]},{"id":11914,"question":"هل يجوز لنا التيمم إذا كان البحر قريبًا منا، علمًا بأن الماء الذي معنا مخصص للشرب والأكل؟","title":"حكم التيمم مع قرب ماء البحر","answer":"الجواب:  نعم ليس لكم التيمم، ما دام البحر قريبًا؛ توضؤوا من البحر، يقول فيه النبي ﷺ: هو الطهور ماؤه، الحل ميتته، فالبحر ماؤه طهور والحمد لله، ولو كان مالحًا؛ يلزمكم الوضوء والغسل للجنابة من ماء البحر. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10098/حكم-التيمم-مع-قرب-ماء-البحر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_426/42615.mp3","categories":["صلاة المريض","فروض الوضوء وصفته","التيمم"]},{"id":12070,"question":"من القاهرة المستمع محمد برعي يسأل سماحتكم عن الكيفية الصحيحة للوضوء؟ جزاكم الله خيرًا.","title":"صفة وضوء النبي صلى الله عليه وسلم","answer":"الجواب:  النبي ﷺ وضح للأمة الوضوء، ارجع إليه ﷺ تفسيرًا لقوله تعالى: يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا قُمْتُمْ إِلَى الصَّلاةِ فَاغْسِلُوا وُجُوهَكُمْ وَأَيْدِيَكُمْ إِلَى الْمَرَافِقِ وَامْسَحُوا بِرُءُوسِكُمْ وَأَرْجُلَكُمْ إِلَى الْكَعْبَيْنِ [المائدة:6] فسره النبي ﷺ، فسرها بفعله للصحابة. فكان -عليه الصلاة والسلام- إذا قام للوضوء؛ غسل كفيه ثلاث مرات أولًا، وهذا مستحب، ثم يبدأ فيتمضمض ويستنشق، ويغسل وجهه عمومًا من منابت شعر الرأس إلى الذقن طولًا، وعرضًا إلى فروع الأذنين، ثم يغسل ذراعيه مع المرفقين، ثم يمسح رأسه مع أذنيه، ثم يغسل رجليه مع الكعبين، هكذا كان يفعل ﷺ هذه صفة وضوئه، يغسل كفيه ثلاثًا أولًا، ولاسيما إذا قام من النوم يتأكد ذلك، فيجب أن يغسل كفيه ثلاث مرات قبل إدخال يده في الإناء، ثم يبدأ فيتمضمض ويستنشق ويستنثر ويغسل وجهه. والواجب مرة، الواجب مرة؛ لأن الرسول ﷺ توضأ مرة مرة، ثم يغسل ذراعيه مرة مرة مع المرفقين، ثم يمسح رأسه كله مرة واحدة مع أذنيه، يدخل أصبعيه سباحتيه في صماخ أذنيه، ويمسح ظاهر أذنيه بإبهاميه، ثم يغسل رجليه مع الكعبين مرة واحدة هذا الواجب، وتوضأ لهم مرتين مرتين وتوضأ لهم ثلاثًا ثلاثًا حتى يعلموا السنة، فالمرة الواحدة هذه فريضة، والمرة الثانية سنة، والثلاث هي الكمال، أفضل ما يكون ثلاثًا ثلاثًا، وهو الغالب من فعله -عليه الصلاة والسلام-إلا الرأس مسحة واحدة، لا يكرر ثلاثًا، الرأس يمسحه مرة، يبدأ بمقدمه إلى قفاه، ثم يرد يديه إلى المكان الذي بدأ منه، هكذا كان يفعل، عليه الصلاة والسلام. والواجب أن تكون المرفقان داخلين في غسل اليدين، وهكذا الكعبان في الرجلين يدخلان في غسل الرجلين، قال أبو هريرة  : كان النبي ﷺ إذا غسل يديه؛ أشرع في العضد، وإذا غسل رجليه؛ أشرع في الساق، حتى يدخل بذلك المرفقين والكعبين فقوله -جل علا-: إِذَا قُمْتُمْ إِلَى الصَّلاةِ فَاغْسِلُوا وُجُوهَكُمْ وَأَيْدِيَكُمْ إِلَى الْمَرَافِقِ [المائدة:6] (إلى) يعني: مع المرافق، وقوله -جل وعلا-: وَامْسَحُوا بِرُءُوسِكُمْ وَأَرْجُلَكُمْ إِلَى الْكَعْبَيْنِ [المائدة:6]، معناه مع الكعبين، فالكعب مغسول والمرفق مغسول. هذه صفة وضوئه -عليه الصلاة والسلام- مرة مرة، ومرتين مرتين، وثلاثًا ثلاثًا، وربما غسل بعض الأعضاء مرتين، وبعضها ثلاثًا، فالأمر واسع، الواجب مرة مرة، يتمضمض مرة، ويستنشق مرة، ويغسل وجهه مرة يعمه بالغسل، ثم اليدين مرة مرة، ثم يمسح رأسه مع أذنيه مرة، ثم يغسل رجليه مع الكعبين مرة، هذا هو الواجب. والأفضل أن يزيد، فيكرر في غسل الوجه واليدين والرجلين مرتين أو ثلاثًا، والثلاث أكمل وأفضل، أما الرأس فإنه يكفيه مرة واحدة لا يكرر، يمسحه مرة واحدة بيديه مع الأذنين، والأفضل أن يبدأ بالمقدم ثم يمر يديه إلى قفاه، ثم يعيدهما إلى ........، مع إدخال أصبعيه في أذنيه، ومسح ظاهرهما بأصبعيه، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10255/صفة-وضوء-النبي-صلى-الله-عليه-وسلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_435/43503.mp3","categories":["فروض الوضوء وصفته"]},{"id":12125,"question":"من إحدى الأخوات المستمعات رسالة تقول في نهايتها: المرسلة أختكم في الله، أختنا في الله ضمنت رسالتها أكثر من خمسة أسئلة، فتسأل في أحدها عن حكم من نسي التسمية عند الوضوء، جزاكم الله خيرًا؟","title":"حكم من نسي التسمية عند الوضوء","answer":"الجواب:  من نسيها عند الوضوء؛ فلا شيء عليه، ولو تعمدها فوضوؤه صحيح عند أكثر أهل العلم، وقال بعض أهل العلم: إذا تعمدها وهو يعلم الحكم الشرعي يعيد الوضوء، والصواب أنه لا يعيد، الصواب أنه لا يعيد إذا كان عنده جهل، أو شك في وجوبها عليه، أو يعتقد أنها مستحبة فقط، ليس عليه إعادة الوضوء، ولكن يشرع له أن يسمي عند الوضوء، فإن نسي ذلك، أو جهل ذلك، أو شك في وجوب ذلك وضوؤه صحيح، والحمد لله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10310/حكم-من-نسي-التسمية-عند-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_438/43810.mp3","categories":["فروض الوضوء وصفته"]},{"id":12177,"question":"من مدينة العيص في ضواحي ينبع المستمع: مساعد مرزوق السناني بعث برسالة ضمنها بعض الأسئلة، يقول في أحدها: رجل اغتسل غسل الجمعة، وصلى مع الجماعة، وهو لم يتوضأ وضوء الصلاة، ولم يذكر ذلك إلا وهو في الصلاة، لم يذكر أنه لم يتوضأ بعد الغسل، فصلى معهم، فهل صلاته صحيحة؟ أم ماذا يجب عليه إذا كانت صلاته غير صحيحة بعد مضي وقت طويل؟","title":"حكم الوضوء أثناء الاغتسال","answer":"الجواب:  عليه أن يعيد الصلاة ظهرًا، يصلي ظهرًا؛ لأن الغسل لا يكفيه عن الوضوء، غسل الجمعة لا يكفي، بل لا بد من الوضوء الشرعي، لكن لو كان غسل الجنابة ونوى الحدثين؛ أجزأ، أما غسل المستحب غسل الجمعة؛ فهذا لا يكفي، بل عليه أن يعيد الصلاة ظهرًا؛ لأن الجمعة لا تقضى إلا ظهرًا، نعم. المقدم: جزاكم الله خيرًا، إذًا الغسل المستحب لا يجزي عن الوضوء حتى نوى؟ الشيخ: لا يجزي عن الوضوء، لا، إلا إذا رتب. المقدم: إلا إذا رتب. الشيخ: غسل وجهه، ثم يديه، ثم مسح رأسه وأذنيه، ثم غسل رجليه في أثناء الغسل؛ لا بأس يكفي. المقدم: يعني كأنه توضأ؟ الشيخ: نعم، توضأ وهو يغتسل ما يخالف. المقدم: جزاكم الله خيرًا. الشيخ: بالترتيب يعني والنية، نعم. المقدم: نعم نعم، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10363/حكم-الوضوء-اثناء-الاغتسال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_443/44304.mp3","categories":["فروض الوضوء وصفته"]},{"id":12283,"question":"تقول: الخضاب بالسواد على اليدين والقدمين هل يمنع وصول الماء إلى البشرة، أم لا؟ أفيدونا، جزاكم الله خيرًا.","title":"حكم خضاب المرأة ليديها ورجليها بالسواد","answer":"الجواب:  إذا لم يكن له جرم؛ فلا يمنع، ولا بأس، الحناء وأشباهه، الدسم وأشباه ذلك لا يمنع، أما إذا كان له جرم يعني: غليظ، بحيث يمكن إزالته، وحكه، فإنه يزال كالمناكير التي تكون على الأظفار، يكون لها جرم، تزال، أما إذا كان مجرد صبغ فقط، فإنه لا يمنع الماء، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10483/حكم-خضاب-المراة-ليديها-ورجليها-بالسواد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_452/45203.mp3","categories":["فروض الوضوء وصفته"]},{"id":12746,"question":"هل يجوز أن يتوضأ الشخص في دورة المياه، أكرمكم الله؟","title":"حكم الوضوء داخل الحمام","answer":"الجواب:  لا بأس في ذلك، لا حرج في ذلك، ولا بأس أن يسمي الله، يسمي الله عند بدء الوضوء، وإذا خرج يتشهد؛ لأن بدء الوضوء بالتسمية واجب عند جمع من أهل العلم، ومتأكد، فلا يمنعه كونه في الدورة، وإذا توضأ خارج الدورة؛ كان أفضل إذا تيسر ذلك، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10960/حكم-الوضوء-داخل-الحمام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_418/41817.mp3","categories":["فروض الوضوء وصفته"]},{"id":12802,"question":"هل الاحتفاظ بالوضوء ليوم كامل يجوز؟","title":"حكم تأدية عدة صلوات مفروضة بوضوء واحد","answer":"الجواب:  لا حرج في ذلك إذا استطعت، أما إذا كان ذلك فيه مشقة؛ فلا، تحدث وتتوضأ؛ لقوله ﷺ: لا صلاة بحضرة الطعام، ولا وهو يدافعه الأخبثان يعني: البول والغائط، فإذا بقيت على الطهارة من دون مشقة؛ صليت بها الظهر والعصر والمغرب والعشاء؛ فلا بأس، لكن إذا كان عندك مشقة مثل الريح، أو البول، أو غيرهما؛ فاقض حاجتك، ولا تشق على نفسك، بل اقض حاجتك، هذا هو الأفضل، وهذا هو السنة، حتى تصلي وأنت مطمئن خاشع. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11016/حكم-تادية-عدة-صلوات-مفروضة-بوضوء-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_462/46207.mp3","categories":["فروض الوضوء وصفته"]},{"id":12847,"question":"إذا استدعت الحاجة أن أستنشق أثناء الوضوء أكثر من ثلاث مرات، أو أتمضمض أكثر من ثلاث مرات، فهل يصح الوضوء؟","title":"حكم وضوء من زاد على الثلاث في المضمضة والاستنشاق","answer":"الجواب:  يصح الوضوء لكنك أخطأت، والواجب عليك التوبة من ذلك، جاء عن النبي ﷺ أنه قال -لما ذكر الثلاث- قال: من زاد عليها؛ فقد أساء وتعدى وظلم. فالسنة الثلاث، الثلاث غسلات لا زيادة، والاستنشاق كذلك ثلاث، تستنشق وتستنثر ثلاثًا، ولا تزد، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11062/حكم-وضوء-من-زاد-على-الثلاث-في-المضمضة-والاستنشاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_464/46413.mp3","categories":["فروض الوضوء وصفته"]},{"id":13097,"question":"السائلة تقول: سماحة الشيخ! إذا وضعت الحناء على الرأس هل يمنع وصول ماء الوضوء إلى فروة الرأس، وهل أكتفي بالمسح عليها أثناء الوضوء فقط؟","title":"كيفية المسح على الرأس إذا كان فيه حناء","answer":"الجواب:  الصواب: أنه يكفي إذا كان على الرأس لصوقات من حناء وغيرها، يمسح عليها؛ ويكفي والحمد لله، كما قالت عائشة -رضي الله عنها- أخبرت عائشة أنهم كانوا يضعون اللصوقات على رؤوسهم، ويمسحون عليها، والحمد لله.","link":"https://binbaz.org.sa/fatwas/11313/كيفية-المسح-على-الراس-اذا-كان-فيه-حناء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_508/50807.mp3","categories":["فروض الوضوء وصفته"]},{"id":13162,"question":"السائل يقول: هل يجب عند غسل اليد عند الوضوء من المرفق إلى الكف من الأعلى إلى الأسفل، أم أنه يجب التقيد باتجاه معين؟","title":"كيفية غسل اليدين في الوضوء","answer":"الجواب:  الواجب غسل اليد من أطراف الأصابع إلى المرفق في الوضوء، كان النبي ﷺ كان يغسل ذراعيه مع المرفقين حتى يشرع في العضد يعني: يدخل المرفقين في الغسل، سواء بدأ من أعلى، أو من أسفل، المهم أن يجري الماء على اليد من أطراف الأصابع إلى المرفق، إلى أول العضد، وهكذا في الرجل يجري الماء على الرجلين حتى ... الكعبين يشرع في الساق ، فتكون المرفقان والكعبان كلها داخلة في المغسول. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11417/كيفية-غسل-اليدين-في-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_510/51020.mp3","categories":["فروض الوضوء وصفته"]},{"id":13223,"question":"تقول السائلة: سماحة الشيخ، ما حكم مسح الرقبة في الوضوء؟","title":"ما حكم مسح الرقبة في الوضوء؟","answer":"الجواب:  غير مشروع، المشروع الرأس فقط، يمسح رأسه مع الأذنين، أما الرقبة لا تمسح، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11502/ما-حكم-مسح-الرقبة-في-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_520/52010.mp3","categories":["فروض الوضوء وصفته"]},{"id":13443,"question":"هذا السائل أبو عبدالله يقول: أحيانًا لا أدري هل أنا محدث، أم لا؟ وأتوضأ قطعًا للشك، فهل أنوي بهذا الوضوء بأنه عن رفع الحدث، أم أنوي أنه وضوء شرعي فقط؟","title":"من شك في وضوئه هل يتوضأ بنية رفع الحدث؟","answer":"الجواب: كله طيب، إذا نويت عن رفع الحدث، أو نويت الوضوء الشرعي؛ كفى والحمد لله. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11740/من-شك-في-وضوىه-هل-يتوضا-بنية-رفع-الحدث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_527/52713.mp3","categories":["فروض الوضوء وصفته"]},{"id":13449,"question":"إذا اغتسل الإنسان للجنابة، فهل يكفيه ذلك عن الوضوء؟","title":"هل يكفي غسل الجنابة عن الوضوء؟","answer":"الجواب: إذا نواهما جميعًا فلا بأس، إذا نوى الوضوء والغسل للجنابة أجزأه، لكن الأفضل يتوضأ، ثم يغتسل، هذا الأفضل، ويتوضأ وضوء الصلاة، ثم يغتسل، يعني: يفيض الماء على رأسه، وعلى جسده، ثم على رأسه ثلاثًا، ثم على شقه الأيمن، ثم الأيسر، والمرأة كذلك تستنجي، ثم تتوضأ وضوء الصلاة، ثم تغتسل، سواء كان من الجنابة، أو لغير ذلك، هذا .. الظاهر الأفضل، الأفضل هكذا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11748/هل-يكفي-غسل-الجنابة-عن-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_516/51615.mp3","categories":["فروض الوضوء وصفته"]},{"id":13547,"question":"تسأل أيضًا وتقول: هل الزيوت التي تضعها المرأة على رأسها يمنع وصول الماء إلى الرأس بحيث يكون الوضوء والغسل باطلًا؟","title":"هل الزيوت تمنع وصول الماء في الوضوء والغسل؟","answer":"الجواب: لا، لا يمنع، الزيت الذي يكون في الرأس، زيت وأشباهه مما يوضع على الرأس لا يمنع كالحناء أو نحوه. نعم.","link":"https://binbaz.org.sa/fatwas/11870/هل-الزيوت-تمنع-وصول-الماء-في-الوضوء-والغسل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_480/48003.mp3","categories":["فروض الوضوء وصفته","قضايا المرأة"]},{"id":13693,"question":"كيف يسمي من أراد الوضوء في داخل دورة المياه؟ وهل له أن يذكر اسم الله وهو داخل الدورة؟","title":"كيف يسمي المتوضئ داخل دورة المياه؟","answer":"الجواب: نعم نعم، يسمي عند بدء الوضوء، عند غسل يديه، كفيه للوضوء يقول: باسم الله، ثم يشرع؛ لأنها حاجة، وجمع من أهل العلم يراها واجبة، هذه التسمية، فعند وجوبها وتأكدها تزول الكراهة، ولو أنه في دورة المياه. نعم.. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12064/كيف-يسمي-المتوضى-داخل-دورة-المياه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_481/48103.mp3","categories":["فروض الوضوء وصفته"]},{"id":13858,"question":"أخيرًا هذا  هل يصح الوضوء في الحمام؟","title":"هل يصح الوضوء في الحمام؟","answer":"الجواب: نعم، لا حرج أن يتوضأ في الحمام ويسمي في أول الوضوء عند أول ما يبدأ الوضوء بالمضمضة والاستنشاق، أو عند غسل الكفين ثلاثًا يقول: باسم الله. ويبدأ؛ لأن الكراهة التي ذكرها العلماء في كراهة ذكر الله في الحمام تزول عند الحاجة، وهو محتاج إلى أن يسمي الله في أول وضوئه، وقد أوجب ذلك بعض أهل العلم فحينئذ تزول الكراهة ويسمي الله عند بدء وضوئه، فإن تيسر أن يكون ذلك خارج الحمام فهذا أفضل وأتم. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12234/هل-يصح-الوضوء-في-الحمام ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_603/60305.mp3","categories":["فروض الوضوء وصفته"]},{"id":13955,"question":"تقول: إنها طالبة كما ذكرت في المدرسة وعندما تريد أن تتوضأ لا يرتفع ثوبها إلى ما فوق المرفق نظرًا لضيق الكم فهل لها أن تمسح؟","title":"حكم مسح المرفق بسبب ضيق الكم","answer":"الجواب: ليس لها ذلك، وليس لها لبس الضيق فهذا لا يجوز بل عليها أن تلبس لباسًا يمكن حسره عن مرفقها حتى تغسل المرفق، والمرفق من الذراع لابد منه، لابد أن تغسل ذراعها مع المرفق، والواجب عليها ترك هذا الضيق وأن تلبس لباسًا تستطيع معه غسل مرافقها، نعم نسأل الله الهداية للجميع.\nالمقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/12367/حكم-مسح-المرفق-بسبب-ضيق-الكم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_604/60413.mp3","categories":["فروض الوضوء وصفته"]},{"id":13989,"question":"في آخر أسئلة هذه السائلة تقول سماحة الشيخ: هل مسح الرأس في الصلاة يكون مرة واحدة؟ وماذا تفعل المرأة؛ هل تمسح جميع الرأس؟ وماذا تفعل إذا كان الشعر طويل؟","title":"كيفية مسح المرأة رأسها أثناء الوضوء","answer":"الجواب: مسح الرأس فرض من فروض الوضوء على الرجل والمرأة، تمسح رأسها كما يمسح الرجل رأسه، والمقصود منابت الشعر من مقدمه إلى مؤخره، أما الذوائب ما حاجة إلى مسحها، لكن تمسح من مقدمه إلى مؤخره، ... منابت الشعر، أما الذوائب النازلة عن ذلك فلا يجب مسحها، وإذا كان عليه ضمادات من حناء أو غيره فلا يضر، قالت عائشة: \"كنا نمسح على الضمادات في عهد النبي ﷺ\"، فإذا مسحت على ما في رأسها من ضماد من حناء أو غيره فلا بأس. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12404/كيفية-مسح-المراة-راسها-اثناء-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_539/53915.mp3","categories":["فروض الوضوء وصفته","قضايا المرأة"]},{"id":14052,"question":"هل يجوز ذكر لا إله إلا الله عند غسل الوجوه وعند الوضوء؟ أم أنه لا يلزم ذلك؟","title":"حكم التهليل عند غسل الوجه أثناء الوضوء","answer":"الجواب: ليس هذا مشروع لا أصل له، ولكن يسمي عند بدء الوضوء يقول: باسم الله عند أول ما يتوضأ، وبعد الفراغ يقول: أشهد أن لا إله إلا الله، وحده لا شريك له، وأشهد أن محمدًا عبده ورسوله. أما كونه يقولها عند الوضوء عند أعضاء الوضوء هذا ما هو بمشروع، لكن لو قالها من غير قصد أنه مشروع لأنه يحب ذكر الله، ما في بأس، من باب محبة ذكر الله جل وعلا، أما أن يعتقد أنه يشرع أن يقولها عند غسل اليدين، عند غسل الوجه هذا ليس عليه دليل، بل هذا الاعتقاد بدعة، ولكن يأتي بالشهادتين بعد الفراغ من الوضوء، إذا فرغ يقول: أشهد أن لا إله إلا الله وحده لا شريك له، وأشهد أن محمدًا عبده ورسوله، اللهم اجعلني من التوابين واجعلني من المتطهرين، هذا سنة.  وفي الحديث الآخر يقول: سبحانك اللهم وبحمدك أشهد أن لا إله إلا أنت أستغفرك اللهم وأتوب إليك بعد الوضوء أيضًا مثل ذكره إذا قام من المجلس، سبحانك اللهم وبحمدك أشهد أن لا إله إلا أنت أستغفرك اللهم وأتوب إليك، كل هذا مستحب بعد الوضوء.  ثبت عنه ﷺ أنه قال: ما منكم من أحد يتوضأ فيبلغ الوضوء -أو قال: يسبغ الوضوء ثم يقول: أشهد أن لا إله إلا الله وحده لا شريك له، وأشهد أن محمدًا عبده ورسوله إلا فتحت له أبواب الجنة الثمانية، يدخل من أيها شاء، رواه مسلم في صحيحه، زاد الإمام الترمذي رحمه الله في هذا الحديث في آخره: اللهم اجعلني من التوابين، واجعلني من المتطهرين، وهذه الزيادة صحيحة، نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12475/حكم-التهليل-عند-غسل-الوجه-اثناء-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_484/48403.mp3","categories":["فروض الوضوء وصفته"]},{"id":14430,"question":"من قرى المدينة المنورة المستمع (ع. ب. س) بعث برسالة يقول فيها: عرفنا أن فريضة الصلاة قد فرضت قبل الهجرة، أي: في ليلة الإسراء والمعراج، هل فريضة الوضوء ومشروعية التيمم أيضًا قبل الهجرة أم بعدها؟ وإذا كانت بعد الهجرة ففي أي السنين جاءت فريضة الوضوء ومشروعية التيمم؟وجهونا حول هذا الموضوع، جزاكم الله خيرًا.","title":"متى شرع الوضوء والتيمم؟","answer":"الجواب: أما الوضوء فالأصل في ذلك أنه شرع مع الصلاة؛ لأن النبي  قال: لا تقبل صلاة بغير طهور فالأصل في هذا أن الله شرع الوضوء مع الصلاة.  أما التيمم فلم يشرع إلا في المدينة بعد مدة طويلة شرع التيمم بعد ذلك في المدينة، وأما الوضوء فهو مشروع مع الصلاة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12929/متى-شرع-الوضوء-والتيمم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_624/62407.mp3","categories":["التيمم","فروض الوضوء وصفته"]},{"id":14572,"question":"السائلة التي رمزت لاسمها بـ (ع. ف) تقول: سماحة الشيخ، عندما نريد أن نتوضأ من أحد المساجد وعندما نقوم بفتح الماء يخرج لنا مياه مختلطة بالصدأ بفعل الأنابيب أو أنابيب المياه، هل نتوضأ من هذه المياه المصدية؟ أم نقوم بصرف الماء بكثرة حتى يخرج لنا ماء صافٍ؟","title":"حكم الوضوء بالماء إذا كان فيه صدأ","answer":"الجواب: لا حرج في الوضوء والغسل بالماء المتغير بالصدأ لا يضر، يغتسل به، ويتوضأ منه، ولا يضره الصدأ، والحمد لله، وهكذا إذا تغير بالتراب أو بأوراق الشجر، أو ما أشبه ذلك، ما يضره ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13069/حكم-الوضوء-بالماء-اذا-كان-فيه-صدا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_556/55610.mp3","categories":["فروض الوضوء وصفته"]},{"id":14653,"question":"يقول في سؤاله الثاني سماحة الشيخ: نرى البعض من الناس يصلون بدون وضوء نهائيًا، وأحيانًا لا يتمون التيمم مع توفر الماء، وعند مناقشتهم يحتج هؤلاء بأنهم يعيشون في الصحراء، والماء قليل، مع أن مصادر جلب الماء موجود، والماء متوفر، و هل الصلاة في مثل هذه الحالة صحيحة؟","title":"حكم اكتفاء أهل الصحراء بالتيمم للصلاة","answer":"الجواب: الواجب على كل مسلم أن يتوضأ للصلاة عند وجود الماء، والقدرة على استعماله، فإن عجز لبعد الماء، وعدم وجوده، أو لمرض يمنعه من ذلك، وجب عليه التيمم بالتراب، يضرب الأرض بيديه، ويمسح وجهه وكفيه، هذا هو الواجب، فمن صلى بدون وضوء، ولا تيمم صلاته باطلة، لا بد من أحد الأمرين، الوضوء عند القدرة، وعند وجود الماء والقدرة على استعماله، وإذا كان قريبًا أمكن نقله يذهب ويتوضأ، أو ينقل الماء في سيارته، أو في دابته ليشرب ويتوضأ. أما من عجز عن الماء لمرض يضره الماء، أو لعدم وجود الماء ليس معهم إلا ماء قليل لشأن حاجته لأكله وشربه فإنه يتيمم، والحمد لله؛ لأن الله يقول: فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا صَعِيدًا طَيِّبًا [النساء:43] ويقول النبي ﷺ: الصعيد وضوء المسلم، وإن لم يجد الماء عشر سنين يتيمم من الأرض التي هو فيها يضرب التراب بيديه ويمسح وجهه وكفيه، هذا هو الواجب على كل مسلم. ومن عجز عن التيمم، وعن الماء فهو معذور، لو كان إنسانًا مربوطًا في سارية أو عمود، ولا يستطيع لا يتيمم ولا يتوضأ، صلى على حسب حاله، أو مريض لا يستطيع التحرك، وليس عنده من يوضئه، ولا من يممه، صلى على حسب حاله : فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286]، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13141/حكم-اكتفاء-اهل-الصحراء-بالتيمم-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_559/55919.mp3","categories":["فروض الوضوء وصفته"]},{"id":14664,"question":"هل المكياج يمنع وصول الماء أثناء الوضوء، بمعنى: هل يجب أن نزيل هذا المكياج عند كل وضوء؟","title":"حكم إزالة المرأة المكياج أثناء الوضوء","answer":"الجواب: إذا كان المكياج له جسم يمنع الماء يزال، وإن كان ما له جسم مجرد صبغ لا يكون له جرم فلا يلزم إزالته.  أما إذا كان له جسم يحصل له منع، يعني: يمنع الماء فهذا يجب أن يزال من الوجه، وهكذا من الذراع إذا كان فيه شيء كعجين يزال، أو من الوجه عجين، أو من الرجل، أما إذا كان شيء لا، صبغة ما له جسم، ما له جرم، هذا ما تجب إزالته، نعم.","link":"https://binbaz.org.sa/fatwas/13153/حكم-ازالة-المراة-المكياج-اثناء-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_560/56005.mp3","categories":["فروض الوضوء وصفته","قضايا المرأة"]},{"id":14711,"question":"في ثالث أسئلته يقول: شخص بدأ في الوضوء لبعض أعضاء جسمه، فانقطع عليه الماء، فذهب إلى مكان آخر، وأكمل ما تبقى من أعضاء جسمه، فهل هذا الوضوء صحيح؟","title":"حكم وضوء من شرع بمكان ثم أكمله في مكان آخر","answer":"الجواب: إذا كانت المدة غير طويلة فلا بأس، إذا كانت المدة الفاصلة خفيفة فلا بأس، وإلا فليعيده من أوله.","link":"https://binbaz.org.sa/fatwas/13195/حكم-وضوء-من-شرع-بمكان-ثم-اكمله-في-مكان-اخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_560/56021.mp3","categories":["فروض الوضوء وصفته"]},{"id":14713,"question":"المستمع أحمد نصر السيد، من جمهورية مصر العربية، ويعمل في دولة العراق أيضًا يقول: إنني أعمل سائق، وعملي دائمًا في الصحراء، وحيث أنه يأتي علي وقت الظهر والعصر، ولا يوجد ماء إلا ماء الآبار، وحيث أن ماء الآبار يتغير طعمه، إما يكون مالحًا أو مرًا، هل يجوز الوضوء منه أم أن لي التيمم؟جزاكم الله خيرًا.","title":"حكم الوضوء من مياه الآبار المتغيرة","answer":"الجواب: يلزمك الوضوء من ماء الآبار إذا قدرت على ذلك، سواء كان حلوًا أو مرًا أو مالحًا، حتى ماء البحر يجب عليك الوضوء منه إذا كنت في البحر، وليس لك التيمم وأنت تجد الماء؛ لأن الله سبحانه يقول: فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا[النساء:43] والنبي ﷺ يقول: جعلت تربتها لنا طهورًا إذا لم نجد الماء فلو وجد الماء ولو مالحًا ولو ماء البحر وجب عليه الوضوء، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13199/حكم-الوضوء-من-مياه-الابار-المتغيرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_637/nour_63706.mp3","categories":["فروض الوضوء وصفته","المياه"]},{"id":14723,"question":"هل الزيادة في الوضوء لأكثر من ثلاث مرات للعضو يعتبر بدعة أم لا سماحة الشيخ؟","title":"حكم زياد الغسل في الوضوء عن ثلاث","answer":"الجواب: لا يجوز لا يجوز، الرسول ﷺ نهى عن هذا، السنة ثلاث فأقل، واحدة مجزئة، وثنتين أفضل والثلاث أفضل، في بعض الروايات: من زاد فقد تعدى وأساء وظلم فلا ينبغي الزيادة، لا تنبغي الزيادة، نعم. المقدم: طيب إذا زاد سماحة الشيخ، وهو أكثر من ثلاث أربع أو خمس، هل للمشاهد لهذا المتوضئ أن يمنعه؟\nالجواب: لا، ينبهه، يقول: ترى هذا ما يجوز، أو مكروه، على الأقل مكروه كراهة شديدة ينبهه. المقدم: طيب جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13210/حكم-زياد-الغسل-في-الوضوء-عن-ثلاث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_560/56027.mp3","categories":["فروض الوضوء وصفته"]},{"id":14790,"question":"هذا السائل: (ش) من الشام يقول: أنا طالب في المدرسة، عندما أكتب يصب في يدي الحبر؛ وذلك من القلم، فأتوضأ والحبر على يدي، ثم أتذكر وجود ذلك الحبر، فأزيله، وأتوضأ من جديد، لكن ذلك تكرر معي كثيرًا، وشق علي أكثر، بعد ذلك أغتسل ثم أذكر وجود الحبر فأغسل يدي، هل وضوئي وغسلي صحيح يا فضيلة الشيخ؟","title":"حكم الوضوء أو الغسل وعلى اليدين حبر","answer":"الجواب: إن كان الحبر له جسم يمنع الماء فلا بد تعيد الوضوء، في ذراعك أو في رجلك، لا بد تعيد الوضوء.  أما إن كان ما له جسم مجرد صفرة، أو سواد صبغ ما يمنع الماء، فلا بأس ولا حرج، أما إذا كان له جسم يمنع الماء فهذا لا بد من إزالته قبل الوضوء، وإذا نسيت ولم تزله تعيد الوضوء، وهكذا في الغسل، لا بد أن تزيله عند غسل الجنابة، إذا كان له جسم.  أما إذا كان ما له جسم، إنما هو مجرد صورة سواد، صورة حمرة، صورة شهبة، فهذا ما يضر ما يمنع؛ لأنه ما له جسم، نعم.","link":"https://binbaz.org.sa/fatwas/13279/حكم-الوضوء-او-الغسل-وعلى-اليدين-حبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_561/56113.mp3","categories":["فروض الوضوء وصفته"]},{"id":14834,"question":"المستمع (م. ع. ع) من شرورة، بعث برسالة ضمنها ثلاثة أسئلة، في سؤاله الأول يقول: هل وصول الماء إلى بشرة اللحية واجب ضروري، أم يكفي مرور الماء فوق الشعر؟جزاكم الله خيرًا.","title":"حكم وصول الماء إلى بشرة اللحية","answer":"الجواب: إذا كانت اللحية كثيفة كفى مرور الماء عليها، وإن خللها فهو أفضل، خللها وعركها فهو أفضل، وإلا كان النبي ﷺ يمر الماء عليها، وربما خللها بعض الأحيان -عليه الصلاة والسلام-. أما إن كانت صغيرة ما تستر البشرة، فإنه يعركها حتى يصل الماء إلى البشرة، إذا كانت صغيرة ما تستر البشرة، فإنه يغسل البشرة مع الشعر؛ لأنها حينئذٍ وجودها كعدمها قليلة.  أما الكثيفة التي تستر البشرة لكثافتها، فإنه يكفي مرور الماء عليها جميعها، إذا أجرى عليها الماء كفى، وإن خللها فهو أفضل. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13322/حكم-وصول-الماء-الى-بشرة-اللحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_491/49105.mp3","categories":["فروض الوضوء وصفته"]},{"id":15010,"question":"فضيلة الشيخ عبدالعزيز هذه رسالتان وردتنا من سعيد بن محمد من سلطنة عمان، وسالم محمد سالم أيضًا اتفق بسؤالٍ مع سعيد بن محمد من سلطنة عمان، نبدأ برسالة سعيد من سلطنة عمان، تحمل عدة أسئلة:أولًا: يثني على مجهود المشايخ، ويطلب لهم العمر المديد على زيادة عمل صالح، يقول: حددوا لنا الوضوء من الفرض والسنة؟","title":"فروض الوضوء وسننه","answer":"الجواب: بسم الله الرحمن الرحيم. الحمد لله، والصلاة والسلام على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فإن الله -جل وعلا- شرع لعباده الوضوء عند إرادة الصلاة، قال سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا قُمْتُمْ إِلَى الصَّلاةِ فَاغْسِلُوا وُجُوهَكُمْ وَأَيْدِيَكُمْ إِلَى الْمَرَافِقِ وَامْسَحُوا بِرُءُوسِكُمْ وَأَرْجُلَكُمْ إِلَى الْكَعْبَيْنِ [المائدة:6] الآية، فهذا يدل على وجوب استعمال الوضوء الشرعي على ضوء ما ذكرته الآية الكريمة، وقد فسر النبي ﷺ ذلك بفعله -عليه الصلاة والسلام-، فدل ذلك على أنه لا بد لمن قام إلى الصلاة من الوضوء الشرعي إذا كان على غير طهارة، وهو كما بينه الله: غسل الوجه، ثم غسل اليدين مع المرفقين، ثم مسح الرأس، ثم غسل الرجلين، وهذا فرض، والمفترض مرةً مرة. والسنة أن يغسل قبل ذلك يديه ثلاث مرات، قبل إدخالهما في الإناء، كما بينه النبي -عليه الصلاة والسلام- فيغسل يديه ثلاث مرات، يعني: كفيه، ثم يشرع في الوضوء، وينبغي أن يقدم التسمية على غسل اليدين، فيقول: باسم الله، قبل أن يغسل يديه.  والجمهور على أنها سنة، وذهب بعض أهل العلم إلى وجوب التسمية مع الذكر، وسقوطها مع الجهل والنسيان؛ لما جاء عنه -عليه الصلاة والسلام- أنه قال: لا وضوء لمن لم يذكر اسم الله عليه وهو حديث له طرق، وفيها ضعف، لكن مجموعها يدل على أن له أصلًا، وأنه حسن، فينبغي لمن أراد الوضوء أن يسمي الله عند بدئه بغسل اليدين، ثم يتمضمض ويستنشق، ثم يغسل وجهه، من منابت الشعر، من الأعلى إلى الذقن من أسفل، وعرضًا إلى فروع الأذنين، هذا الوجه، فيغسله جميعًا، ثم يغسل يديه إلى المرفقين، ومعنى (إلى): مع، يعني: مع المرفقين، ويدل على ذلك فعله ﷺ، فإنه كان يغسل يديه حتى يشرع في العضد، يعني يغسل مرافقه مع الذراع، ثم يمسح رأسه مع أذنيه، كما جاءت به السنة، وهذا فرض أيضًا، ثم يغسل رجليه إلى الكعبين، يعني: مع الكعبين، ويدل على هذا فعله ﷺ؛ فإنه كان يغسل رجليه حتى يشرع في الساقين، كما رواه مسلم في الصحيح من حديث أبي هريرة. هذا هو الوضوء المفترض، غسل الوجه مع المضمضة والاستنشاق مرةً مرة، غسل اليدين مع المرفقين مرة، مسح الرأس مع الأذنين مرة، غسل الرجلين مع الكعبين مرة، هذا المفترض، فإن كرره مرتين؛ فهو أفضل، وسنة، وإن كرره ثلاثًا؛ فهو أكمل وأكمل، كما بينه النبي -عليه الصلاة والسلام- في عمله، وفعله -عليه الصلاة والسلام-، ويتمضمض ويستنشق مرةً واحدة، وهذا فرض، وإن كرر المضمضة والاستنشاق ثلاث مرات، فهذا أكمل وأفضل. ثم بعد ذلك يقول: أشهد أن لا إله إلا الله وحده لا شريك له، وأشهد أن محمدًا عبده ورسوله، اللهم اجعلني من التوابين، واجعلني من المتطهرين هكذا جاء في الحديث الصحيح وهذا سنة، بعد الفراغ، يقول: أشهد أن لا إله إلا الله وحده، لا شريك له، وأشهد أن محمدًا عبده ورسوله رواه مسلم في صحيحه عن عمر ، عن النبي -عليه الصلاة والسلام- أنه قال: ما من عبد يتوضأ فيسبغ الوضوء أو قال: فيبلغ الوضوء، ثم يقول: أشهد أن لا إله إلا الله وحده لا شريك له، وأشهد أن محمدًا عبده ورسوله؛ إلا فتحت له أبواب الجنة الثمانية، يدخل من أيها شاء وهذا فضل عظيم، هذا فضل عظيم في هذه الشهادة، بعد الوضوء، ويستحب أن يزيد: اللهم اجعلني من التوابين، واجعلني من المتطهرين؛ لما رواه الترمذي -رحمه الله- بإسناد صحيح، عن المغيرة بهذه الزيادة. وبهذا يعلم المفترض من الوضوء والسنة، فالتسمية في أول الوضوء سنة، تكرار المضمضة والاستنشاق مرتين أو ثلاث سنة، غسل الوجه أكثر من مرة سنة، غسل اليدين مع المرفقين مرة، هذا فرض، تكرار ذلك مرتين أو ثلاث سنة، مسح الرأس مع الأذنين فرض، ولا يشرع التكرار، غسل الرجلين مع الكعبين مرةً مرة فرض، تكرار ذلك مرتين أو ثلاث سنة، الشهادة بعد الوضوء والدعاء سنة، الذي تقدم ذكره، نعم.","link":"https://binbaz.org.sa/fatwas/13505/فروض-الوضوء-وسننه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_652/nour_65201.mp3","categories":["فروض الوضوء وصفته"]},{"id":15109,"question":"أحد الإخوة المستمعين، بعث برسالة ضمنها جمعًا من الأسئلة، وهو الأخ عبدالله أبو فديمر فيما يبدو، يقول في أحد أسئلته: سمعت بأن الشخص المسلم إذا لم يغسل رجليه إلى الكعبين ثلاث مرات؛ فإن ذلك محرم، فما مدى صحة ذلك؟ وحيث أنني أقوم بغسل رجلي تحت بزبوز الماء، بدون عدد الغسل، فهل أكون آثمًا؟","title":"حكم غسل الرجلين إلى الكعبين ثلاثًا","answer":"الجواب: هذا القول قول على الله بغير علم وغلط، الواجب مرة واحدة، والثلاث أفضل، النبي ﷺ توضأ مرة مرة، وتوضأ مرتين مرتين، وتوضأ ثلاثًا ثلاثًا -عليه الصلاة والسلام-، فإن توضأ مرة، وغسل وجهه مرة، وتمضمض مرة، واستنشق مرة، وغسل يديه مرة، ومسح رأسه مرة، وغسل رجليه مرة، كفى، إذا عمم الغسل، إذا عم العضو، إذا أجرى عليه الماء مرة واحدة، كفى، بحيث يتمضمض ويستنشق مرة واحدة، ويصب الماء على وجهه مرة واحدة ويعمه بالماء، يكفي، وهكذا يداه اليمنى واليسرى، يعمهما بالماء مرة واحدة، يكفي، وهكذا رأسه يمسح رأسه وأذنيه مرة واحدة، ويغسل قدمه اليمنى مرة واحدة واليسرى كذلك، يكفي. لكن إذا كرر ثلاثًا فهو أفضل وأكمل، والثنتين أكمل من الواحدة، ومعنى غسله: كونه يعمه بالماء، ولو بغرفتين، ولو بثلاث غرفات، ولو تحت الكباس البزبوز يعمه بالماء هذه مرة، فإذا أعاد تعميمه بالماء هذه ثانية، فإذا أعاد رجله تحت البزبوز مرة ثالثة هذه ثالثة، ولكن ليس بشرط الثلاث لا، يكفي مرة واحدة، إذا عمه بالماء تحت الكباس مرة واحدة، كفى، أو بالماء الذي يأخذه من الإناء يغرف من الإناء، ويصبه على أعضائه يكفي مرة واحدة. وقول من قال: إنه لا بد من ثلاث خطأ، الصواب يكفي مرة واحدة، إذا عم العضو بالماء، سواء عمه بغسلة أو بغسلتين أو بأكثر، لا بد يعمه بالماء، الوجه واليدين والرجلين. أما الرأس السنة واحدة مطلقًا، السنة ألا يمسح إلا مرة واحدة مطلقًا مع الأذنين. أما الأعضاء الثلاثة: الوجه، واليدين، والرجلين، فالسنة تعميمها بالماء ثلاث مرات، فإن اقتصر على مرتين، أو على واحدة، كفى، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13609/حكم-غسل-الرجلين-الى-الكعبين-ثلاثا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_494/49406.mp3","categories":["فروض الوضوء وصفته"]},{"id":15156,"question":"إذا خرج من الإنسان ريح هل يجب عليه أن يستنجي أم يتوضأ مباشرة؟","title":"من خرج منه ريح هل يجب عليه أن يستنجي؟","answer":"الجواب: الريح لا توجب الاستنجاء، الريح فيها الوضوء الذي يسمونه التمسح، غسل الوجه واليدين ومسح الرأس والأذنين وغسل الرجلين، هذا التمسح، وهو الوضوء المطلق، إذا كان ريح أو مس الفرج باليد، أو نوم ما فيه استنجاء، الاستنجاء يكون من البول والغائط، إذا كان خرج البول من الذكر أو غائط من الدبر، وهذا محل الاستنجاء.  أما إذا انتقض وضوؤه بالريح أو بالنوم أي: المستغرق، كل هذا ما فيه استنجاء، إنما يتمسح، يعني: يتوضأ الوضوء الشرعي بالتمضمض والاستنشاق وغسل الوجه، وغسل اليدين مع المرفقين، ومسح الرأس مع الأذنين وغسل الرجلين مع الكعبين، هذا هو الوضوء إذا أطلق الوضوء، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13648/من-خرج-منه-ريح-هل-يجب-عليه-ان-يستنجي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_564/56414.mp3","categories":["فروض الوضوء وصفته"]},{"id":15513,"question":"المسح على الرقبة أثناء الوضوء ما الحكم فيه؟ يا سماحة الشيخ.","title":"عدم مشروعية المسح على الرقبة في الوضوء","answer":"الجواب: غير مشروع، إنما يمسح الرأس فقط، من مقدمه إلى مؤخره، أما مسح الرقبة فليس بمشروع. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14051/عدم-مشروعية-المسح-على-الرقبة-في-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_569/56915.mp3","categories":["فروض الوضوء وصفته"]},{"id":15531,"question":"السائلة أختكم في الله، أم محمد، تقول في هذا  قرأت فتوى بالنسبة لمسح الرأس في الوضوء، بأن الرجل مثل المرأة أن يمسح مرة من الأمام إلى الخلف، ثم مرة من الخلف إلى الأمام، ولكن هذا الأمر يصعب علينا -تقول- نحن النساء لما في ذلك من تنكيش للشعر، خاصة التي تشد شعرها، فما الواجب علينا؟ وهل إذا مسحنا ونسينا ذلك أن نرجع مرة أخرى من المسح ثم نغسل الرجلين؟","title":"كيفية مسح الرأس عند الوضوء للمرأة","answer":"الجواب: المسح كافٍ، ولو ما أرجع يديه، المسح كافٍ للرجل والمرأة، لكن إذا رد يديه كان أفضل؛ لفعل النبي ﷺ كان يبدأ بمُقَدَّم رأسه، ثم يذهب بهما إلى قفاه، ثم يردهما إلى المكان الذي بدأ منه، إذا فعل هذا فهو أفضل، وإن مسح من وسط الرأس وعمَّمَه، أو من مُقدَّمه، أو من مؤخَّره كفى؛ لأن الله أمر بمسح الرأس، وهذا يكفي، والرسول ﷺ كان يمسح رأسه، كما أمر الله -جل وعلا-، فإذا فعل الكيفية التي ثبتت عنه ﷺ وهو البداءة بمقدم الرأس إلى قفاه، ثم يرد يديه؛ هذا أفضل، وإلا فليس بلازم، المهم المسح من وسطه، أو من مُقَدَّمه، أو من آخره، إذا عمَّه بالمسح كفى ذلك، والحمد لله، الرجل والمرأة. المقدم: أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/14068/كيفية-مسح-الراس-عند-الوضوء-للمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_569/56924.mp3","categories":["فروض الوضوء وصفته","قضايا المرأة"]},{"id":15546,"question":"يقول هذا السائل: سماحة الشيخ، عندما أبالغ في الاستنشاق أثناء الوضوء، ينتابني ألم شديد في أعصاب الأنف والرأس يستمر عدة ثواني، فهل هذا ما أمرنا به في الشريعة الإسلامية؟","title":"حكم من يتضرر من المبالغة في الاستنشاق","answer":"الجواب: لا، لا تبالغ مبالغة تضرك، الرسول ﷺ قال: بالغ في الاستنشاق إلا أن تكون صائمًا فإذا كان يشق عليك استنشق واطرح الأذى من أنفك، ويكفي، ولا تبالغ مبالغة تضرك، نعم.","link":"https://binbaz.org.sa/fatwas/14087/حكم-من-يتضرر-من-المبالغة-في-الاستنشاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_691/nour_69123.mp3","categories":["فروض الوضوء وصفته"]},{"id":15554,"question":"في سؤالها الثاني تقول: إذا توضأت وضوءًا كاملًا إلا أنني لم أستنشق، فهل يبطل وضوئي وصلاتي؟","title":"حكم ترك الاستنشاق في الوضوء","answer":"الجواب: نعم، الاستنشاق والمضمضة لا بد منهما من غسل الوجه، من جملة الوجه، فلا يصح غسل الوجه إلا بالمضمضة والاستنشاق، ولو مرة واحدة، والأفضل ثلاث.  فالذي لم يستنشق، أو لم يتمضمض وضوؤه غير صحيح، يعيده من أوله، نعم. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/14096/حكم-ترك-الاستنشاق-في-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_691/nour_69129.mp3","categories":["فروض الوضوء وصفته"]},{"id":15630,"question":"هذا سائل للبرنامج الحقيقة أرسل بهذا السؤال يقول -سماحة الشيخ- يذكر بأنه مصاب بمرض سلس البول، كيف يتوضأ للصلاة؟ يقول: لأنني سمعت من بعض أهل العلم، وقرأت بأنه يجب أن أتوضأ لكل وقت صلاة، ولكن أنا -والحمد لله- أصلي في المسجد، وإذا أردت أن أتوضأ عند دخول الوقت فإن تكبيرة الإحرام والركعة الأولى والثانية، قد تفوتني خاصةً في صلاتي المغرب والعشاء، فهل يجوز لي أن أتوضأ قبل دخول الوقت، ولو بخمس دقائق، وما الحال أيضًا بالنسبة لصلاة الجمعة؟","title":"كيفية وضوء من به سلس البول","answer":"الجواب: النبي ﷺ أمر المستحاضة أن تتوضأ لوقت كل صلاة، قال: توضئي لوقت كل صلاة والمستحاضة هي التي يتبعها الدم الدائم، أو الغالب معها، أمرها أن تتوضأ لوقت كل صلاة. وصاحب السلس سلس البول، أو الريح الدائمة أو الغالبة مثل المستحاضة يتوضأ لكل صلاة، يلف على ذكره شيئًا -إذا كان البول- يلف عليه بعض الشيء يحفظه، فإذا دخل الوقت توضأ كما تفعل المستحاضة، سواءً في الجمعة أو في المغرب أو في غير ذلك، ولو فاته بعض الصلاة، فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] لأن الطهارة شرط للصلاة، فإذا أذن المؤذن للمغرب، الأذان الأخير للجمعة؛ يتوضأ ويأتي المسجد، ولو فاته بعض الصلاة، ولو فاته بعض الخطبة؛ لأن هذا شرط الطهارة، شرط للصلاة، والحمد لله.  وإذا تيسر العلاج أنه يعالج هذا السلس عند بعض الأطباء المختصين، أو خروج الريح الدائم؛ كل داء له دواء يعالج، الحمد لله، نعم.","link":"https://binbaz.org.sa/fatwas/14172/كيفية-وضوء-من-به-سلس-البول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_571/57113.mp3","categories":["فروض الوضوء وصفته"]},{"id":15673,"question":"إذا توضأ الإنسان للصلاة، ثم لبس الجورب، ثم صلى العصر، ثم خلع الجورب، وتوضأ لصلاة المغرب، هل فعله هذا صحيح؟","title":"حكم خلع الجورب لتجديد الوضوء","answer":"الجواب: لا حرج عليه، إذا كان لا يرغب ببقائها في رجليه، لا بأس، لا حرج، إن شاء أبقاها ومسح، وإن شاء خلعها، الحمد لله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14217/حكم-خلع-الجورب-لتجديد-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_706/nour_70604.mp3","categories":["فروض الوضوء وصفته"]},{"id":15880,"question":"يسأل سماحتكم عن حكم من لم يتوضأ لبعض الصلوات خوفًا من البرد؟","title":"حكم ترك الوضوء خوفًا من البرد","answer":"الجواب: لا حرج، الحمد لله، إذا كان على وضوء، فالحمد لله يكفيكم الوضوء، أما إذا كان ما هو على وضوء يلزمه الوضوء، ولو كان برد، يسخن الماء، الحمد لله، يسخن الماء، ويتوضأ، نعم.\nالمقدم: جزاكم الله خيرًا، إذا كان بعيدًا عن وسائل التسخين سماحة الشيخ؟\nالشيخ: إذا كان عليه خطر ويضره الماء يتيمم، إذا كان برد ولا عنده شيء مما يسخن به الماء، ويضره الماء يتيمم والحمد لله؛ عذر. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14472/حكم-ترك-الوضوء-خوفا-من-البرد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_744/nour_74417.mp3","categories":["صلاة المريض","فروض الوضوء وصفته","التيمم"]},{"id":16242,"question":"يسأل ويقول: هل الاغتسال غير الغسل من الجنابة يجزئ عن الوضوء؟","title":"هل يجزئ الغسل المباح عن الوضوء؟","answer":"الجواب: لا يجزئ عن الوضوء، لا بد من الوضوء المرتب، أما في الجنابة إذا اغتسل للجنابة، ونواهما؛ فإنه يجزي عند جمع من أهل العلم، والأفضل أن يتوضأ حتى في الجنابة، يتوضأ، ثم يكمل غسله، هذا هو الأفضل. كان النبي ﷺ في غسله من الجنابة يتوضأ، أولًا يستنجي، ثم يتوضأ وضوء الصلاة، ثم يفرغ الماء على رأسه ثلاثًا، ثم على بدنه، هذا هو السنة، وهذا هو الأفضل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14942/هل-يجزى-الغسل-المباح-عن-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_807/nour_80711.mp3","categories":["فروض الوضوء وصفته","الغسل"]},{"id":16345,"question":"تسأل سماحتكم هل الحناء الذي يوضع على الرأس يمنع وصول الماء إلى البشرة؟","title":"حكم المسح على الرأس مع وجود الحناء","answer":"الجواب: لا حرج فيما يوضع على الرأس، تمسح على ما يجعل على الرأس، تمسح عليه والحمد لله، ولو فيه ضماد من الحناء وغيره، كان الصحابيات يمسحن عليه في عهد النبي -عليه الصلاة والسلام- يمسحن على رؤوسهن، وفيها الضماد، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15039/حكم-المسح-على-الراس-مع-وجود-الحناء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_714/nour_71408.mp3","categories":["فروض الوضوء وصفته","قضايا المرأة"]},{"id":16411,"question":"في آخر أسئلة هذا السائل يقول يا سماحة الشيخ حفظكم الله: هل يجوز لمن به عذر كسلس، وغيره أن يتوضأ قبل دخول وقت الصلاة؛ لكي يدرك تكبيرة الإحرام في المسجد، خاصة في صلاتي المغرب والعشاء في المسجد، وصلاة الجمعة، وأيضًا إذا كان المسجد بعيدًا، أي: هل يجوز الوضوء قبل دخول وقت الصلاة، ولو بدقائق معدودة؟","title":"ما حكم الوضوء قبل الوقت للمصاب بالسلس؟","answer":"الجواب: الرسول ﷺ أمر المستحاضة أن تتوضأ لوقت كل صلاة، والعلماء ذكروا أصحاب السلس مثل المستحاضة، لا يتوضأ إلا بعد دخول الوقت لجميع الأوقات، يتوضأ لدخول الوقت، ولو فات بعض الصلاة، نعم. المقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/15113/ما-حكم-الوضوء-قبل-الوقت-للمصاب-بالسلس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_581/58123.mp3","categories":["فروض الوضوء وصفته"]},{"id":16730,"question":"المستمع (ح. ن. ش) يسأل ويقول: ماذا أفعل إذا نسيت التسمية وأنا في الوضوء؟ هل أسمي بعد إكمال الوضوء؟ جزاكم الله خيرًا.","title":"ما حكم من نسي التسمية للوضوء؟","answer":"الجواب: سقطت، لا حرج، إذا نسيتها؛ سقطت -والحمد لله- ولا شيء عليك، إذا نسيت التسمية في الوضوء؛ سقطت -والحمد لله-نعم، وإن ذكرت في الأثناء؛ سم عند غسل اليدين، وعند مسح الرأس، سم الله، كله طيب، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15481/ما-حكم-من-نسي-التسمية-للوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_718/nour_71807.mp3","categories":["فروض الوضوء وصفته"]},{"id":16863,"question":"رسالة من إحدى الأخوات المستمعات تقول: أم سارة من المدينة المنورة، أم سارة لها جمع من الأسئلة في أحدها يقول: عند الوضوء دائمًا أنسى البسملة في بدايته، مع علمي بصحة الحديث في ذلك، فما حكم الوضوء؟ وبالتالي الصلاة فيما مضى؟ جزاكم الله خيرًا.","title":"التسمية عند الوضوء سنة","answer":"الجواب: الوضوء صحيح، والصلاة صحيحة، والحمد لله؛ لقول الله : رَبَّنَا لا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا [البقرة:286] فليس عليك حرج، حتى ولو تركت عمدًا؛ لأن أكثر العلماء على أنها سنة، وذهب بعض أهل العلم إلى أنها واجبة مع الذكر، أما مع النسيان تسقط، والحمد لله، أو مع الجهل، فالصلاة صحيحة والحمد لله، والوضوء صحيح كذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15619/التسمية-عند-الوضوء-سنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_764/nour_76411.mp3","categories":["فروض الوضوء وصفته"]},{"id":16865,"question":"تسأل وتقول: ما حكم استعمال زيت الشعر، وهو يمنع وصول الماء أثناء الوضوء، وأنا أترك خصلة شعر جانب كل أذن، دون وضع الزيت عليها؛ حتى أمسح بالماء، فما الحكم في ذلك؟ جزاكم الله خيرًا.","title":"حكم مسح الرأس وعليه زيت الشعر أثناء الوضوء","answer":"الجواب: يمسح عليه، ولا حرج، كان نساء النبي ﷺ يمسحن على ما يكون في الرؤوس على ما يكون في الرؤوس من اللصوقات، ولا حرج في ذلك، والحمد لله، يمسح عليه الماء مع الأذنين، ويكفي، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15622/حكم-مسح-الراس-وعليه-زيت-الشعر-اثناء-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_764/nour_76412.mp3","categories":["فروض الوضوء وصفته","قضايا المرأة"]},{"id":16867,"question":"تقول: أقوم بوضع الكريم على وجهي لحدوث بعض الجفاف به، فهل يلزم أن أغسل وجهي بالصابون حتى أتأكد من وصول الماء إلى البشرة؟","title":"ما حكم الوضوء وعلى الوجه كريم؟","answer":"الجواب:  الكريم لا يمنع البشرة، لا يمنع الماء الكريم مثل الدهن الخفيف معروف، لا يمنع، ولا يحتاج إلى غسل الصابون، فالماء يتصل بالبشرة، ولا يمنعه الكريم وأشباهه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15624/ما-حكم-الوضوء-وعلى-الوجه-كريم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_764/nour_76413.mp3","categories":["فروض الوضوء وصفته","قضايا المرأة"]},{"id":16936,"question":"فرحان حمد أرسل بهذا السؤال يقول: هل يلزم الوضوء لصلاة التهجد في آخر الليل؟","title":"حكم الوضوء لقيام الليل","answer":"الجواب: إذا كان ليس على وضوء يلزمه الوضوء، إذا كان بعد العشاء قد أحدث، بعد العشاء ريحًا، أو بولًا، أو غائطًا يلزمه، لا يصلي إلا بوضوء، أما إذا كان على طهارة العشاء، وأراد أن يتهجد، ولم يحدث بعد طهارته للعشاء لا بأس، لكن إذا كان نام، أو أحدث لا بد من وضوء للتهجد مثل بقية الصلوات، لا بد يستنجي إن كان بال، ثم يتوضأ وضوء الصلاة، وإن كان ما به إلا ريح يكفيه الوضوء، يغسل، ويتمضمض، ويستنشق، ويغسل وجهه، ويديه، ويمسح رأسه، وأذنيه، ويغسل رجليه، أما إذا كان قد حصل بول، أو غائط لا بد من استنجاء، يستنجي أولًا، ثم يتوضأ وضوء الصلاة.","link":"https://binbaz.org.sa/fatwas/15705/حكم-الوضوء-لقيام-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_586/58609.mp3","categories":["فروض الوضوء وصفته"]},{"id":17072,"question":"تقول هذه السائلة سماحة الشيخ: بأنها تشتكي من ألم في رأسها عند مسحه للوضوء، وأحيانًا تقول: أمسح على شيء فوق رأسي بحيث لا يلامس رأسي الماء، هل علي شيء في ذلك والحال ما ذكر؟","title":"حكم ترك المسح على الرأس للعذر","answer":"الجواب: هذا يختلف؛ إن كان عليها ... ضرر بين فلا تمسح وتتيمم، فإن كان هذا شيء ضرر خفيف، لا، يلزمها المسح على نفس الشعر، لا تحط شيئًا، تمسح على نفس الشعر. لكن لها أن تتخذ خمارًا، يعني: تلفهن تتحنك به، وتضبطه، تمسح يومًا وليلة إذا لبسته على طهارة، ثم إذا تمت اليوم والليلة؛ تخلعه، وتتطهر، ثم تلبسه.. وهكذا، حتى يدفع عنها بعض الضرر، يعني: خمار مربوط، تطويه على رأسها، وتحت حنكها، مضبوط، تلبسه على طهارة، تمسح عليه يومًا وليلة مثل: الخفين، فإذا تمت اليوم والليلة؛ نقضته، ثم تطهرت، ثم لبسته لبسًا محكمًا لأجل مضرة الرأس. نعم. المقدم: إذًا هذه ضرورة يا سماحة الشيخ؟ الجواب: نعم، إذا تيسر الخمار هذا ولبسه على طهارة، وتمسح على الخمار يوم وليلة، ثم تنقضه، وتتطهر، ثم تعيد لبسه، وهكذا كالخفين، لا بأس، وإن شق عليها هذا، ولم يتيسر تتيمم، إذا كان يضره الماء، إذا توضأت، وغسلت رجليها تنشفت، تضرب التراب بيديها بالنية عن الرأس. المقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/15877/حكم-ترك-المسح-على-الراس-للعذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_588/58812.mp3","categories":["فروض الوضوء وصفته","قضايا المرأة"]},{"id":17133,"question":"سماحة الشيخ! هذه رسالة وصلت من مستمع للبرنامج يقول: سماحة الشيخ! السلام عليكم ورحمة الله وبركاته، أنا أعلم بأن الكلام أثناء الوضوء مكروه، ولكن هل يكون مكروهًا أيضًا إذا رددنا وراء الأذان أثناء الوضوء؟","title":"حكم الكلام أثناء الوضوء","answer":"الجواب: لا حرج أن يتكلم بالأمر الشرعي، وهو يتوضأ إذا كان في محلٍ خارج الحمام، خارج محل قضاء الحاجة، لا بأس أن يردد مع الأذان وهو يتوضأ، ويجيب المؤذن إذا كان خارج الحمام. نعم.","link":"https://binbaz.org.sa/fatwas/15954/حكم-الكلام-اثناء-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_589/58924.mp3","categories":["فروض الوضوء وصفته"]},{"id":17170,"question":"من إحدى الأخوات من الخبر رمزت إلى اسمها بالحرف (م) تسأل: هل صحيح أن الكلام أثناء الوضوء يبطل ذلك؟","title":"حكم الكلام أثناء الوضوء","answer":"الجواب: لا، غلط، الكلام وقت الوضوء لا يبطل الوضوء، الحمد لله إذا توضأ وهو يتكلم مع أحد الوضوء شرعي، إذا تم الوضوء شرعي، إذا أتى بالوضوء الشرعي تمضمض، واستنشق، وغسل وجهه، وغسل يديه مع المرفقين، ومسح رأسه مع الأذنين، وغسل رجليه مع الكعبين، الوضوء صحيح، ولو أنه يتكلم، لا حرج في الكلام. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15989/حكم-الكلام-اثناء-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_722/nour_72218.mp3","categories":["فروض الوضوء وصفته"]},{"id":17210,"question":"بعد هذا ننتقل إلى رسالة وصلت إلى البرنامج من المستمع هاشم عبدالمجيد محمد العطاء، يسأل فيقول: لقد استفدنا من هذا البرنامج الشيء الكثير والكثير -ولله الحمد- وأسألكم في هذه الحلقة لو تكرمتم عن الوضوء داخل دورات المياه هل هو جائز؟ وكيف توجهوننا بالنسبة للأذكار، ثم إني أذكر سماحتكم بنظافة هذه المحلات -ولله الحمد- فهي تختلف عن سابقاتها فيما عهد قديمًا، جزاكم الله خيرًا.","title":"حكم الوضوء والتسمية له في دورة المياه","answer":"الجواب:  إذا كان في الحمام هذا مقعد لقضاء الحاجة، فالأولى والأحوط الخروج وقت الوضوء، الوضوء الشرعي إلى خارج إذا تيسر ذلك، فإن لم يتيسر؛ توضأ من داخل، لكن يسمي عند بدء الوضوء، عند غسل يديه، أو عند المضمضة يقول: باسم الله، ويبدأ الوضوء، ولا كراهة في ذلك؛ لأن التسمية مهمة، قد أوجبها جماعة من العلماء، في أول الوضوء لما يروى عنه ﷺ أنه قال: لا وضوء لمن لم يذكر اسم الله عليه.  فالإنسان يسمي ولو كان في داخل الحمام؛ لأن التسمية مهمة، ومتأكدة، أو واجبة عند بعض أهل العلم، فلا يدعها لقول بعض أهل العلم بكراهة الذكر في الحمامات، فإنه يكره، لكن عند دعاء الحاجة إليه، أذكار الوضوء تزول الكراهة؛ لأن التسمية متعينة، ومتأكدة إما وجوبًا، وإما استحبابًا متأكدًا. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16036/حكم-الوضوء-والتسمية-له-في-دورة-المياه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_723/nour_72306.mp3","categories":["فروض الوضوء وصفته"]},{"id":17331,"question":"بعد هذا رسالة بعث بها مستمع رمز إلى اسمه بالحروف (م. ك. ر) الرسالة مؤثرة كثيرًا سماحة الشيخ، صدرها بـ (بسم الله الرحمن الرحيم).سماحة الشيخ والدنا عبدالعزيز بن عبدالله بن باز حفظه الله، السلام عليكم ورحمة الله وبركاته، أشهد الله، ثم أشهدكم بأني أحبكم في الله، سماحة الشيخ! أصبت ببلاء، وأصبحت لا أتحكم في نفسي، ولاسيما الطهارة إلا بصعوبة، وقد ينتقض وضوئي في مرات كثيرة في الصلاة، أو أثناء الذهاب إلى المسجد، وقد لا ينتقض في بعض الأوقات، وهي قليلة، أصبحت لا أعلم متى ينتقض وضوئي، ومتى لا ينتقض، هل أنا بهذه الحالة من أصحاب الأعذار، وإذا كنت كذلك فهل لي أن أتوضأ قبل دخول الوقت لكي أدرك الجماعة؛ لأنني قرأت فتوى لابن تيمية يقول: يتوضأ صاحب العذر لكل صلاة، أو لوقت كل صلاة، فهل لي أن أتوضأ قبل دخول الوقت لأدرك صلاة الجماعة، مع العلم بأنني إذا توضأت بعد دخول الوقت فإني قد لا أدرك صلاة الجماعة، هل لي أن أجمع بين الصلاتين بوضوء واحد مع إمام يجمع في مطر، أو في سفر، هل لي أن أمسح على الجوارب، وأنا بهذه الحالة، هل لي أن أصلي إمامًا إذا لم يحضر إمام المسجد، وكنت أقرأ الموجودين، وأعلمهم بالسنة، وهل إذا صليت فيهم إمامًا، فهل أكون آثمًا؟ وجهوني حول هذه الأمور، جزاكم الله خيرًا.","title":"كيفية وضوء صاحب الحدث الدائم","answer":"الجواب: أسأل الله أن يمنحنا، وإياك الشفاء، والعافية من كل سوء، وأما ما يتعلق بالمحبة في الله، فالمحبة في الله من أفضل القربات، ونقول: أحبك الله الذي أحببتنا له، والرسول ﷺ يقول: إذا أحب أحدكم أخاه فليعلمه، وإذا أعلمه أخوه فليقل: أحبك الله الذي أحببتنا له وقد صح عن رسول الله ﷺ أنه قال: سبعة يظلهم الله في ظله، يوم لا ظل إلا ظله ذكر منهم: رجلان تحابا في الله، اجتمعا عليه، وتفرقا عليه وصح عنه أيضًا -عليه الصلاة والسلام- أنه قال: يقول الله يوم القيامة: أين المتحابون بجلالي، اليوم أظلهم في ظلي، يوم لا ظل إلا ظلي. أما ما ذكرت من جهة استمرار الحدث فإنك تتوضأ لوقت كل صلاة، هكذا أمر النبي ﷺ أمر النبي ﷺ المستحاضة، وهي التي حدثها دائم، قال: توضئي لوقت كل صلاة رواه البخاري ، فأنت تتوضأ لوقت كل صلاة، ولو خرج منك شيء في الطريق، أو في المسجد، أو في الصلاة ما يضرك، فالحمد لله، متى توضأت بعد دخول الوقت فإن الحدث الذي يخرج منك في الطريق، أو في المسجد، أو في الصلاة، أو بعد الصلاة لا ينقض وضوؤك، بل لك أن تصلي في الوقت ما دمت على هذه الحال، حتى يأتي الوقت الآخر، متى تصلي تقرأ من المصحف، وتطوف في مكة، إذا كنت في مكة تطوف.  إذا توضأت العصر، تطوف بوضوء العصر بعد العصر، وإذا توضأت الظهر تطوف بوضوء الظهر، وتصلي به، وإذا كان جمع كفى وضوء واحد في المطر، أو في السفر، أو في المرض، يكفي وضوء واحد والحمد لله، تتوضأ، وتصلي الصلاتين بوضوء واحد، وأبشر بالخير، ونسأل الله لك العافية، والتوفيق. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16162/كيفية-وضوء-صاحب-الحدث-الداىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_724/nour_72408.mp3","categories":["فروض الوضوء وصفته"]},{"id":17443,"question":"رسالة مؤثرة للغاية سماحة الشيخ، باعثتها إحدى الأخوات المستمعات تقول: أختكم في الله (ح. ع. ع) تقول عن نفسها: السلام عليكم ورحمة الله وبركاته، وبعد. أنا فتاة أصبت بحادث سيارة منذ أربع سنوات، تسبب لي هذا الحادث في شلل كامل، ما عدا الذراعين فهما سليمتان، والحمد لله، بعد إصابتي بهذا الحادث كنت أصلي بدون تيمم، أو وضوء، وسمعت من بعض الأخوات أنه يجب علي أن أتيمم، وأستعين في ذلك بخادمة، أو أي أحد يقوم بالضرب على التراب مرة واحدة، ثم أمسح على وجهي، وكفي، مع العلم أنه بعد التيمم لا أدري هل ظهر أثر التراب على مناطق التيمم، أو لا؟ ثم إنه عندما أشرع في الصلاة في بعض الأوقات لا أضبط نفسي بحكم الشلل، وقد ينتقض وضوئي، أرجو من سماحتكم توجيهي -جزاكم الله خيرًا- كما أرجو من سماحتكم الدعوات الطيبة؛ لعل الله أن ينفع بها.","title":"كيفية التيمم والصلاة لمن أصيب بالشلل","answer":"الجواب: وعليكم السلام ورحمة الله وبركاته، نسأل الله لك الشفاء والعافية، نسأل الله أن يمنحك الشفاء والعافية ويجمع لك بين الأجر والعافية، متى فعلت التيمم؛ كفى، ولو ما ظهرت آثار التراب عليه، متى ضربت التراب بيديك، أو من ينوب عنك، ضرب التراب بأمرك، ونيتك، ومسح على وجهك، وعلى كفيك؛ كفى ذلك، والحمد لله، وإن لم تعلمي ظهور آثار التراب، المهم أن يضرب التراب النائب عنك، أو أنت بنفسك، ثم تمسحين أنت، أو النائب وجهك والكفين بنية الطهارة، والحمد لله. وأما ما يتعلق بخروج الحدث في الصلاة فهذا فيه تفصيل: إن كان الحدث دائمًا معك في كل وقت؛ فلا يضرك خروجه في الوقت ما بعد الطهارة، أما إن كان لا، ليس بدائم، فإنه متى خرج تبطل الصلاة، وعليك أن تعيدي التيمم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16305/كيفية-التيمم-والصلاة-لمن-اصيب-بالشلل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_836/nour_83608.mp3","categories":["صلاة المريض","فروض الوضوء وصفته","التيمم"]},{"id":17563,"question":"هل طبقة الدهون خاصة الفازلين تمنع وصول الماء إلى البشرة، وماذا عليَّ؟ يقول: إذا كنت قد توضأت وصليت في هذا عدة صلوات وما زالت موجودة على يدي دون علمي بأن الدهن يمنع وصول الماء إلى البشرة، كيف أتخلص من ذلك مأجورين؟","title":"ما حكم الوضوء وعلى اليدين دهن؟","answer":"الجواب: المروخات التي لا جرم لها لا تمنع من الماء بالزيت أو بالدهن أو بغير هذا من أنواع المروخات التي لا جرم لها فإنها لا تمنع، أما إذا كان شيء له جرم، له يعني: أثر يمنع الماء تزيله قبل هذا، في يدك أو في وجهك تزيله أو في رجلك، أما دهن مسحت يدك أو وجهك أو رجلك بشيء لا جرم له لا يبقى له جرم إنما هو جرم يبقى له أثر فقط من الملوسة ونحو ذلك فهذا لا يمنع، لا يمنع الماء ولا حرج في ذلك، الذي يمنع هو اللي يكون له جرم يحول بين الماء وبين الجلدة. نعم.\nالمقدم: أحسن الله إليكم وأثابكم الله.","link":"https://binbaz.org.sa/fatwas/16480/ما-حكم-الوضوء-وعلى-اليدين-دهن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_775/nour_77520.mp3","categories":["فروض الوضوء وصفته"]},{"id":17703,"question":"هذا سائل للبرنامج يقول: وجدت أثرًا لعلك في رجلي بعد العصر فاجتهد في إزالته وأعدت صلاة العصر ثم ذهبت إلى الحرم ووجدت بقايا صغيرة جدًا من العلك فهل علي أن أعيد العصر والمغرب أم ماذا علي؟","title":"الواجب على من وجد علكًا في رجله بعد الصلاة","answer":"الجواب: إذا كانت يسيرة لا تمنع الماء لا حرج، إذا كانت يسيرة جدًا لا تمنع الماء فلا حرج. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16656/الواجب-على-من-وجد-علكا-في-رجله-بعد-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_776/nour_77614.mp3","categories":["فروض الوضوء وصفته"]},{"id":17704,"question":"هذا سائل للبرنامج يقول: وجدت أثرًا لعلك في رجلي بعد العصر فاجتهد في إزالته وأعدت صلاة العصر ثم ذهبت إلى الحرم ووجدت بقايا صغيرة جدًا من العلك فهل علي أن أعيد العصر والمغرب أم ماذا علي؟","title":"الواجب على من وجد علكًا في رجله بعد الصلاة","answer":"الجواب: إذا كانت يسيرة لا تمنع الماء لا حرج، إذا كانت يسيرة جدًا لا تمنع الماء فلا حرج. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16656/الواجب-على-من-وجد-علكا-في-رجله-بعد-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_776/nour_77614.mp3","categories":["فروض الوضوء وصفته"]},{"id":17722,"question":"يقول هذا السائل أخوكم (ع. ط. ح) ما حكم الوضوء أثناء الاستحمام وتعميم كافة الجسد بالماء، وهل يختلف الحكم إذا كان في جنابة أو غير ذلك.","title":"حكم الوضوء أثناء الاستحمام","answer":"الجواب: الجنب والحائض السنة أن يبدأ بالوضوء، الوضوء الشرعي، ثم يفيض الماء على جسده، وهكذا في غسل الجمعة يتوضأ قبل، وإن لم يتوضأ قبل يتوضأ بعد.\nأما إذا كان للتبرد- فالحمد لله- يصب الماء على جسده والحمد لله، لكن إذا كان لجمعة أو عن الجنابة فيستحب له البداءة بالوضوء ثم يغتسل الغسل الشرعي.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16675/حكم-الوضوء-اثناء-الاستحمام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_595/59528.mp3","categories":["فروض الوضوء وصفته"]},{"id":17749,"question":"تقول السائلة زهراء علي: سماحة الشيخ! إذا توضأ الفرد المسلم فانتقل إلى غسل عضو ونسي أن يغسل العضو الذي قبله، مثلًا أن يغسل يديه إلى المرفق ونسي غسل الوجه، فما الحكم هل يعيد الوضوء؟ أم أنه يعود للعضو الذي لم يغسله؟","title":"حكم نسيان غسل عضو من أعضاء الوضوء","answer":"الجواب: يعود للعضو الذي لم يغسله ثم يغسل ما بعده، يعيد الوضوء كله من أوله إذا ترك الوجه يبدأ يعود للوجه، ثم يعود يغسل اليدين، ثم يمسح رأسه، ثم يغسل رجليه؛ لأنه لابد من الترتيب، فإذا نسي غسل يديه قبل وجهه، يعود يغسل وجهه ثم يغسل يديه، نعم.","link":"https://binbaz.org.sa/fatwas/16717/حكم-نسيان-غسل-عضو-من-اعضاء-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_596/59611.mp3","categories":["فروض الوضوء وصفته"]},{"id":17751,"question":"السائل أبو أحمد يقول يا سماحة الشيخ: هل يكفي مسح بعض الرأس عند الوضوء للصلاة؟","title":"حكم مسح بعض الرأس","answer":"الجواب: الواجب مسحه كله، كان النبي يمسحه كله عليه الصلاة والسلام، فعلينا أن نتأسى به عليه الصلاة والسلام، فالواجب مسح الرأس كله مع الأذنين، يمسح داخلهما وظاهرهما. نعم.","link":"https://binbaz.org.sa/fatwas/16721/حكم-مسح-بعض-الراس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_596/59613.mp3","categories":["فروض الوضوء وصفته"]},{"id":17862,"question":"تقول السائلة من مكة المكرمة سماحة الشيخ: إذا توضأ الإنسان بماء، ثم توضأ بذلك الماء آخر لضرورة أو لغير ضرورة، فهل هذا جائز؟","title":"حكم الوضوء بالماء المستعمل","answer":"الجواب: إذا كان الماء مجموعًا وتوضأ به الإنسان ثم بقي حصل منه ما يكفي في وضوء الثاني، فالصواب أنه لا حرج، لا ينجس بذلك، ولا تزول طهوريته، الصحيح أنه يبقى طهورًا، فلو توضأ به آخر كان في محل مجموع في إناء مجموع وتوضأ به آخر، فالصواب أنه يحصل به الطهارة.\nوقال بعض أهل العلم: إنه يكون طاهرًا لا طهورًا، لا تحصل به الطهارة، وليس عليه دليل، والصواب أنه طهور، فلو أن إنسانًا تطهر من حوض صغير، أو من إناء كبير ثم صب ماءه الذي تطهر في إناء آخر، فتوضأ به آخر فلا بأس، إذا المقصود أن الماء الذي تطهر به لو اجتمع في إناء واغتسل به إنسان أو توضأ به إنسان فلا حرج، إذا لم يكن له نجاسة إنما هو غسل وجهه وذراعيه ومسح رأسه وأذنيه، هذا لا ينجسه، ولا يسلبه الطهورية على الراجح.\nلكن تركه كونه يتوضأ بماء سليم -خروجًا من الخلاف- يكون أحسن، من باب: دع ما يريبك إلى ما لا يريبك. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16871/حكم-الوضوء-بالماء-المستعمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_598/59807.mp3","categories":["فروض الوضوء وصفته"]},{"id":18272,"question":"رسالة وصلت إلى البرنامج من القصيم وباعثها أحد الإخوة يقول: أخوكم (ع. م) يسأل أخونا ويقول: من شروط الوضوء النية -والنية محلها القلب- لكن إذا ذهب شخص لدورة المياه الحمام -أعزكم الله- والسامعين لقضاء الحاجة، ولم ينو الوضوء، وحينما فرغ أراد الوضوء بأن غسل وجهه ويديه إلى آخر الأعضاء أي: أكمل الوضوء، فهل وضوءه صحيح؟","title":"وقت بدء النية للوضوء","answer":"الجواب:\n\nنعم، نية الوضوء عند البدء في المضمضة والاستنشاق؛ لأن ذاك يسمى قضاء حاجة، يسمى استنجاء، فإذا استنجى من البول أو الغائط ما عنده نية وضوء ثم بعد ذلك أراد أن يتوضأ، فالنية تكفي بعد ذلك، فإذا بدأ يتمضمض ويستنشق بنية الوضوء كفى، والأفضل أن ينوي عند غسل الكفين، عند غسل الكفين يسمي الله وينوي الوضوء، ثم يشرع في المضمضة والاستنشاق وغسل وجهه ثم يديه ثم مسح رأسه إلى آخره، فالنية عند بدئه غسل اليدين قبل المضمضة والاستنشاق.\n\nأما ذاك الذي يسمى الاستنجاء فليس محل النية، هذاك إزالة أذى، إزالة خبث، يزيل الأذى بالماء أو بالاستجمار ولا يحتاج إلى نية، إنما النية عند بدئه غسل أطرافه الأربعة، الوجه واليدين والرأس والرجلين، هذا محل النية ويسمى الوضوء، ويسمى التطهر والطهور. نعم.\n\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17321/وقت-بدء-النية-للوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_910/nour_91008.mp3","categories":["فروض الوضوء وصفته"]},{"id":18300,"question":"هل التسمية عند الوضوء سنة أم فريضة؟ وإن كانت فريضة ونسي إنسان أن يسمي فما الحكم؟","title":"حكم التسمية للوضوء","answer":"الجواب: الجمهور من أهل العلم على أنها سنة، هذا قول أكثر أهل العلم، التسمية سنة، وقال بعض أهل العلم: إنها واجبة، لما ورد عنه ﷺ أنه قال: لا وضوء لمن لم يذكر اسم الله عليه لكن هذا الحديث أعله العلماء، قالوا: إنه لا يثبت، كما قاله أحمد رحمه الله وجماعة؛ ولهذا قالوا يستحب فقط؛ لأن مجموع الأحاديث قد يشد بعضها بعضًا، فيؤخذ منها السنية، وقال بعضهم: يؤخذ منها الوجوب؛ لأنها متعددة فيشد بعضها بعضًا كما قال الحافظ ابن كثير رحمه الله. فالقول بالوجوب فيه نظر، أما السنية فلا شك فيها، يستحب عند البدء بالوضوء أن يسمي الله، يقول: باسم الله، عند بدء الوضوء فإن نسيها فلا شيء عليه. وهكذا عند الغسل يسمي فإن نسي فلا شيء عليه: رَبَّنَا لا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا[البقرة:286]. المقدم: جزاكم الله خيرًا ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/17351/حكم-التسمية-للوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_912/nour_91215.mp3","categories":["فروض الوضوء وصفته"]},{"id":18336,"question":"سماحة الشيخ: يقول السائل من الرياض: هل عدم التسمية عند الوضوء تبطل الوضوء؟","title":"حكم التسمية في بداية الوضوء","answer":"الجواب: جمع من أهل العلم يرونها واجبة التسمية مع الذكر، إلا إن تركها ناسيًا أو جاهلًا ما يضر، أما التعمد لا ينبغي تعمد تركها، لكن إذا ترك التسمية ناسيًا أو جاهلًا لا حرج عليه.","link":"https://binbaz.org.sa/fatwas/17390/حكم-التسمية-في-بداية-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_913/nour_91319.mp3","categories":["فروض الوضوء وصفته"]},{"id":18464,"question":"يقول في سؤاله الثاني: هل يصح الوضوء في الحمام، إذا لم توجد مغسلة أخرى خارج الحمام؟","title":"هل يصح الوضوء في الحمام؟","answer":"الجواب: يتوضأ في الحمام ولا بأس، والحمد لله، ويسمي عند بدء الوضوء، الحمد لله؛ لأنه مضطر إلى هذا، تزول الكراهة عند الحاجة، زالت الكراهة يسمي الله ويتوضأ والحمد لله. المقدم: والتسمية يا سماحة الشيخ تكون جهرية؟ الشيخ: عند أول الوضوء. المقدم: جهرًا أم سرًا؟ الشيخ: كله واحد، يتلفظ بها.نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17561/هل-يصح-الوضوء-في-الحمام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_785/nour_78514.mp3","categories":["فروض الوضوء وصفته"]},{"id":18683,"question":"هل حمرة الشفاه أو الكحل في العينين يمنع الوضوء؟","title":"هل حمرة الشفاه أو كحل العينين يمنع الوضوء؟","answer":"الجواب: لا، لا أثر له في ذلك، الكحل وحمرة الشفتين لا أثر لهما؛ لأنها ليس لها جرم يمنع الماء ومثل جنس الدهن وأشباهه، نعم.","link":"https://binbaz.org.sa/fatwas/17807/هل-حمرة-الشفاه-او-كحل-العينين-يمنع-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_873/nour_87305.mp3","categories":["فروض الوضوء وصفته","قضايا المرأة"]},{"id":18716,"question":"تسأل أختنا عن كيفية مسح المرأة لشعرها عند الوضوء، ما مقدار الجزء الذي تمسحه، وهل يكفي المسح؟ أم لا بد من طريقة معينة؟ جزاكم الله خيرًا.","title":"كيفية مسح المرأة لشعرها عند الوضوء","answer":"الجواب: مثل الرجل تمسح من مقدم رأسها إلى قفاه إلى منابت الشعر أسفل. أما الذوائب ما لها لزوم، إنما تمسح من مقدم الشعر مقدم الرأس، إلى منتهى منابت الشعر من أسفل الرأس. وأما ذوائبها ما له لزوم، فلا يشترط مسحها في الوضوء ولكن تغسل في الجنابة والحيض، نعم. المقدم: إذًا الضفائر كما سمتها أختنا لا يجب على المرأة مسحها. الشيخ: في الوضوء، ولكن تغسل في غسل الحيض والجنابة. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17823/كيفية-مسح-المراة-لشعرها-عند-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_735/nour_73518.mp3","categories":["فروض الوضوء وصفته","قضايا المرأة"]},{"id":18769,"question":"هذه السائلة تقول: سماحة الشيخ، هناك موضوع أود أن أستفسر من سماحتكم عنه، وهو أننا كنا نتعلم في المدرسة بأن المسح على الرأس بالنسبة للمرأة في الوضوء سنة، وأنه يكون من الأمام فقط، وأن تاركه لا يأثم، وعلى ذلك فقد كنت نادرًا ما أمسح رأسي في الوضوء، وإذا مسحت أمسح من الأمام فقط، وطبعًا هذا نتيجة للجهل.ولكن منذ مدة بدأت أقرأ القرآن، والكتب الشرعية، وعلمت ما كنت عليه من خطأ، فماذا علي أن أفعل؟ وهل يجب علي الإعادة في صلواتي الفائتة؟ مأجورين.","title":"حكم من تركت مسح الرأس حال الوضوء جهلًا","answer":"الجواب: الواجب عليك التوبة إلى الله من ذلك، والاستقامة على مسح جميع الرأس من مقدمه إلى أسفله، إلى آخره مما يلي الرقبة، هذا الواجب عليك، وعلى الرجل مسح جميع الرأس، أما أطراف العمائم ما يجب، لكن مسح جميع الرأس من منابته من أعلى إلى منابته من أسفل، هذا هو الواجب عليك، وعلى غيرك، وعلى الرجال أيضًا، والماضي ليس عليك إعادة عليك التوبة إلى الله من ذلك، وليس عليك إعادة؛ لأن الرسول ﷺ أمر الذي أساء في صلاته أن يعيد الوقت الحاضر، ولم يأمره أن يعيد ما مضى لجهله، فأنت جهلت الأمر الشرعي فعليك التوبة إلى الله من ذلك، وعليك الاستقامة في المستقبل، نعم. المقدم: أحسن الله إليكم، سماحة الشيخ عبد العزيز، تهاون الناس في السؤال عن الأمور الشرعية، هل لكم توجيه في ذلك يا شيخ؟ الشيخ: الواجب على كل مسلم ومسلمة التفقه في الدين، والسؤال عما أشكل عليه، وعدم السكوت على الجهل، يجب على الرجل أن يتعلم، والمرأة أن تتعلم أمور دينها، كل واحد منهم الرجل والمرأة على كل واحد أن يتعلم أمور دينه، الله يقول: فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لا تَعْلَمُونَ[النحل:43].\nوالله أوجب على الناس أن يعبدوه، ولا طريق للعبادة إلا بالتعلم، يعرف ما أوجب الله عليه حتى يؤديه، ويعرف ما حرم الله عليه حتى يجتنبه، وقد أجمع المسلمون على أنه لا بد من التعلم لما لا يسع العبد جهله، يتعلم ما أوجب الله عليه، وما حرم الله عليه، والسكوت، والإعراض، والغفلة؛ هذا أمر منكر لا يجوز، الله وصف الكفار بالإعراض، قال: وَالَّذِينَ كَفَرُوا عَمَّا أُنْذِرُوا مُعْرِضُونَ[الأحقاف:3]، قال سبحانه: وَمَنْ أَظْلَمُ مِمَّنْ ذُكِّرَ بِآيَاتِ رَبِّهِ فَأَعْرَضَ عَنْهَا[الكهف:57]. فالواجب على كل مسلم ومسلمة التفقه في الدين والتبصر، كما قال النبي ﷺ: من يرد الله به خيرًا يفقهه في الدين. وعلى المسلم أن يسأل ولو من طريق الكتابة، من طريق الهاتف يسأل أهل العلم عما أشكل عليه، يستمع ما يذاع في إذاعة القرآن من العلم، إذاعة القرآن فيها علم عظيم في نور على الدرب أسئلة كثيرة من كل مكان لأهل العلم يجيبون عنها فيها، فوائد كثيرة، في إذاعة القرآن سماع القرآن، وسماع الندوات، والمحاضرات العلمية، فيها خير كثير. فأنا أوصي الجميع الرجال والنساء بالعناية بإذاعة القرآن، والاستماع لها، والاستفادة مما فيها من العلم، نسأل الله للجميع الهداية، نعم. المقدم: اللهم آمين، شكر الله لكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17899/حكم-من-تركت-مسح-الراس-حال-الوضوء-جهلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_791/nour_79105.mp3","categories":["فروض الوضوء وصفته"]},{"id":18805,"question":"أخونا يسأل سؤالًا آخر ويقول: هل يجوز الوضوء بالماء الدافي، وخاصة في أيام البرد القارس؟","title":"حكم الوضوء بالماء الدافئ","answer":"الجواب: نعم هو الأفضل، الأفضل بالماء الدافئ؛ لأنه أبلغ في الإسباغ، لكن إذا احتاج الماء البارد، وصبر عليه له فضل عظيم؛ لما جاء في الحديث عنه ﷺ أنه قال: ألا أدلكم على ما يرفع الله به الدرجات، ويمحو به الخطايا؟ قالوا: بلى يا رسول الله، قال: إسباغ الوضوء على المكاره -وفي لفظ قال: في السبرات يعني: في البرد- وكثرة الخطى إلى المساجد، وانتظار الصلاة بعد الصلاة، فذلكم الرباط فذلكم الرباط خرجه مسلم في صحيحه. فإسباغ الوضوء في المكاره في حال شدة البرد عند الحاجة إليه؛ هذا يدل على قوة الإيمان، ويكون الأجر أعظم، لكن إذا تيسر له الماء الدافئ يكون أفضل؛ لأن هذا الماء الدافئ يكون أعون له على الإسباغ، وإكمال الوضوء، كما شرع الله  وأبلغ أيضًا في إزالة الأوساخ والنظافة، نعم. المقدم: هذا الدافئ؟ الشيخ: هذا الدافئ، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17959/حكم-الوضوء-بالماء-الدافى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_877/nour_87707.mp3","categories":["فروض الوضوء وصفته"]},{"id":18925,"question":"رجل دخل دورة المياه لقضاء الحاجة، ثم بعد أن قضى الحاجة توضأ وضوء للصلاة دون أن يكون قد نوى أن يصلي، وإنما جاءت النية بعد قضاء الحاجة، وهو داخل الحمام، فهل الوضوء صحيح أم أن عليه أن يكون قد نوى من قبل؟","title":"انعقاد نية الصلاة عند بدء الوضوء الشرعي","answer":"الجواب: إذا نوى عند بدء الوضوء الشرعي، فالوضوء صحيح، إذا استنجى ثم تمضمض واستنشق وغسل وجهه بنية الوضوء الشرعي، فالحمد لله، يصلي ما تيسر من ذلك، ويمس المصحف لا بأس؛ لأن هذا وضوء شرعي، إذا كان نوى الوضوء، أما إذا كان غسل أعضاءه ما عنده نية، ما في وضوء، لا بد من النية.","link":"https://binbaz.org.sa/fatwas/18073/انعقاد-نية-الصلاة-عند-بدء-الوضوء-الشرعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_882/nour_88210.mp3","categories":["فروض الوضوء وصفته"]},{"id":18960,"question":"تقول هذه السائلة: إذا أردت وضع الحناء على رأسي لمدة يوم أو يومين، فهل يجوز أن أمسح على الغطاء، أم لا بد من مسح الرأس نفسه؟","title":"حكم المسح على غطاء الرأس للمرأة","answer":"الجواب: تمسح على الرأس على الأضمدة، على الضماد الذي على الرأس، تقول عائشة: \"كنا نمسح على الضماد في عهد النبي ﷺ\"، نعم. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/18106/حكم-المسح-على-غطاء-الراس-للمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_882/nour_88227.mp3","categories":["فروض الوضوء وصفته"]},{"id":19046,"question":"مع مطلع هذه الحلقة نعود إلى رسالة الأخ المستمع سعيد بن عبد الحميد أحمد، أخونا عرضنا بعض أسئلة له في حلقة مضت، وفي هذه الحلقة له سؤال واحد يقول فيه: ما حكم التسمية قبل الوضوء، وإذا لم يسم الإنسان فما حكم وضوءه؟ جزاكم الله خيرًا.","title":"حكم التسمية عند الوضوء","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فالتسمية في أول الوضوء سنة عند الجمهور عند جمهور العلماء، وذهب بعض أهل العلم إلى وجوبها مع الذكر، فينبغي للمؤمن أن لا يدعها، فإن نسي أو جهل فلا شيء عليه ووضوءه صحيح، أما إن تعمد تركها وهو يعلم الحكم الشرعي؛ فينبغي له أن يعيد الوضوء احتياطًا وخروجًا من الخلاف؛ لأنه جاء عنه ﷺ أنه قال: لا وضوء لمن لم يذكر اسم الله عليه . وهذا الحديث جاء من طرق، وقد حكم جماعة من العلماء أنه غير ثابت، وأنه ضعيف، وقال الحافظ ابن كثير رحمه الله: إنه حسن، بسبب كثرة طرقه فهو من باب الحسن لغيره، فينبغي للمؤمن أن يجتهد في التسمية عند أول الوضوء، وهكذا المؤمنة فإن نسي ذلك أو جهل ذلك فلا حرج. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/18230/حكم-التسمية-عند-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_737/nour_73701.mp3","categories":["فروض الوضوء وصفته"]},{"id":19061,"question":"تقول: لو توضأت على التحجيبة الموضوعة على الرأس؛ لأنه لا يوجد وقت في العمل برفع التحجيبة من على الرأس للوضوء، ووضعها مرة أخرى، فهل الوضوء صحيح أم لا؟","title":"هل يجوز مسح المرأة على التحجيبة في الوضوء؟","answer":"الجواب: إذا كان المراد بالتحجيبة الخمار الشيلة التي على الرأس هذه تنزع وقت مسح الرأس، أما إذا كان المقصود بالتحجيبة آثار المشاط الذي في الرأس، أو الحناء الذي في الرأس؛ هذا يمسح عليه، والحمد لله، أما التحجيبة التي أردت إذا كانت غير ذلك فلا بد من بيانها.\nأما لو كان الخمار محنكًا على الرأس، ويشق نزعه، وقد لبس على الطهارة؛ فإنه يمسح عليه يوم وليلة كالخفين.\nوهكذا عمامة الرجل إذا جعلها على رأسه، وحنكها تحت حنكه؛ لفها على رأسه فإن مثلها يشق نزعه، فإذا مسح عليها يومًا وليلة فلا بأس، إذا كان لبسها على طهارة.\nفالعمامة - والخمار للمرأة - كلاهما إذا لبسا على طهارة، وقد حنكها أو حنكتها المرأة حيث يكون ربطتها على رأسها وربطها على رأسه فإن هذا عذر في مسحه عليها، إذا كان لبسها على طهارة يوم وليلة في الحضر، وثلاثة أيام بلياليها في السفر؛ كالخفين.\nأما لبس الخمار عاديًا والغترة عاديًا فلا يمسح عليهما، عند المسح يزيل الغترة ويمسح، تزيل المرأة الخمار العادي، وتمسح، أو كان لبسها على غير طهارة ينزعها، ويمسح على الرأس، لا بد من شرط ذلك المسح أن يكون لبسها على طهارة، أن تكون يشق نزعها؛ لأنها محنكة - مطوية على الرأس، ملفوفة على الرأس، مدارة على الرأس -. نعم.\nالمقدم: جزاكم الله خيرًا، هل يأذن لي سماحة الشيخ! بأن أقول: ما أعرفه عن هذه التحجيبة؟\nالشيخ: نعم.\nالمقدم: هذه التحجيبة رداء خاص يرتديه إخواتنا المسلمات من الممرضات، وهو كما تفضلتم يلف على الرأس، وأيضًا من تحت الذقن.\nالشيخ: نعم، إذا كان يشق هذا، إذا كان لبسته المرأة على طهارة؛ هذه التحجيبة إذا لبست على طهارة وهي تلف على الرأس والذقن هذا فيه مشقة، فإذا كان على طهارة تمسح عليه، والحمد لله يوم وليلة في حق المقيم، وثلاثة أيام بلياليها في حق المسافر. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18236/هل-يجوز-مسح-المراة-على-التحجيبة-في-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_796/nour_79611.mp3","categories":["فروض الوضوء وصفته"]},{"id":19116,"question":"صفة مسح الرأس؟","title":"صفة مسح الرأس","answer":"الجواب: يمسح رأسه بيديه، يمسح بيديه يقبل بهما ويدبر، يبدأ بمقدمه إلى قفاه ثم يردهما، هذا هو الأفضل. وإن مسح على غير هذه الصفة بأن مسح بيده اليمنى أو بيده اليسرى وعمم أو بيديه من وسط الرأس وعمم لا يضر كله لا يضر يكفي، والحمد لله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18266/صفة-مسح-الراس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_930/nour_93009.mp3","categories":["فروض الوضوء وصفته"]},{"id":19187,"question":"تسأل أختنا أيضًا وتقول: هل يجوز للمرأة أن تمسح رأسها من فوق الملابس التي على رأسها؟","title":"حكم مسح المرأة على الخمار ونحوه أثناء الوضوء","answer":"الجواب: ليس لها ذلك، بل عليها أن تمسح الرأس نفسه، كما أن الرجل يمسح رأسه أيضًا، لكن إن كان عليها خمار قد حنكت به رأسها، ويشق عليها نزعه؛ مسحت عليه يوم وليلة إذا كانت لبسته على طهارة، كالرجل إذا لبس العمامة على طهارة يومًا وليلة، يمسح عليها يوم وليلة بعد الحدث إذا كانت عمامة محنكة؛ لأن حلها قد يشق بعض المشقة، وهكذا الخمار المحنك على المرأة الذي قد ربطته وحنكته على رأسها، ولبسته على طهارة؛ فإنها لها أن تمسح يومًا وليلة كالخفين، كما تمسح على الخفين يوم وليلة كالرجل. أما خمار مطروح على الرأس هكذا عادي فهذا لا يمسح عليه، يزال ويمسح على الرأس أو عمامة لبستها على غير طهارة، لا تمسح عليها؛ تزيلها، أو زاد على الوقت على يوم وليلة تزيلها كالرجل سواء. المقدم: جزاكم الله خيرًا، بعض أخواتنا الطبيبات والممرضات يرتدين ما يسمى لديهن بالتحجيبة، وهذا التحجيبة ينطبق عليها الوصف الذي تفضلتم به وهو أنها تكون من تحت الذقن، وتغطي جميع الرأس، هل لمثل هؤلاء الأخوات أن يمسحن على هذه التحجيبة إذا لبست على الطهارة؟ الشيخ: نعم، إذا لبسنها على طهارة، وكان حلها يعني: مما قد يشق بعض الشيء فإنها تمسح على هذه التحجيبة التي يسمونها خمار محنك. نعم. تمسح عليه إذا كان على طهارة مدة المسح يوم وليلة فقط بعد الحدث يعني ثم تنزعها بعد اليوم والليلة، وأما إن كانت ملبوسة على غير طهارة فإنها لا تمسح عليها. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18372/حكم-مسح-المراة-على-الخمار-ونحوه-اثناء-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_798/nour_79811.mp3","categories":["فروض الوضوء وصفته"]},{"id":19287,"question":"هل التكرار في الوضوء مثلًا، تكرار غسل الوجه ثلاث مرات واجب أم مستحب ؟","title":"حكم التكرار في الوضوء","answer":"الجواب: التكرار سنة مستحب، والواجب مرة، يتمضمض مرة، ويستنشق مرة، ويغسل وجهه مرة وذراعيه مرة مرة ويمسح رأسه وأذنيه مرة ، ويغسل رجله اليمنى مرة مع الكعبين، واليسرى مرة مع الكعبين، هذا الواجب، وقد فعله النبي ﷺ وتوضأ مرة مرة، كما في البخاري في الصحيح، وإن توضأ مرتين مرتين فهذا أفضل من المرة، وإن توضأ ثلاثًا فهي النهاية وهو الكمال .نعم . المقدم: بارك الله فيكم.\nالشيخ: لكن الرأس لا يمسح إلا مرة مطلقًا. المقدم: حتى وإن غسل بقية الأعضاء ثلاث مرات؟\nالشيخ: إلا الرأس فإنه يمسح مرة واحدة، يقبل بيديه ويدبر مرة واحدة؛ لأن هذا هو المحفوظ من فعله ﷺ. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18487/حكم-التكرار-في-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_893/nour_89305.mp3","categories":["فروض الوضوء وصفته"]},{"id":19302,"question":"يسأل أخونا ويقول: هل تجب المضمضة على المتوضىء المحتفظ بوضوئه إذا أكل أو شرب شيئًا ما؟","title":"حكم المضمضة للمتوضئ إذا أكل أو شرب","answer":"الجواب: ما تجب، لكن تستحب، إذا كان فيه دسم أو فيه شيء له رائحة يتمضمض حتى تزول الرائحة الكريهة، أو يزول الدسم الذي قد يؤذيه ويشغله، والنبي ﷺ في بعض الأحيان لما شرب لبنًا تمضمض وقال: إن له دسمًا، فالمضمضة مستحبة إذا دعت الحاجة إليها. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18512/حكم-المضمضة-للمتوضى-اذا-اكل-او-شرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_894/nour_89409.mp3","categories":["فروض الوضوء وصفته"]},{"id":19317,"question":"المستمع محمد مصطفى يقول: رجل رجله مقطوعة من الساق، كيف يكون وضوءه هل يتيمم؟ أم يتوضأ؟ جزاكم الله خيرًا.","title":"كيف يتوضأ من كانت رجله مقطوعة","answer":"الجواب: يغسل الأعضاء الباقية، الوجه واليدين، والرجل الباقية، مع مسح الرأس قبل غسل الرجل ويكفي، أما المقطوعة فلا ولا يلزمه شيء عنها، ما دام مقطوعة فوق الكعب انتهى الموضع، ليس عليه إلا أن يغسل وجهه ويديه مع المرفقين، ثم يمسح رأسه وأذنيه، ثم يغسل الرجل الباقية والحمد لله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18511/كيف-يتوضا-من-كانت-رجله-مقطوعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_739/nour_73913.mp3","categories":["فروض الوضوء وصفته"]},{"id":19496,"question":"يقول السائل: ما حكم الوضوء بماء فيه رائحة الغاز، أو أي رائحة أخرى؟","title":"حكم الوضوء بماء متغير الرائحة","answer":"الجواب: إذا كان الماء فيه الرائحة غير متغير بالنجاسة رائحته ليست بنجاسة فلا حرج في ذلك، إذا كان رائحة غاز أو غيره ما يضر. نعم.","link":"https://binbaz.org.sa/fatwas/18744/حكم-الوضوء-بماء-متغير-الراىحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_939/nour_93926.mp3","categories":["فروض الوضوء وصفته","المياه"]},{"id":19554,"question":"هذه السائلة أختكم (ش. الشمراني) أبها تقول: يا سماحة الشيخ هل صبغ الوجه بالمكياج بالنسبة للمرأة والكريمات السائلة يمنع من وصول الماء للبشرة أثناء الوضوء؟","title":"حكم استعمال ما يمنع وصول الماء للبشرة","answer":"الجواب: الشيء الذي يمنع الماء لا يجوز؛ فإذا مسحت وجهها بشيء لا يمنع الماء فلا بأس، أما شيء يبقى له جسم يمنع الماء لا يجوز، لا في الوجه، ولا في الذراع، ولا في الرجل، بل يجب أن يكون الذراع، والوجه، والقدم خاليًا مما يمنع الماء، فإن استعملت شيئًا ينور الوجه، ويطيب الوجه، ويحسنه لكن ليس له جسم يمنع الماء فلا بأس.","link":"https://binbaz.org.sa/fatwas/18804/حكم-استعمال-ما-يمنع-وصول-الماء-للبشرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_947/nour_94703.mp3","categories":["فروض الوضوء وصفته","اللباس والزينة"]},{"id":19569,"question":"هذا سائل يقول: أفيدونا عن المضمضة والاستنشاق في الوضوء، هل يتمضمض الإنسان، ويستنشق في غرفة واحدة؟ أم يغرف للمضمضة؟ ويغرف للاستنشاق؟ وهل يلزم للمضمضة أن يدخل الإصبع في الفم؟ أم يكتفي بتحريك الماء في الفم؟","title":"صفة المضمضة والاستنشاق","answer":"الجواب: المشروع غرفة واحدة لهما جميعًا، يكرر ثلاثًا كما فعله النبي ﷺ وإن أفرد الفم بغرفة والأنف بغرفة فلا حرج، لكن الأفضل أن يأخذ غرفة يتمضمض منها، ويستنشق منها، ولا يلزم إدخال إصبعه في فمه، إذا أدخل ماء في الفم ثم مجه كفى.","link":"https://binbaz.org.sa/fatwas/18827/صفة-المضمضة-والاستنشاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_947/nour_94717.mp3","categories":["فروض الوضوء وصفته"]},{"id":19576,"question":"المرسلة (م. ع. ف) من القصيم تقول: ما هي سنة الوضوء سماحة الشيخ؟ وكيف يسجد الرجل لسجود السهو؟","title":"صفة الوضوء الشرعي وما يقال عقبه","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه. الوضوء مشروع بأن يتوضأ الإنسان، كما بين الله في كتابه، وكما فعل النبي ﷺ يقول الله جل وعلا: يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا قُمْتُمْ إِلَى الصَّلاةِ فَاغْسِلُوا وُجُوهَكُمْ وَأَيْدِيَكُمْ إِلَى الْمَرَافِقِ وَامْسَحُوا بِرُءُوسِكُمْ وَأَرْجُلَكُمْ إِلَى الْكَعْبَيْنِ [المائدة:6]، هكذا بين الرب للعباد، وهكذا فعل النبي ﷺ. فالسنة في الوضوء إذا قام إليه الإنسان يسمي الله عند بدئه، ثم يغسل كفيه ثلاث مرات، ثم يتمضمض ويستنشق ثلاثًا بثلاث غرفات، ثم يغسل وجهه ثلاثًا هذا هو الأكمل، والواحدة تكفي إذا عم به، لكن التكرار ثلاث أفضل، ثم يغسل ذراعيه ثلاثًا مع المرفقين، هذا هو الكمال، وإن غسلهما مرتين أو واحدة كفى إذا عمم، ثم يمسح رأسه وأذنيه مرة واحدة بالماء، ويدخل إصبعه في أذنيه ويمسح بإبهاميه ظاهر أذنيه، ثم يغسل رجليه مع الكعبين ثلاث مرات، وإن غسلهما مرتين أو مرة كفى إذا عم الرجلين بالغسل، لكن تكراره ثلاثًا أفضل وهو الكمال. وهذا كله بعد الاستنجاء إن كان قد بال أو تغوط لابد من الاستنجاء قبل ذلك، وإن كان ما خرج منه إلا ريح أو مس الفرج أو أكل لحم الإبل أو ما أشبهه هذا يكفي فيه الوضوء، يبدأ بالمضمضة والاستنشاق. أما إذا حصل بول أو غائط يستنجي أولًا، ثم بعد الاستنجاء يتوضأ، يعني: يتمضمض ويستنجي ويغسل وجهه إلى آخره، هذا هو المشروع، وبعد الفراغ يقول: أشهد أن لا إله إلا الله وحده لا شريك له، وأشهد أن محمدًا عبده ورسوله، اللهم اجعلني من التوابين واجعلني من المتطهرين. هذا هو المشروع بعد الوضوء، يقول: أشهد أن لا إله إلا الله وأشهد أن محمدًا عبده ورسوله، اللهم اجعلني من التوابين واجعلني من المتطهرين ويستحب أيضًا أن يقول: سبحانك اللهم وبحمدك أشهد أن لا إله إلا أنت أستغفرك اللهم وأتوب إليك نعم.","link":"https://binbaz.org.sa/fatwas/18835/صفة-الوضوء-الشرعي-وما-يقال-عقبه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_949/nour_94901.mp3","categories":["فروض الوضوء وصفته"]},{"id":19647,"question":"هذا أخونا السائل أبو عبد الرحمن من الرياض، أرسل بمجموعة من الأسئلة يقول: أرجو التكرم بالإجابة عليها من سماحة الشيخ، ما حكم الوضوء للصلاة قبل دخول الوقت؟","title":"حكم الوضوء للصلاة قبل دخول وقتها","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه. أما بعد:\nفلا بأس أن يتوضأ قبل الوقت، كأن يتوضأ العصر ويصلي بها المغرب، أو يتوضأ الظهر ويصلي بها العصر إذا بقيت معه الطهارة، النبي ﷺ كان في بعض الأحيان يصلي عدة أوقات بوضوء واحد، اللهم صل عليه وسلم. نعم. المقدم: أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/18931/حكم-الوضوء-للصلاة-قبل-دخول-وقتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_950/nour_95001.mp3","categories":["فروض الوضوء وصفته"]}]
